tokio::task_local! {
    /// cas-eda0: present while Cassy itself closes a delivery it merged.
    static CASSY_MERGE_CLOSE: ();
}

/// cas-eda0: run `close` as Cassy's own post-merge close. Every ordinary
/// gate still applies; only the supervisor verification skip is withheld.
pub(crate) async fn as_cassy_merge_close<F: std::future::Future>(close: F) -> F::Output {
    CASSY_MERGE_CLOSE.scope((), close).await
}

fn in_cassy_merge_close() -> bool {
    CASSY_MERGE_CLOSE.try_with(|_| ()).is_ok()
}

/// Prefix of every close response that found the task already closed.
pub(crate) const ALREADY_CLOSED_PREFIX: &str = "Already closed:";

fn already_closed_message(task: &Task) -> String {
    let closed_at = task
        .closed_at
        .map(|t| t.format("%Y-%m-%d %H:%M UTC").to_string())
        .unwrap_or_else(|| "unknown time".to_string());
    format!(
        "{ALREADY_CLOSED_PREFIX} {} - {} (closed at {closed_at}). This call did not re-close \
         the task; closed_at and notes were left unchanged.",
        task.id, task.title
    )
}

/// cas-eda0: cross-process exclusive lock for one task's terminal close
/// write. Best effort: if the lock cannot be taken the write proceeds as
/// before, guarded only by the re-read.
fn terminal_close_lock(cas_root: &std::path::Path, task_id: &str) -> Option<std::fs::File> {
    use fs2::FileExt;
    let dir = cas_root.join("locks");
    std::fs::create_dir_all(&dir).ok()?;
    let file = std::fs::OpenOptions::new()
        .create(true)
        .truncate(false)
        .write(true)
        .open(dir.join(format!("task-close-{task_id}.lock")))
        .ok()?;
    match file.lock_exclusive() {
        Ok(()) => Some(file),
        Err(error) => {
            tracing::warn!(%task_id, %error, "terminal close lock unavailable");
            None
        }
    }
}

pub(crate) fn required_verification_type(task_type: TaskType) -> VerificationType {
    if task_type == TaskType::Epic {
        VerificationType::Epic
    } else {
        VerificationType::Task
    }

}

fn delivery_audit_text_is_portable(value: &str) -> bool {
    delivery_audit_text_rejection(value).is_none()
}

pub(crate) fn delivery_audit_text_rejection(value: &str) -> Option<&'static str> {
    if value.chars().any(char::is_control) {
        return Some("contains control characters");
    }
    let lower = value.to_ascii_lowercase();
    if [
        "-----begin private key",
        "-----begin rsa private key",
        "token=",
        "password=",
        "secret=",
        "authorization:",
        "bearer ",
        "sk-",
        "ghp_",
    ]
    .iter()
    .any(|marker| lower.contains(marker))
    {
        return Some("is secret-shaped");
    }
    if value.split_whitespace().any(|token| {
        let token = token.trim_matches(|ch: char| "(),[]{}<>\"'".contains(ch));
        token.starts_with('/')
            || (token.len() >= 3
                && token.as_bytes()[1] == b':'
                && matches!(token.as_bytes()[2], b'/' | b'\\'))
    }) {
        return Some("contains a local absolute path");
    }
    None
}

fn no_code_close_proof<'a>(
    task_id: &str,
    execution_note: Option<&str>,
    external_ref: Option<&'a str>,
    has_reviewable_code: bool,
) -> Result<Option<&'a str>, String> {
    if execution_note != Some("no-code") {
        return Ok(None);
    }
    let proof_reference = external_ref.map(str::trim).filter(|value| !value.is_empty()).ok_or_else(|| {
        format!(
            "⚠️ NO-CODE PROOF REQUIRED\n\nTask {task_id} declares execution_note=no-code, but no external_ref was supplied inline or persisted on the task. Retry close with `{caller}task action=close id={task_id} execution_note=no-code external_ref=<portable-reference>` so the paired metadata is validated before verification dispatch.",
            caller = crate::mcp::tools::core::guidance::caller_prefix(),
        )
    })?;
    if let Some(reason) = delivery_audit_text_rejection(proof_reference) {
        return Err(format!(
            "⚠️ NO-CODE PROOF REQUIRED\n\nTask {task_id} declares execution_note=no-code, but the supplied external_ref {reason}. Retry with `{caller}task action=close id={task_id} execution_note=no-code external_ref=<portable-reference>` so the paired metadata is validated before verification dispatch.",
            caller = crate::mcp::tools::core::guidance::caller_prefix(),
        ));
    }
    if has_reviewable_code {
        return Err(format!(
            "⚠️ NO-CODE INTENT VIOLATED\n\nTask {task_id} declares execution_note=no-code, but its task-attributed branch history contains reviewable code changes. Ask a live registered supervisor to run `{}` to clear the methodology and invalidate the old proof cycle, then complete the ordinary review/merge gates; no-code cannot be used to bypass code delivery proof.",
            super::proof_scope::methodology_recovery_command(task_id, ""),
        ));
    }
    Ok(Some(proof_reference))
}

fn apply_no_code_close_proof(
    task: &mut cas_types::Task,
    inline_external_ref: Option<&str>,
    has_reviewable_code: bool,
) -> Result<(), String> {
    let inline = inline_external_ref.map(str::to_string);
    let persisted = task.external_ref.clone();
    let effective = inline.as_deref().or(persisted.as_deref());
    let proof = no_code_close_proof(
        &task.id,
        task.execution_note.as_deref(),
        effective,
        has_reviewable_code,
    )?;
    if inline.is_some() {
        task.external_ref = proof.map(str::to_string);
    }
    Ok(())
}

/// Validate the close-only no-code correction before any verification or task
/// projection can persist it. The correction is intentionally narrow: an
/// absent methodology may become `no-code`, and an existing `no-code` posture
/// may be repeated, but close cannot rewrite a methodology the verifier may
/// already have approved. The portable proof is part of the same declaration,
/// so both fields reach the pending verification projection together.
fn prepare_no_code_close_metadata(
    task: &mut cas_types::Task,
    inline_execution_note: Option<&str>,
    inline_external_ref: Option<&str>,
) -> Result<(), String> {
    let validated_inline = match inline_execution_note {
        Some(raw) => {
            let validated = crate::mcp::tools::types::validate_execution_note(Some(raw))?;
            if validated.as_deref() != Some("no-code") {
                return Err(format!(
                    "INLINE EXECUTION NOTE REJECTED: task close accepts only execution_note=no-code, paired with a portable external_ref. Record other execution methodologies with `{}task action=update id={} execution_note=<methodology>` before requesting verification.",
                    crate::mcp::tools::core::guidance::caller_prefix(),
                    task.id,
                ));
            }
            if let Some(stored) = task.execution_note.as_deref()
                && stored != "no-code"
            {
                return Err(format!(
                    "INLINE NO-CODE INTENT REJECTED: Task {} already records execution_note={stored}. task close may set no-code only when execution_note is empty or already no-code; it cannot replace a reviewed methodology. Ask a live registered supervisor to run `{}` to correct it and invalidate the old proof cycle, then retry close with portable proof; delivered code still requires ordinary delivery gates.",
                    task.id,
                    super::proof_scope::methodology_recovery_command(&task.id, "no-code"),
                ));
            }
            validated
        }
        None => None,
    };

    let effective_execution_note = validated_inline
        .as_deref()
        .or(task.execution_note.as_deref());
    if effective_execution_note != Some("no-code") {
        return Ok(());
    }

    let inline = inline_external_ref.map(str::to_string);
    let persisted = task.external_ref.clone();
    let effective_external_ref = inline.as_deref().or(persisted.as_deref());
    let proof = no_code_close_proof(&task.id, Some("no-code"), effective_external_ref, false)?
        .map(str::to_string);

    if validated_inline.is_some() {
        task.execution_note = Some("no-code".to_string());
    }
    if inline.is_some() {
        task.external_ref = proof;
    }
    Ok(())
}

/// Words that mark a nearby path as *cited evidence* rather than as subject
/// matter being discussed. Deliberately nouns and reporting verbs — not
/// prepositions like "at"/"in"/"under", which appear in ordinary prose about
/// directories and would re-create the false positive this list exists to fix.
const PROOF_CUE_WORDS: &[&str] = &[
    "artifact",
    "artifacts",
    "evidence",
    "log",
    "logs",
    "output",
    "proof",
    "receipt",
    "receipts",
    "recorded",
    "results",
    "saved",
    "screenshot",
    "screenshots",
    "stored",
    "transcript",
    "written",
];

/// How many tokens before a path are searched for a [`PROOF_CUE_WORDS`] hit.
/// Wide enough for "full transcript saved to <path>", narrow enough that a cue
/// word elsewhere in the same sentence does not reach across a clause.
const PROOF_CUE_WINDOW: usize = 5;

/// Return a durable-proof path under tmpfs **cited as evidence** in a
/// task-close reason.
///
/// This deliberately inspects only the close reason, which workers use to
/// claim their proof. It must not scan task notes: tasks can legitimately
/// discuss `/tmp` (including the incident that introduced this guard), and
/// treating that prose as a close failure would make the gate unusable.
///
/// ROOT CAUSE of cas-8a9e: matching *any* `/tmp/` token did exactly that to the
/// close reason too. Closing cas-647c was rejected because its reason explained
/// why a new temp-skip rule had to be narrow — "every TestEnvGuard fixture HOME
/// is a `/tmp/.tmpXXXX` directory" — while citing its real proof under the
/// durable artifacts root. Nothing ephemeral was ever offered as evidence; the
/// worker had to reword a design rationale to get past a receipt gate. That is
/// the same unclearable-warning shape the surrounding epic is about.
///
/// So a tmpfs path is only a receipt when it is *presented* as one:
/// - a [`PROOF_CUE_WORDS`] hit within [`PROOF_CUE_WINDOW`] tokens before it, or
/// - it opens a line or list item, where a bare path reads as a citation.
///
/// Failing both, the path is still rejected when the reason cites no durable
/// artifact at all — then it is the only evidence on offer, whatever the prose
/// around it says. The guard therefore never gets weaker for a close that has
/// nothing durable behind it, and a genuinely cited tmpfs receipt is caught
/// even when the same reason also names an artifacts-root path.
fn tmpfs_receipt_path_in_close_reason(
    reason: &str,
    artifacts_root: Option<&std::path::Path>,
) -> Option<String> {
    let mut first_tmpfs_path = None;

    for line in reason.lines() {
        let tokens: Vec<&str> = line.split_whitespace().collect();
        let opening = line_opening_token_index(&tokens);
        for (index, token) in tokens.iter().enumerate() {
            let Some(path) = tmpfs_path_token(token) else {
                continue;
            };
            if first_tmpfs_path.is_none() {
                first_tmpfs_path = Some(path.clone());
            }
            let cited_as_proof = opening == Some(index)
                || tokens[index.saturating_sub(PROOF_CUE_WINDOW)..index]
                    .iter()
                    .any(|prior| is_proof_cue(prior));
            if cited_as_proof {
                return Some(path);
            }
        }
    }

    if cites_durable_artifact(reason, artifacts_root) {
        return None;
    }
    first_tmpfs_path
}

/// Strip the punctuation a path picks up from surrounding prose or markup.
///
/// `.` is only trimmed as a single trailing character — sentence punctuation
/// after a cited path — because it is otherwise part of most filenames, and a
/// name that genuinely ends in `.` does not occur in practice. Without this the
/// rejection message quotes `/tmp/run.log.` and the operator cannot tell
/// whether the trailing dot is part of the path it is complaining about.
fn strip_path_punctuation(token: &str) -> &str {
    let trimmed = token.trim_matches(|ch: char| "(),[]{}<>\"'`;:*".contains(ch));
    trimmed.strip_suffix('.').unwrap_or(trimmed)
}

fn tmpfs_path_token(token: &str) -> Option<String> {
    let path = strip_path_punctuation(token);
    (path.starts_with("/tmp/") || path.starts_with("/private/tmp/")).then(|| path.to_string())
}

fn is_proof_cue(token: &str) -> bool {
    let word = token
        .trim_matches(|ch: char| !ch.is_ascii_alphanumeric())
        .to_ascii_lowercase();
    PROOF_CUE_WORDS.contains(&word.as_str())
}

/// Index of the token that opens a line's content once list markers are
/// skipped, so `- /tmp/demo.md` is recognised as a citation.
fn line_opening_token_index(tokens: &[&str]) -> Option<usize> {
    let mut index = 0;
    while index < tokens.len() && is_list_marker(tokens[index]) {
        index += 1;
    }
    (index < tokens.len()).then_some(index)
}

fn is_list_marker(token: &str) -> bool {
    matches!(token, "-" | "*" | "+" | ">" | "•")
        || token
            .strip_suffix('.')
            .or_else(|| token.strip_suffix(')'))
            .is_some_and(|prefix| {
                !prefix.is_empty() && prefix.chars().all(|ch| ch.is_ascii_digit())
            })
}

/// Does the reason name a path under the durable artifacts root?
///
/// Accepts the configured root and the conventional `~/.cas/artifacts/`
/// spelling, because the check only ever *withholds* a fallback rejection —
/// a path genuinely cited as a tmpfs receipt is caught before this runs.
fn cites_durable_artifact(reason: &str, artifacts_root: Option<&std::path::Path>) -> bool {
    let configured = artifacts_root
        .map(|root| root.to_string_lossy().trim_end_matches('/').to_string())
        .filter(|root| !root.is_empty());
    reason.split_whitespace().any(|token| {
        let path = strip_path_punctuation(token);
        if path.starts_with("~/.cas/artifacts/") || path.contains("/.cas/artifacts/") {
            return true;
        }
        configured.as_deref().is_some_and(|root| {
            path.len() > root.len() && path.starts_with(root) && path.as_bytes()[root.len()] == b'/'
        })
    })
}

/// Resolve the durable artifacts root for close-reason inspection. Best
/// effort: an unreadable config simply means the conventional spelling is the
/// only durable citation recognised.
fn close_reason_artifacts_root(cas_root: &std::path::Path) -> Option<std::path::PathBuf> {
    let config = crate::config::Config::load(cas_root).ok()?;
    Some(crate::config::resolved_factory_artifacts_root(
        config.factory().artifacts_root.as_deref(),
    ))
}

/// Validate the optional durable artifact selected for a completion receipt.
///
/// This is deliberately performed before new receipt persistence:
/// receipt metadata is immutable, so accepting an out-of-contract path would
/// make the durable audit record itself misleading. Canonical paths prevent a
/// `..` component or symlink from escaping either the configured root or this
/// task's dedicated directory.
fn validate_completion_artifact_path(
    cas_root: &std::path::Path,
    task_id: &str,
    artifact_path: &str,
) -> Result<(), TaskLifecycleGateError> {
    let reject = |message: String| TaskLifecycleGateError::ArtifactPath { message };
    let mut task_components = std::path::Path::new(task_id).components();
    if !matches!(task_components.next(), Some(std::path::Component::Normal(_)))
        || task_components.next().is_some()
    {
        return Err(reject("artifact task id must be one directory name, not an absolute path or traversal".into()));
    }
    if artifact_path.trim().is_empty() || artifact_path.len() > 4096 {
        return Err(reject(
            "artifact_path must be a non-empty path no longer than 4096 bytes.".to_string(),
        ));
    }
    let artifact_path = std::path::Path::new(artifact_path);
    if !artifact_path.is_absolute() {
        return Err(reject(
            "artifact_path must be an absolute path under the configured [factory] artifacts_root/<project-key>/<task-id>/."
                .to_string(),
        ));
    }

    let config = crate::config::Config::load(cas_root)
        .map_err(|error| reject(format!("could not load [factory] artifacts_root: {error}")))?;
    let configured_root =
        crate::config::resolved_factory_artifacts_root(config.factory().artifacts_root.as_deref());
    let canonical_artifact = artifact_path.canonicalize().map_err(|_| reject(
        "artifact_path must name an existing durable file or directory under configured [factory] artifacts_root/<project-key>/<task-id>/.".to_string()
    ))?;
    let dirs = crate::config::factory_task_artifact_dirs(cas_root, &configured_root, task_id);
    let permitted = dirs
        .iter()
        .filter_map(|dir| crate::config::canonical_factory_task_artifact_dir(&configured_root, dir))
        .any(|dir| canonical_artifact.starts_with(dir));
    if !permitted {
        return Err(reject(format!(
            "artifact_path must resolve beneath this project's [factory] artifacts_root/<project-key>/<task-id>/ ({}), or its legacy artifacts_root/<task-id>/ ({}).",
            dirs[0].display(),
            dirs[1].display()
        )));
    }
    Ok(())
}

