#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TaskCloseDisposition {
    Delivered,
    NegativeResult,
    EvidenceOnly,
    Decision,
}

impl TaskCloseDisposition {
    fn requires_delivery_gates(self) -> bool {
        matches!(self, Self::Delivered)
    }

    fn terminal_outcome(self) -> cas_types::TaskTerminalOutcome {
        match self {
            Self::Delivered => cas_types::TaskTerminalOutcome::Delivered,
            Self::NegativeResult => cas_types::TaskTerminalOutcome::NegativeResult,
            Self::EvidenceOnly => cas_types::TaskTerminalOutcome::EvidenceOnly,
            Self::Decision => cas_types::TaskTerminalOutcome::Decision,
        }
    }
}

pub(super) fn gate_supervisor_authority_error(
    operation: &str,
    error: SupervisorAuthorityError,
) -> String {
    match error {
        SupervisorAuthorityError::Identity(error) => format!(
            "GATE {operation} REJECTED: gate tasks require an authenticated registered supervisor; caller identity could not be resolved ({error})."
        ),
        SupervisorAuthorityError::Store(error) => format!(
            "GATE {operation} REJECTED: supervisor authority could not be checked ({error})."
        ),
        SupervisorAuthorityError::NotRegistered { caller_id, error } => format!(
            "GATE {operation} REJECTED: caller `{caller_id}` is not a registered supervisor ({error})."
        ),
        SupervisorAuthorityError::NotLive(caller) => format!(
            "GATE {operation} REJECTED: only a live registered supervisor may start or close a gate. Caller `{}` has role {}.",
            caller.name, caller.role
        ),
    }
}

fn has_recorded_gate_decision(notes: &str) -> bool {
    notes.lines().any(|line| {
        line.strip_prefix('[')
            .and_then(|line| line.split_once("] ✅ DECISION "))
            .is_some_and(|(_, decision)| !decision.trim().is_empty())
    })
}

fn contains_word(text: &str, word: &str) -> bool {
    text.split(|character: char| !character.is_ascii_alphanumeric())
        .any(|token| token == word)
}

fn proof_field_tokens(field: &str) -> Vec<&str> {
    field
        .split(|character: char| !character.is_ascii_alphanumeric())
        .filter(|token| !token.is_empty())
        .collect()
}

// Keep assignments visible: dropping '=' turns `jobs=16 loops=2` into
// adjacent `16 loops` and lets the loops field borrow the jobs value.
fn proof_numeric_tokens(field: &str) -> Vec<&str> {
    let mut tokens = Vec::new();
    let mut start = None;
    for (index, character) in field.char_indices() {
        if character.is_ascii_alphanumeric() || character == '_' {
            start.get_or_insert(index);
        } else {
            if let Some(start) = start.take() {
                tokens.push(&field[start..index]);
            }
            if matches!(character, '=' | ':') {
                tokens.push(&field[index..index + 1]);
            }
        }
    }
    if let Some(start) = start {
        tokens.push(&field[start..]);
    }
    tokens
}

fn is_proof_numeric_label(token: &str) -> bool {
    matches!(
        token,
        "j" | "jobs"
            | "parallelism"
            | "concurrency"
            | "loop"
            | "loops"
            | "run"
            | "runs"
            | "iteration"
            | "iterations"
            | "time"
            | "times"
    )
}

fn has_adjacent_number<F>(text: &str, label: &str, predicate: F) -> bool
where
    F: Fn(u32) -> bool,
{
    text.split([';', ',', '|']).any(|field| {
        let tokens = proof_numeric_tokens(field);
        let mut owned = vec![false; tokens.len()];
        for (index, token) in tokens.iter().enumerate() {
            if !is_proof_numeric_label(token) {
                continue;
            }
            let number_at = |index: usize| {
                tokens
                    .get(index)
                    .and_then(|token| token.parse::<u32>().ok())
                    .map(|number| (index, number))
            };
            let value = if tokens
                .get(index + 1)
                .is_some_and(|token| matches!(*token, "=" | ":"))
            {
                // Explicit fields take only their own right-hand value.
                number_at(index + 2)
            } else {
                // Prefer an unclaimed preceding prose value ("16 jobs 3
                // loops"). Otherwise consume the following value ("jobs 16
                // loops 3"). A value cannot belong to both labels.
                index
                    .checked_sub(1)
                    .filter(|previous| {
                        !owned[*previous]
                            && !previous
                                .checked_sub(1)
                                .is_some_and(|before| matches!(tokens[before], "=" | ":"))
                    })
                    .and_then(number_at)
                    .or_else(|| number_at(index + 1))
            };
            if let Some((index, number)) = value {
                owned[index] = true;
                if *token == label && predicate(number) {
                    return true;
                }
            }
        }
        false
    })
}

fn has_adjacent_words(text: &str, words: &[&str]) -> bool {
    text.split([';', ',', '|']).any(|field| {
        let tokens = proof_field_tokens(field);
        tokens.windows(words.len()).any(|window| window == words)
    })
}

fn proof_labeled_values(text: &str, label: &str) -> Vec<String> {
    // Keep underscores inside command/test names instead of treating them as
    // field separators. A test named `...failure_cause` is not a result field.
    let mut values = Vec::new();
    for field in text.split([';', ',', '|']) {
        let words = field.split_whitespace().collect::<Vec<_>>();
        for (index, word) in words.iter().enumerate() {
            let word = word.trim_start_matches(['(', '[']);
            let value = if word == label {
                words.get(index + 1).copied()
            } else if let Some(rest) = word
                .strip_prefix(label)
                .and_then(|rest| rest.strip_prefix([':', '=']))
            {
                (!rest.is_empty())
                    .then_some(rest)
                    .or_else(|| words.get(index + 1).copied())
            } else {
                None
            };
            if let Some(value) = value {
                let value = if value == "code" {
                    words.get(index + 2).copied().unwrap_or(value)
                } else if value == "non" && words.get(index + 2).copied() == Some("zero") {
                    "nonzero"
                } else {
                    value
                };
                values.push(value.trim_matches(['(', ')', '[', ']', '.']).to_string());
            }
        }
    }
    values
}

fn has_passing_result(lower: &str) -> bool {
    const SUCCESS: &[&str] = &[
        "pass", "passed", "passing", "success", "successful", "green",
    ];
    const FAILURE: &[&str] = &["fail", "failed", "failure", "error"];
    let results = proof_labeled_values(lower, "result");
    let statuses = proof_labeled_values(lower, "exit")
        .into_iter()
        .chain(proof_labeled_values(lower, "status"))
        .collect::<Vec<_>>();
    let bare = lower.split([';', ',', '|']).map(str::trim).collect::<Vec<_>>();
    if results.iter().any(|result| FAILURE.contains(&result.as_str()))
        || statuses.iter().any(|status| {
            matches!(status.as_str(), "nonzero" | "non-zero")
                || status.parse::<u32>().is_ok_and(|code| code != 0)
        })
        || bare.iter().any(|field| {
            FAILURE.contains(field)
                || SUCCESS.iter().any(|word| {
                    *field == format!("not {word}") || *field == format!("no {word}")
                })
        })
    {
        return false;
    }
    results.iter().any(|result| SUCCESS.contains(&result.as_str()))
        || statuses.iter().any(|status| status == "0")
        || bare.iter().any(|field| SUCCESS.contains(field))
}

fn has_platform_command(lower: &str) -> bool {
    // The command may be from any repository ecosystem. Keep the fallback
    // structured (`command:`/`command=`) so arbitrary prose cannot satisfy the
    // command requirement merely by mentioning the word "command".
    const COMMANDS: &[&str] = &[
        "bazel", "bun", "cargo", "cmake", "deno", "dotnet", "go", "gradle", "java",
        "just", "make", "meson", "mix", "mvn", "node", "npm", "ninja", "pnpm", "pytest",
        "python", "python3", "ruby", "swift", "swiftc", "xcodebuild", "xcrun", "yarn",
    ];
    if COMMANDS
        .iter()
        .any(|command| proof_field_tokens(lower).contains(command))
    {
        return true;
    }

    lower.split([';', ',', '|']).any(|field| {
        ["command:", "command="]
            .iter()
            .find_map(|marker| field.split_once(marker).map(|(_, remainder)| remainder))
            .map(str::trim)
            .and_then(|command| proof_field_tokens(command).first().copied())
            .is_some_and(|command| {
                !matches!(
                    command,
                    "pass" | "passed" | "success" | "successful" | "exit" | "status" | "result"
                )
            })
    })
}

fn has_platform_proof_note(notes: &str) -> bool {
    notes.lines().any(|line| {
        let lower = line.to_ascii_lowercase();
        lower.contains("platform_proof")
            && contains_word(&lower, "macos")
            && has_platform_command(&lower)
            && has_passing_result(&lower)
    })
}

fn has_target_scope(lower: &str) -> bool {
    // Structured Rust scope must still declare the whole target. Non-Rust
    // scope is explicit or uses a named runner; keep all legacy prose forms.
    loaded_proof::has_structured_target_scope(lower) || [
        &["whole", "target"][..],
        &["entire", "target"],
        &["full", "target"],
        &["all", "target"],
        &["non", "rust", "target"],
        &["whole", "suite"],
        &["entire", "suite"],
        &["full", "suite"],
    ]
    .iter()
    .any(|words| has_adjacent_words(lower, words))
}

fn has_parallelism_16(lower: &str) -> bool {
    lower.split([';', ',', '|']).any(|field| {
        let tokens = proof_field_tokens(field);
        tokens.iter().any(|token| *token == "j16")
            || tokens
                .windows(2)
                .any(|window| window[0] == "j" && window[1] == "16")
    }) || has_adjacent_number(lower, "jobs", |number| number == 16)
        || has_adjacent_number(lower, "parallelism", |number| number == 16)
        || has_adjacent_number(lower, "concurrency", |number| number == 16)
}

fn has_at_least_three_runs(lower: &str) -> bool {
    const LABELS: &[&str] = &[
        "loop",
        "loops",
        "run",
        "runs",
        "iteration",
        "iterations",
        "time",
        "times",
    ];
    // A stated low count is decisive even if another token resembles a
    // repetition shorthand, or a later field claims a larger count.
    if lower.split([';', ',', '|']).any(|field| {
        proof_numeric_tokens(field).windows(3).any(|window| {
            LABELS.contains(&window[0])
                && matches!(window[1], "=" | ":")
                && window[2].parse::<u32>().is_ok_and(|number| number < 3)
        })
    }) {
        return false;
    }
    if has_adjacent_words(lower, &["1", "2", "3"]) {
        return true;
    }
    if lower.split([';', ',', '|']).any(|field| {
        let tokens = proof_numeric_tokens(field);
        tokens.iter().enumerate().any(|(index, token)| {
            if token
                .strip_suffix('x')
                .and_then(|number| number.parse::<u32>().ok())
                .is_some_and(|number| number >= 3)
            {
                return true;
            }
            // xN is the receipt's parallelism repetition suffix, not an
            // arbitrary host/architecture token. Keep underscores intact.
            let bound_to_parallelism = index.checked_sub(1).is_some_and(|previous| {
                tokens[previous] == "j16"
                    || (tokens[previous] == "16"
                        && previous.checked_sub(1).is_some_and(|label| {
                            matches!(tokens[label], "j" | "jobs" | "parallelism" | "concurrency")
                                || (matches!(tokens[label], "=" | ":")
                                    && label.checked_sub(1).is_some_and(|label| {
                                        matches!(
                                            tokens[label],
                                            "jobs" | "parallelism" | "concurrency"
                                        )
                                    }))
                        }))
            });
            bound_to_parallelism
                && token
                    .strip_prefix('x')
                    .and_then(|number| number.parse::<u32>().ok())
                    .is_some_and(|number| number >= 3)
        })
    }) {
        return true;
    }

    LABELS.iter().any(|label| {
        has_adjacent_number(lower, label, |number| number >= 3)
            || has_adjacent_words(lower, &["three", label])
    })
}

/// A platform proof is deliberately a typed note rather than an unstructured
/// close-reason claim. The note must identify macOS, a real platform command,
/// and a passing result so a close receipt remains useful after the worker pane
/// is gone.
fn platform_proof_missing_evidence(notes: &str) -> Vec<&'static str> {
    let lines = notes
        .lines()
        .filter(|line| line.to_ascii_lowercase().contains("platform_proof"))
        .collect::<Vec<_>>();
    if lines.is_empty() {
        return vec!["typed note_type=platform_proof"];
    }

    let mut missing = Vec::new();
    if !lines.iter().any(|line| {
        let lower = line.to_ascii_lowercase();
        contains_word(&lower, "macos")
    }) {
        missing.push("macOS marker");
    }
    if !lines.iter().any(|line| has_platform_command(&line.to_ascii_lowercase())) {
        missing.push("recognized platform command (for example cargo or xcodebuild)");
    }
    if !lines.iter().any(|line| has_passing_result(&line.to_ascii_lowercase())) {
        missing.push("passing result (PASS, SUCCESS, exit 0, or status 0)");
    }
    if missing.is_empty() {
        missing.push("all required evidence on the same typed note");
    }
    missing
}

/// A loaded proof must cover the complete target, use 16-way parallelism, and
/// repeat the run at least three times. Rust and non-Rust receipts use the same
/// typed contract while retaining common wording variants.
fn has_loaded_proof_note(notes: &str) -> bool {
    loaded_proof::assess_notes(notes).any(|fields| fields.complete())
}

fn loaded_proof_missing_evidence(notes: &str) -> String {
    loaded_proof::missing_evidence(notes)
}

/// A changed Rust source file as a crate-relative module path:
/// `cas-cli/src/cli/integrate/fs.rs` is crate `cas-cli`, path `cli::integrate::fs`.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
pub(crate) struct SourceModule {
    crate_dir: String,
    segments: Vec<String>,
    /// Actual parent module of a mounted sibling test; display stays physical.
    test_parent: Option<Vec<String>>,
    /// Distinct mounting files when no single parent alias can be trusted.
    ambiguous_test_parents: Vec<String>,
}

impl SourceModule {
    fn display(&self) -> String {
        self.segments.join("::")
    }

    /// Names a proof target may use for this module's crate before its
    /// crate-relative path: the directory, its Rust identifier, `crate`, and the
    /// package name for `*-cli` directories (`cas-cli` is package `cas`).
    fn crate_aliases(&self) -> Vec<String> {
        let mut aliases = vec![
            "crate".to_string(),
            self.crate_dir.clone(),
            self.crate_dir.replace('-', "_"),
        ];
        if let Some(package) = self.crate_dir.strip_suffix("-cli") {
            aliases.push(package.to_string());
        }
        aliases
    }
}

/// Split one proof-target token into lowercase module-path segments. Accepts
/// `a::b`, `a/b`, and file paths such as `cas-cli/src/a/b.rs` or `src/a/mod.rs`.
fn proof_target_segments(token: &str) -> Vec<String> {
    let token = token.trim().to_ascii_lowercase().replace('\\', "/");
    let token = match token.split_once("/src/") {
        Some((_, source)) => source.to_string(),
        None => token.strip_prefix("src/").unwrap_or(&token).to_string(),
    };
    let token = token.strip_suffix(".rs").unwrap_or(&token);
    let token = token.strip_suffix("/mod").unwrap_or(token);
    token
        .replace('/', "::")
        .split("::")
        .filter(|segment| !segment.is_empty())
        .map(str::to_string)
        .collect()
}

/// A proof target covers a module when one of its tokens (command-shaped
/// targets such as `cas --lib rules` or `test(=a::b)` are split into tokens)
/// names the module, an ancestor of it, or a tail of its path:
///
/// * ancestor or equal: `cli::integrate` covers `cli::integrate::fs`;
/// * a full path continued into the file: `cli::integrate::fs::tests`;
/// * a bare or qualified leaf: `fs` and `integrate::fs` cover
///   `cli::integrate::fs`, but `fs::tests` does not, because a leaf followed
///   by more segments names some other module just as plausibly.
///
/// Either form may carry a crate prefix (`cas::cli::integrate`). Unrelated
/// modules never match by substring: `violet_retirement` does not cover `violet`.
/// A sibling test file also accepts its confirmed parent module as an alias.
fn proof_target_matches_module(target: &str, module: &SourceModule) -> bool {
    let paths: Vec<Vec<String>> = std::iter::once(&module.segments)
        .chain(module.test_parent.iter())
        .map(|path| {
            path.iter()
                .map(|segment| segment.to_ascii_lowercase())
                .collect()
        })
        .collect();
    if module.segments.is_empty() {
        return false;
    }
    let aliases = module.crate_aliases();
    target
        .split(|c: char| c.is_whitespace() || "()=,'\"`".contains(c))
        .filter(|token| !token.is_empty() && !token.starts_with('-'))
        .any(|token| {
            let segments = proof_target_segments(token);
            let mut candidates = vec![segments.as_slice()];
            if segments.len() > 1 && aliases.iter().any(|alias| *alias == segments[0]) {
                candidates.push(&segments[1..]);
            }
            candidates.into_iter().any(|segments| {
                !segments.is_empty()
                    && paths.iter().any(|path| {
                        path.starts_with(segments)
                            || segments.starts_with(path)
                            || (1..path.len()).any(|start| segments == &path[start..])
                    })
            })
        })
}

fn scoped_proof_rust_files(root: &std::path::Path) -> Vec<std::path::PathBuf> {
    let mut files = Vec::new();
    let Ok(entries) = std::fs::read_dir(root) else {
        return files;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        if path.is_dir() {
            files.extend(scoped_proof_rust_files(&path));
        } else if path.extension().is_some_and(|extension| extension == "rs") {
            files.push(path);
        }
    }
    files
}

fn scoped_proof_manifest_document(repo: &std::path::Path) -> Option<toml::Value> {
    let manifest = std::fs::read_to_string(repo.join("cas-cli/Cargo.toml")).ok()?;
    toml::from_str::<toml::Value>(&manifest).ok()
}

fn scoped_proof_manifest_test_target(repo: &std::path::Path, path: &str) -> Option<String> {
    let relative = path.strip_prefix("cas-cli/").unwrap_or(path);
    let document = scoped_proof_manifest_document(repo)?;
    document
        .get("test")
        .and_then(toml::Value::as_array)
        .and_then(|tests| {
            tests.iter().find_map(|test| {
                let test_path = test.get("path").and_then(toml::Value::as_str)?;
                (std::path::Path::new(test_path) == std::path::Path::new(relative))
                    .then(|| test.get("name").and_then(toml::Value::as_str))
                    .flatten()
                    .map(str::to_string)
            })
        })
}

fn scoped_proof_cargo_test_target_exists(repo: &std::path::Path, target: &str) -> bool {
    let tests_root = repo.join("cas-cli/tests");
    let document = scoped_proof_manifest_document(repo);
    let auto_targets_enabled = document
        .as_ref()
        .and_then(|document| document.get("package"))
        .and_then(toml::Value::as_table)
        .and_then(|package| package.get("autotests"))
        .and_then(toml::Value::as_bool)
        .is_none_or(|enabled| enabled);
    if auto_targets_enabled
        && (tests_root.join(format!("{target}.rs")).is_file()
            || tests_root.join(target).join("main.rs").is_file())
    {
        return true;
    }

    let Some(document) = document else {
        return false;
    };
    document
        .get("test")
        .and_then(toml::Value::as_array)
        .is_some_and(|tests| {
            tests.iter().any(|test| {
                let Some(name) = test.get("name").and_then(toml::Value::as_str) else {
                    return false;
                };
                if name != target {
                    return false;
                }
                test.get("path")
                    .and_then(toml::Value::as_str)
                    .map_or_else(
                        || {
                            tests_root.join(format!("{target}.rs")).is_file()
                                || tests_root.join(target).join("main.rs").is_file()
                        },
                        |path| repo.join("cas-cli").join(path).is_file(),
                    )
            })
        })
}

/// Use the checkout's authoritative original-stem -> configured harness map.
/// This is inspection only; no Cargo process runs at close.
fn scoped_proof_test_inventory(
    repo: &std::path::Path,
) -> std::collections::BTreeMap<String, String> {
    let helper = repo.join("scripts/cas-test-targets.py");
    if !helper.is_file() {
        return Default::default();
    }
    let package = repo.join("cas-cli");
    let output = std::process::Command::new("python3")
        .arg(&helper)
        .arg(&package)
        .arg("--check")
        .output();
    if !output.is_ok_and(|output| output.status.success()) {
        return Default::default();
    }
    let Ok(output) = std::process::Command::new("python3")
        .arg(helper)
        .arg(package)
        .output()
    else {
        return Default::default();
    };
    if !output.status.success() {
        return Default::default();
    }
    let safe_name = |value: &str| {
        !value.is_empty()
            && value
                .bytes()
                .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'_' | b'-'))
    };
    String::from_utf8_lossy(&output.stdout)
        .lines()
        .filter_map(|line| {
            let (stem, target) = line.split_once('|')?;
            (safe_name(stem) && safe_name(target)).then(|| (stem.to_string(), target.to_string()))
        })
        .collect()
}

fn canonical_scoped_proof_targets(
    repo: &std::path::Path,
    targets: Vec<String>,
) -> Option<Vec<String>> {
    let inventory = scoped_proof_test_inventory(repo);
    let mut canonical = std::collections::BTreeSet::new();
    for target in targets {
        let target = if scoped_proof_cargo_test_target_exists(repo, &target) {
            target
        } else {
            inventory.get(&target)?.clone()
        };
        if !scoped_proof_cargo_test_target_exists(repo, &target) {
            return None;
        }
        canonical.insert(target);
    }
    Some(canonical.into_iter().collect())
}

fn scoped_proof_test_target(repo: &std::path::Path, path: &str) -> Option<String> {
    let relative = path.strip_prefix("cas-cli/tests/")?;
    if let Some(target) = scoped_proof_manifest_test_target(repo, path) {
        return scoped_proof_cargo_test_target_exists(repo, &target).then_some(target);
    }
    let directory = relative.split('/').next()?;
    if !relative.contains('/') {
        let target = std::path::Path::new(relative)
            .file_stem()
            .and_then(|stem| stem.to_str())
            .map(str::to_string)?;
        return scoped_proof_cargo_test_target_exists(repo, &target).then_some(target);
    }

    // Prefer the conventional root (`mcp_tools_test/task/...` belongs to
    // `mcp_tools_test.rs`) before inspecting declarations. This is the same
    // ownership rule as the shell proof checker and avoids decoy strings in a
    // different integration binary claiming a nested module.
    let root = repo.join("cas-cli/tests");
    if scoped_proof_cargo_test_target_exists(repo, directory) {
        return Some(directory.to_string());
    }
    for candidate in scoped_proof_rust_files(&root) {
        if candidate.parent() != Some(root.as_path()) {
            continue;
        }
        let Ok(body) = std::fs::read_to_string(&candidate) else {
            continue;
        };
        let declared_module = body.lines().any(|line| {
            let trimmed = line.trim();
            trimmed == format!("mod {directory};")
                || (trimmed.starts_with("#[path = \"")
                    && trimmed.contains(&format!("{directory}/"))
                    && trimmed.ends_with("\"]"))
        });
        if declared_module
            && let Some(target) = candidate
                .file_stem()
                .and_then(|stem| stem.to_str())
                .filter(|target| scoped_proof_cargo_test_target_exists(repo, target))
        {
            return Some(target.to_string());
        }
    }
    None
}

fn scoped_proof_source_module_path(path: &str) -> Option<String> {
    let relative = path.strip_prefix("cas-cli/src/")?.strip_suffix(".rs")?;
    let relative = relative.strip_suffix("/mod").unwrap_or(relative);
    Some(relative.replace('/', "::"))
}

fn scoped_proof_source_symbols(body: &str) -> Vec<String> {
    let mut symbols = std::collections::BTreeSet::new();
    for line in body.lines() {
        let Some(mut declaration) = line.trim_start().strip_prefix("pub") else {
            continue;
        };
        declaration = declaration.trim_start();
        if declaration.starts_with('(')
            && let Some(end) = declaration.find(')')
        {
            declaration = declaration[end + 1..].trim_start();
        }
        if let Some(rest) = declaration.strip_prefix("async ") {
            declaration = rest;
        }
        let Some(rest) = declaration.strip_prefix("fn ") else {
            let Some(rest) = declaration
                .strip_prefix("struct ")
                .or_else(|| declaration.strip_prefix("enum "))
                .or_else(|| declaration.strip_prefix("const "))
                .or_else(|| declaration.strip_prefix("type "))
            else {
                continue;
            };
            if let Some(symbol) = rest
                .split(|character: char| {
                    !character.is_ascii_alphanumeric() && character != '_'
                })
                .next()
                && !symbol.is_empty()
            {
                symbols.insert(symbol.to_string());
            }
            continue;
        };
        if let Some(symbol) = rest
            .split(|character: char| !character.is_ascii_alphanumeric() && character != '_')
            .next()
            && !symbol.is_empty()
        {
            symbols.insert(symbol.to_string());
        }
    }
    symbols.into_iter().collect()
}

fn scoped_proof_token_reference(line: &str, reference: &str) -> bool {
    line.match_indices(reference).any(|(index, _)| {
        let before = line[..index].chars().next_back();
        let after = line[index + reference.len()..].chars().next();
        let boundary = |character: char| {
            !character.is_ascii_alphanumeric() && character != '_'
        };
        let before_is_boundary = before.is_none_or(boundary);
        let after_is_boundary = if reference.ends_with("::") {
            after.is_some_and(|character| character.is_ascii_alphanumeric() || character == '_')
        } else {
            after.is_none_or(boundary)
        };
        before_is_boundary && after_is_boundary
    })
}

fn scoped_proof_path_reference(body: &str, module_path: &str, source_path: &str) -> bool {
    body.lines().any(|line| {
        let trimmed = line.trim_start();
        if trimmed.starts_with('/') || trimmed.starts_with('*') {
            return false;
        }
        let module_import = (trimmed.starts_with("use ") || trimmed.starts_with("pub use "))
            && scoped_proof_token_reference(trimmed, module_path);
        let qualified_module =
            scoped_proof_token_reference(trimmed, &format!("{module_path}::"));
        module_import
            || qualified_module
            || ((trimmed.contains("include_str!")
                || trimmed.contains("include_bytes!")
                || trimmed.contains("Path")
                || trimmed.contains("read_to_string"))
                && trimmed.contains(source_path))
    })
}

fn scoped_proof_symbol_reference(body: &str, qualified_symbol: &str) -> bool {
    body.lines().any(|line| {
        let trimmed = line.trim_start();
        if trimmed.starts_with('/') || trimmed.starts_with('*') {
            return false;
        }
        scoped_proof_token_reference(trimmed, qualified_symbol)
    })
}

fn scoped_proof_builtin_path(path: &str) -> bool {
    path.starts_with("cas-cli/src/builtins/skills/")
        || path.starts_with("cas-cli/src/builtins/agents/")
        || path.contains("/skills/") && path.starts_with("cas-cli/src/builtins/")
        || path.contains("/agents/") && path.starts_with("cas-cli/src/builtins/")
}

fn add_scoped_proof_target(targets: &mut std::collections::BTreeSet<String>, target: String) {
    if !target.is_empty() {
        targets.insert(target);
    }
}

/// Legacy in-process target resolver for repository fixtures that do not carry
/// the committed surface checker. Real closes use the checker-backed wrapper
/// below so the suggested command cannot drift from the proof guard.
fn legacy_required_scoped_proof_targets(
    repo: &std::path::Path,
    changed_paths: &[String],
) -> Vec<String> {
    let tests_root = repo.join("cas-cli/tests");
    let test_files = scoped_proof_rust_files(&tests_root);
    let mut targets = std::collections::BTreeSet::new();
    let inventory = scoped_proof_test_inventory(repo);
    if repo.join("scripts/cas-test-targets.py").is_file() && inventory.is_empty() {
        // An invalid explicit inventory cannot erase proof coverage. Require
        // every configured harness instead of inventing obsolete suite names.
        return scoped_proof_manifest_document(repo)
            .and_then(|document| {
                document
                    .get("test")
                    .and_then(toml::Value::as_array)
                    .cloned()
            })
            .unwrap_or_default()
            .iter()
            .filter_map(|test| test.get("name").and_then(toml::Value::as_str))
            .filter(|target| scoped_proof_cargo_test_target_exists(repo, target))
            .map(str::to_string)
            .collect();
    }
    let target_for_path = |path: &str| {
        let stem = path
            .strip_prefix("cas-cli/tests/")?
            .split('/')
            .next()?
            .trim_end_matches(".rs");
        inventory
            .get(stem)
            .filter(|target| scoped_proof_cargo_test_target_exists(repo, target))
            .cloned()
            .or_else(|| scoped_proof_test_target(repo, path))
    };

    for path in changed_paths {
        let normalized = path.replace('\\', "/");
        if normalized.starts_with("cas-cli/tests/") {
            if let Some(target) = target_for_path(&normalized) {
                add_scoped_proof_target(&mut targets, target);
            }
            add_scoped_proof_target(&mut targets, "builtin_archive_portability_test".to_string());
        }
        if normalized.starts_with("cas-cli/src/hooks/")
            || normalized.starts_with("cas-cli/src/cli/hook/")
            || normalized == ".codex/hooks.json"
        {
            add_scoped_proof_target(&mut targets, "hook_schema".to_string());
        }
        if !normalized.ends_with(".rs") || !normalized.starts_with("cas-cli/src/") {
            continue;
        }
        let Some(module_path) = scoped_proof_source_module_path(&normalized) else {
            continue;
        };
        let source_file = repo.join(&normalized);
        let Ok(source_body) = std::fs::read_to_string(&source_file) else {
            continue;
        };
        let symbols = scoped_proof_source_symbols(&source_body);
        for test_file in &test_files {
            let Ok(test_body) = std::fs::read_to_string(test_file) else {
                continue;
            };
            let path_reference = scoped_proof_path_reference(&test_body, &module_path, &normalized);
            let symbol_reference = symbols.iter().any(|symbol| {
                let symbol = symbol.strip_prefix("factory_").unwrap_or(symbol);
                scoped_proof_symbol_reference(&test_body, &format!("{module_path}::{symbol}"))
            });
            if !(path_reference || symbol_reference) {
                continue;
            }
            let Some(test_path) = test_file
                .strip_prefix(repo)
                .ok()
                .and_then(|path| path.to_str())
            else {
                continue;
            };
            if let Some(target) = target_for_path(test_path) {
                add_scoped_proof_target(&mut targets, target);
            }
        }
        if scoped_proof_builtin_path(&normalized) {
            add_scoped_proof_target(&mut targets, "builtin_flavor_drift_test".to_string());
            add_scoped_proof_target(&mut targets, "agent_definition_contract_test".to_string());
            add_scoped_proof_target(&mut targets, "factory_codex_skill_guardrails".to_string());
            for test_file in &test_files {
                let Some(name) = test_file.file_name().and_then(|name| name.to_str()) else {
                    continue;
                };
                if name.starts_with("builtin_") {
                    add_scoped_proof_target(&mut targets, name.trim_end_matches(".rs").to_string());
                }
            }
        }
    }
    targets
        .into_iter()
        .map(|target| inventory.get(&target).cloned().unwrap_or(target))
        .filter(|target| scoped_proof_cargo_test_target_exists(repo, target))
        .collect::<std::collections::BTreeSet<_>>()
        .into_iter()
        .collect()
}

/// Ask the committed surface checker for the same integration-target mapping
/// used by `scripts/run-scoped-tests.sh`. The close gate used to carry a
/// second Rust implementation of that mapping; it drifted from the checker
/// and suggested an eight-target command for a diff the checker required to
/// run with eleven targets. Keep the small in-process resolver as a fixture
/// fallback for unit tests that intentionally build a repository without the
/// project scripts, but all real repository closes use the checker as the
/// authority.
#[derive(Debug, Default)]
struct ScopedProofTargetCache {
    entries: std::collections::HashMap<ScopedProofTargetCacheKey, Result<Vec<String>, String>>,
}

#[derive(Debug, Hash, PartialEq, Eq)]
struct ScopedProofTargetCacheKey {
    proof_repo: std::path::PathBuf,
    target_repo: std::path::PathBuf,
    changed_paths: Vec<String>,
}

fn scoped_proof_changed_path_set(changed_paths: &[String]) -> Vec<String> {
    let mut paths = changed_paths
        .iter()
        .map(|path| path.replace('\\', "/"))
        .collect::<Vec<_>>();
    paths.sort();
    paths.dedup();
    paths
}

fn proof_repo_is_git_worktree(repo: &std::path::Path) -> bool {
    std::process::Command::new("git")
        .args(["rev-parse", "--is-inside-work-tree"])
        .current_dir(repo)
        .output()
        .is_ok_and(|output| output.status.success() && output.stdout == b"true\n")
}

/// cas-74cb: one surface-checker run may take no longer than this. The
/// checker walks every changed path; for cas-f0c7's 1228-path epic range it
/// ran 38 s, and the close spawned it twice with no bound, so the MCP call
/// exceeded its 55 s deadline with an unknown mutation outcome.
const SCOPED_SURFACE_CHECK_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(15);

/// `Err` only when the checker ran past its bound: the close refuses rather
/// than guess the required targets. Any other checker failure keeps the
/// established in-process fallback.
fn required_scoped_proof_targets(
    proof_repo: &std::path::Path,
    target_repo: &std::path::Path,
    changed_paths: &[String],
    cache: &mut ScopedProofTargetCache,
) -> Result<Vec<String>, String> {
    let normalized_paths = scoped_proof_changed_path_set(changed_paths);
    let key = ScopedProofTargetCacheKey {
        proof_repo: proof_repo.to_path_buf(),
        target_repo: target_repo.to_path_buf(),
        changed_paths: normalized_paths.clone(),
    };
    if let Some(targets) = cache.entries.get(&key) {
        return targets.clone();
    }

    let targets = resolve_scoped_proof_targets_without_cache(
        proof_repo,
        target_repo,
        &normalized_paths,
        SCOPED_SURFACE_CHECK_TIMEOUT,
    );
    cache.entries.insert(key, targets.clone());
    targets
}

/// Run the surface checker under a deadline. Its process group is reaped on
/// timeout, so a stuck checker cannot outlive the close (cas-74cb).
fn run_scoped_surface_checker(
    command: &mut std::process::Command,
    stdin: std::process::Stdio,
    timeout: std::time::Duration,
) -> Result<std::process::Output, crate::bounded_process::BoundedCommandError> {
    crate::bounded_process::run_command_with_stdin(
        command,
        crate::bounded_process::Deadline::after(timeout),
        timeout,
        stdin,
    )
}

fn resolve_scoped_proof_targets_without_cache(
    proof_repo: &std::path::Path,
    target_repo: &std::path::Path,
    changed_paths: &[String],
    timeout: std::time::Duration,
) -> Result<Vec<String>, String> {
    // The worker checkout owns the delivery diff, while the task's target
    // repository is the durable location for project tooling. Keep the
    // checker path tied to the declared target so an installed Cassy binary
    // does not reach back into its build checkout; run it from the worker
    // checkout so its relative source/test lookups describe that diff.
    let checker = target_repo.join("scripts/check-scoped-test-surface.sh");
    // The checker is an inspection helper, not a substitute for repository
    // resolution. In-process fallback is the safe path for lightweight
    // stores, installed binaries without a checkout, and any checker failure.
    if proof_repo_is_git_worktree(proof_repo) && checker.is_file() {
        // A file, not a pipe, carries the path list: writing a large request
        // cannot block, and the bounded runner owns the whole lifetime.
        let input = tempfile::tempfile().ok().and_then(|mut input| {
            use std::io::{Seek, Write};
            if !changed_paths.is_empty() {
                writeln!(input, "{}", changed_paths.join("\n")).ok()?;
            }
            input.rewind().ok()?;
            Some(input)
        });
        if let Some(input) = input {
            let mut command = std::process::Command::new("bash");
            command
                .arg(&checker)
                .args([
                    "--resolve-targets",
                    "--base",
                    "HEAD",
                    "--paths-from-stdin",
                    "--",
                ])
                .current_dir(proof_repo);
            match run_scoped_surface_checker(&mut command, std::process::Stdio::from(input), timeout) {
                Ok(output) if output.status.success() => {
                    if let Some(canonical) =
                        parse_scoped_proof_target_args(&String::from_utf8_lossy(&output.stdout))
                            .and_then(|targets| canonical_scoped_proof_targets(proof_repo, targets))
                    {
                        return Ok(canonical);
                    }
                }
                Ok(_) | Err(crate::bounded_process::BoundedCommandError::Io) => {}
                Err(crate::bounded_process::BoundedCommandError::TimedOut) => {
                    tracing::warn!(
                        checker = %checker.display(),
                        changed_paths = changed_paths.len(),
                        timeout_secs = timeout.as_secs_f64(),
                        "cas-74cb: scoped-proof surface checker exceeded its bound"
                    );
                    return Err(format!(
                        "SCOPED PROOF SURFACE UNRESOLVED: `{}` did not finish within {:.0}s for {} changed path(s), so the close refused rather than guess which proof targets this diff requires. Retry once the host is less loaded, or close a narrower delivery.",
                        checker.display(),
                        timeout.as_secs_f64(),
                        changed_paths.len(),
                    ));
                }
            }
        }
    }

    Ok(legacy_required_scoped_proof_targets(proof_repo, changed_paths))
}

/// The `--test` targets on the checker's `SCOPED_PROOF_TARGET_ARGS:` line.
fn parse_scoped_proof_target_args(stdout: &str) -> Option<Vec<String>> {
    let line = stdout
        .lines()
        .find(|line| line.starts_with("SCOPED_PROOF_TARGET_ARGS:"))?;
    let mut targets = Vec::new();
    let mut tokens = line.split_whitespace().skip(1);
    while let Some(token) = tokens.next() {
        if token == "--test"
            && let Some(target) = tokens.next()
        {
            targets.push(target.to_string());
        }
    }
    Some(targets)
}

/// cas-0db7: the `--test` targets `run-scoped-tests.sh --proof` will itself
/// require when run with this base. `--proof` validation hands the committed
/// surface checker the whole `merge-base(base, HEAD)..HEAD` diff, while the
/// gate resolves only the task's attributed paths. When a neighbour's commit
/// sits in that range (a skill or hook edit, say), the proof needs more
/// targets than the gate's own list, and a refusal that suggested only the
/// gate's list sent the closer into a full run that then failed as
/// "SCOPED PROOF INCOMPLETE". Same checker, same arguments as `--proof`.
fn proof_validation_targets(
    proof_repo: &std::path::Path,
    target_repo: &std::path::Path,
    base: Option<&str>,
) -> Option<Vec<String>> {
    proof_validation_targets_within(proof_repo, target_repo, base, SCOPED_SURFACE_CHECK_TIMEOUT)
}

/// The suggestion is advisory: past its bound it adds nothing (cas-74cb).
fn proof_validation_targets_within(
    proof_repo: &std::path::Path,
    target_repo: &std::path::Path,
    base: Option<&str>,
    timeout: std::time::Duration,
) -> Option<Vec<String>> {
    let checker = target_repo.join("scripts/check-scoped-test-surface.sh");
    if !proof_repo_is_git_worktree(proof_repo) || !checker.is_file() {
        return None;
    }
    let mut command = std::process::Command::new("bash");
    command.arg(&checker).arg("--resolve-targets");
    if let Some(base) = base {
        command.args(["--base", base]);
    }
    command.arg("--").current_dir(proof_repo);
    let output = run_scoped_surface_checker(&mut command, std::process::Stdio::null(), timeout).ok()?;
    if !output.status.success() {
        return None;
    }
    canonical_scoped_proof_targets(
        proof_repo,
        parse_scoped_proof_target_args(&String::from_utf8_lossy(&output.stdout))?,
    )
}

/// cas-0db7: the command a scoped-proof refusal suggests. Its `--test` list
/// is the gate's required targets plus every target `--proof` validation will
/// require for the same base, so running it exactly as printed passes both.
fn suggested_scoped_proof_command(
    required_targets: &[String],
    proof_repo: &std::path::Path,
    target_repo: &std::path::Path,
    base: Option<&str>,
) -> String {
    // A persisted requirement or older caller may still name source suites.
    // Resolve those against the delivered checkout before printing Cargo flags.
    let Some(mut targets) = canonical_scoped_proof_targets(proof_repo, required_targets.to_vec())
    else {
        return "SCOPED PROOF SURFACE UNRESOLVED: required integration suites cannot be mapped to existing Cargo test targets; repair the checkout's test inventory before requesting a proof".to_string();
    };
    for target in proof_validation_targets(proof_repo, target_repo, base).unwrap_or_default() {
        if !targets.contains(&target) {
            targets.push(target);
        }
    }
    scoped_proof_command(&targets, base)
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ScopedProofReceipt {
    targets: String,
    base: Option<String>,
    /// The tip the proof ran at, when the runner recorded it (cas-a9a1).
    head: Option<String>,
}

fn scoped_proof_receipt_field(line: &str, field: &str) -> Option<String> {
    let lower = line.to_ascii_lowercase();
    let start = lower.find(&field.to_ascii_lowercase())? + field.len();
    let value = line[start..].split_whitespace().next()?;
    let value = value.trim_matches(|character: char| ",;)]}".contains(character));
    (!value.is_empty()).then(|| value.to_string())
}

fn scoped_proof_note_receipt(notes: &str) -> Option<ScopedProofReceipt> {
    // A later proof note may supersede an earlier partial receipt after a
    // supervisor expands the required target set. Keep the latest passing
    // receipt so close does not revalidate stale scope forever.
    notes
        .lines()
        .filter_map(|line| {
            if let Some(receipt) = scoped_proof_receipt_file(line) {
                return Some(receipt);
            }
            let lower = line.to_ascii_lowercase();
            if !lower.contains("scoped_proof") || !lower.contains("result=pass") {
                return None;
            }
            // cas-2664: `run-scoped-tests.sh --proof` prints two passing
            // lines: the surface checker's `targets=` line and its own
            // `command=… result=PASS base=… head=…` line. Accept either; the
            // command's `--test` arguments name the targets it ran, and the
            // script prints it only after surface validation passed.
            let targets = line
                .split_once("targets=")
                .or_else(|| line.split_once("command="))?
                .1;
            let targets = targets
                .split_once("result=")
                .map_or(targets, |(value, _)| value);
            let targets = targets
                .split_once("base=")
                .map_or(targets, |(value, _)| value);
            let targets = targets.trim().to_string();
            let base = ["SCOPED_PROOF_BASE=", "base_sha=", "base="]
                .into_iter()
                .find_map(|field| scoped_proof_receipt_field(line, field));
            let head = ["head_sha=", "head="]
                .into_iter()
                .find_map(|field| scoped_proof_receipt_field(line, field));
            Some(ScopedProofReceipt {
                targets,
                base,
                head,
            })
        })
        .last()
}

/// cas-2664: a receipt for many targets is longer than one task note allows,
/// so a note may cite the file `run-scoped-tests.sh --proof` writes instead:
/// `SCOPED_PROOF_RECEIPT: id=sp-<sha256> path=<file>`. The file is accepted
/// only when its `receipt_id` matches the cited id and the SHA-256 of its
/// payload, so an edited file or a mismatched citation proves nothing.
fn scoped_proof_receipt_file(line: &str) -> Option<ScopedProofReceipt> {
    use sha2::Digest;

    let rest = &line[line.find("SCOPED_PROOF_RECEIPT:")? + "SCOPED_PROOF_RECEIPT:".len()..];
    let cited_id = scoped_proof_receipt_field(rest, "id=")?;
    let path = scoped_proof_receipt_field(rest, "path=")?;
    let content = std::fs::read_to_string(&path).ok()?;
    let id_line_start = content.find("\nreceipt_id=")? + 1;
    let payload = &content[..id_line_start];
    let file_id = content[id_line_start + "receipt_id=".len()..].lines().next()?.trim();
    let digest = sha2::Sha256::digest(payload.as_bytes());
    let computed = format!(
        "sp-{}",
        digest.iter().map(|byte| format!("{byte:02x}")).collect::<String>()
    );
    if file_id != cited_id || computed != cited_id {
        return None;
    }
    let field = |name: &str| {
        payload
            .lines()
            .find_map(|entry| entry.strip_prefix(name))
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(str::to_string)
    };
    if field("result=").as_deref() != Some("PASS") {
        return None;
    }
    Some(ScopedProofReceipt {
        targets: field("targets=")?,
        base: field("base_sha="),
        head: field("head_sha="),
    })
}

fn scoped_proof_note_targets(notes: &str) -> Option<String> {
    scoped_proof_note_receipt(notes).map(|receipt| receipt.targets)
}

fn scoped_proof_note_base(notes: &str) -> Option<String> {
    scoped_proof_note_receipt(notes).and_then(|receipt| receipt.base)
}

fn scoped_proof_note_head(notes: &str) -> Option<String> {
    scoped_proof_note_receipt(notes).and_then(|receipt| receipt.head)
}

fn scoped_proof_base_matches(proof_repo: &std::path::Path, actual: &str, expected: &str) -> bool {
    if actual == expected {
        return true;
    }
    if actual.len() < 4
        || actual.len() > 40
        || !actual.bytes().all(|byte| byte.is_ascii_hexdigit())
    {
        return false;
    }
    let Ok(output) = std::process::Command::new("git")
        .args(["rev-parse", "--verify", "--quiet", &format!("{actual}^{{commit}}")])
        .current_dir(proof_repo)
        .output()
    else {
        return false;
    };
    output.status.success() && String::from_utf8_lossy(&output.stdout).trim() == expected
}

fn scoped_proof_note_covers(notes: &str, required_targets: &[String]) -> Vec<String> {
    let Some(receipt) = scoped_proof_note_targets(notes) else {
        return required_targets.to_vec();
    };
    let normalized = receipt.to_ascii_lowercase();
    required_targets
        .iter()
        .filter(|target| {
            let target = target.to_ascii_lowercase();
            !normalized
                .split(|character: char| !character.is_ascii_alphanumeric() && character != '_')
                .any(|token| token == target)
        })
        .cloned()
        .collect()
}

fn scoped_proof_command(required_targets: &[String], base: Option<&str>) -> String {
    let prefix = base
        .map(|base| format!("SCOPED_PROOF_BASE={base} "))
        .unwrap_or_default();
    format!(
        "{prefix}scripts/run-scoped-tests.sh --proof -p cas --lib --test {}",
        required_targets.join(" --test ")
    )
}

#[derive(Debug, PartialEq, Eq)]
struct FailedScopedRun {
    failures: std::collections::BTreeSet<String>,
    tests_run: usize,
    platform: String,
}

fn compare_failed_scoped_runs(
    base: &FailedScopedRun,
    delivery: &FailedScopedRun,
) -> Result<(), String> {
    if base.platform != delivery.platform {
        return Err(format!(
            "base and delivery ran on different platforms: {} vs {}",
            base.platform, delivery.platform
        ));
    }
    let new_failures: Vec<_> = delivery
        .failures
        .difference(&base.failures)
        .cloned()
        .collect();
    if !new_failures.is_empty() {
        return Err(format!(
            "delivery-only failing tests block close: {}",
            new_failures.join(", ")
        ));
    }
    Ok(())
}

fn parse_failed_scoped_run(
    log: &str,
    expected_head: &str,
    expected_base: &str,
    expected_command: &str,
) -> Result<FailedScopedRun, String> {
    // The runner preserves nextest's raw log for diagnosis. Match against the
    // same ANSI-free view that its own success/failure guard uses.
    let ansi = regex::Regex::new(r"\x1b\[[0-9;]*[A-Za-z]")
        .map_err(|error| format!("cannot parse scoped log colors: {error}"))?;
    let clean_log = ansi.replace_all(log, "");
    let log = clean_log.as_ref();
    let header = log
        .lines()
        .find(|line| line.starts_with("SCOPED_RUN: "))
        .ok_or("missing SCOPED_RUN header")?;
    for (field, expected) in [
        ("version=", "1"),
        ("head=", expected_head),
        ("base=", expected_base),
        ("runner=", "nextest_run"),
    ] {
        if scoped_proof_receipt_field(header, field).as_deref() != Some(expected) {
            return Err(format!("SCOPED_RUN {field} does not match the delivery"));
        }
    }
    if header.split_once(" command=").map(|(_, command)| command) != Some(expected_command) {
        return Err("SCOPED_RUN command differs from the required scoped command".into());
    }
    let platform = scoped_proof_receipt_field(header, "platform=")
        .filter(|platform| platform.contains('/') && platform.split_whitespace().count() == 1)
        .ok_or("SCOPED_RUN platform is missing")?;
    let exit = log
        .lines()
        .find_map(|line| line.strip_prefix("SCOPED_RUN_RESULT: cargo_exit="))
        .and_then(|exit| exit.parse::<i32>().ok())
        .ok_or("missing scoped cargo exit status")?;
    if exit == 0 {
        return Err("base-red comparison requires a failed test run".into());
    }
    let summary = log
        .lines()
        .filter(|line| line.trim_start().starts_with("Summary ["))
        .last()
        .ok_or("missing nextest summary; a build failure is not a base-red test result")?;
    let summary = summary.trim();
    let run = summary
        .split_once(" run: ")
        .ok_or("malformed nextest summary")?;
    let tests_run = run
        .0
        .split_whitespace()
        .rev()
        .nth(1)
        .and_then(|count| count.parse::<usize>().ok())
        .ok_or("malformed nextest test count")?;
    let reported_failed = run
        .1
        .split(',')
        .find_map(|part| {
            let mut words = part.split_whitespace();
            let count = words.next()?.parse::<usize>().ok()?;
            (words.next() == Some("failed")).then_some(count)
        })
        .ok_or("nextest summary does not report failed tests")?;
    let failures: std::collections::BTreeSet<String> = log
        .lines()
        .filter_map(|line| {
            let line = line.trim_start();
            line.starts_with("FAIL [")
                .then(|| line.split_once(") ").map(|(_, name)| name.trim().to_string()))
                .flatten()
        })
        .collect();
    if tests_run == 0 || reported_failed == 0 || failures.len() != reported_failed {
        return Err(format!(
            "nextest failure list is incomplete: {tests_run} tests run, {reported_failed} reported failed, {} identified",
            failures.len()
        ));
    }
    Ok(FailedScopedRun {
        failures,
        tests_run,
        platform,
    })
}

fn read_task_scoped_log(
    cas_root: &std::path::Path,
    task_id: &str,
    path: &str,
) -> Result<String, String> {
    validate_completion_artifact_path(cas_root, task_id, path)
        .map_err(|error| format!("scoped log path rejected: {error}"))?;
    let path = std::path::Path::new(path);
    let metadata =
        std::fs::metadata(path).map_err(|error| format!("scoped log unreadable: {error}"))?;
    if !metadata.is_file() || metadata.len() > 32 * 1024 * 1024 {
        return Err("scoped log must be a file no larger than 32 MiB".into());
    }
    std::fs::read_to_string(path).map_err(|error| format!("scoped log unreadable: {error}"))
}

fn validate_inherited_scoped_failures(
    task: &Task,
    cas_root: &std::path::Path,
    proof_repo: &std::path::Path,
    expected_base: Option<&str>,
    required_targets: &[String],
) -> Result<String, String> {
    let expected_base = expected_base.ok_or("delivery has no attributable scoped proof base")?;
    let note = task
        .notes
        .lines()
        .filter(|line| line.contains("SCOPED_BASE_RED:"))
        .last()
        .ok_or("add a progress note with SCOPED_BASE_RED: base_log=<durable path> delivery_log=<durable path> after running the same scoped command at the base and delivery; a registered supervisor must close with supervisor_override=true")?;
    let base_path = scoped_proof_receipt_field(note, "base_log=").ok_or("missing base_log")?;
    let delivery_path =
        scoped_proof_receipt_field(note, "delivery_log=").ok_or("missing delivery_log")?;
    if base_path == delivery_path {
        return Err("base and delivery logs must be distinct".into());
    }
    let head = std::process::Command::new("git")
        .args(["rev-parse", "HEAD"])
        .current_dir(proof_repo)
        .output()
        .map_err(|error| format!("cannot resolve delivery HEAD: {error}"))?;
    if !head.status.success() {
        return Err("cannot resolve delivery HEAD".into());
    }
    let head = String::from_utf8_lossy(&head.stdout).trim().to_string();
    let command = scoped_proof_command(required_targets, None);
    let base_log = read_task_scoped_log(cas_root, &task.id, &base_path)?;
    let delivery_log = read_task_scoped_log(cas_root, &task.id, &delivery_path)?;
    use sha2::Digest;
    let base_digest = hex::encode(sha2::Sha256::digest(base_log.as_bytes()));
    let delivery_digest = hex::encode(sha2::Sha256::digest(delivery_log.as_bytes()));
    let base = parse_failed_scoped_run(&base_log, expected_base, expected_base, &command)?;
    let delivery = parse_failed_scoped_run(&delivery_log, &head, expected_base, &command)?;
    compare_failed_scoped_runs(&base, &delivery)?;
    Ok(format!(
        "SCOPED_BASE_RED accepted for base={expected_base}, head={head}, command={command}; base: {} failed / {} run ({base_path}, sha256={base_digest}); delivery: {} failed / {} run ({delivery_path}, sha256={delivery_digest}); every delivery failure was present at base",
        base.failures.len(),
        base.tests_run,
        delivery.failures.len(),
        delivery.tests_run,
    ))
}

/// Mount discovery is local to one changed-source batch: each directory is
/// listed once and each candidate parent is read/parsed once with one parser.
struct SiblingTestParents {
    parser: Option<cas_code::parser::RustParser>,
    directories: std::collections::BTreeMap<std::path::PathBuf, Vec<std::path::PathBuf>>,
    mounts: std::collections::BTreeMap<std::path::PathBuf, Vec<std::path::PathBuf>>,
}

impl SiblingTestParents {
    fn new() -> Self {
        Self {
            parser: cas_code::parser::RustParser::new().ok(),
            directories: Default::default(),
            mounts: Default::default(),
        }
    }

    /// Resolve a sibling only through an explicit AST mount whose canonical
    /// target is the changed file. Comments and lookalike names prove nothing.
    fn parents(&mut self, proof_repo: &std::path::Path, path: &str) -> Option<Vec<String>> {
        let file = std::path::Path::new(path);
        let parent_name = file.file_stem()?.to_str()?.strip_suffix("_tests")?;
        if parent_name.is_empty() {
            return None;
        }
        let directory = file.parent()?;
        let changed_file = proof_repo.join(file).canonicalize().ok()?;
        let parser = self.parser.as_mut()?;
        let candidates = self
            .directories
            .entry(directory.to_path_buf())
            .or_insert_with(|| {
                let mut candidates: Vec<_> = std::fs::read_dir(proof_repo.join(directory))
                    .into_iter()
                    .flatten()
                    .filter_map(Result::ok)
                    .map(|entry| directory.join(entry.file_name()))
                    .filter(|path| path.extension().is_some_and(|extension| extension == "rs"))
                    .collect();
                candidates.sort();
                candidates
            });
        // A parent beside the test directory can mount directory/*_tests.rs.
        let adjacent_parent = directory.parent()?
            .join(format!("{}.rs", directory.file_name()?.to_str()?));
        let mut parents = std::collections::BTreeSet::new();
        // Keep conventional foo/mod.rs mounts, including ../foo_tests.rs.
        for parent in candidates
            .iter()
            .cloned()
            .chain(std::iter::once(directory.join(parent_name).join("mod.rs")))
            .chain(std::iter::once(adjacent_parent))
        {
            if parent == file {
                continue;
            }
            let mounts = self.mounts.entry(parent.clone()).or_insert_with(|| {
                let absolute = proof_repo.join(&parent);
                let Some(directory) = absolute.parent() else {
                    return Vec::new();
                };
                std::fs::read_to_string(&absolute)
                    .ok()
                    .and_then(|body| parser.explicit_external_modules(&body).ok())
                    .unwrap_or_default()
                    .into_iter()
                    .filter_map(|(_name, relative)| directory.join(relative).canonicalize().ok())
                    .collect()
            });
            if !mounts.contains(&changed_file) {
                continue;
            }
            parents.insert(parent.to_str()?.replace('\\', "/"));
        }
        Some(parents.into_iter().collect())
    }
}

/// Convert changed Rust source paths into crate-relative module paths that
/// proof targets are matched against. Non-source files do not require a
/// library proof target; `mod.rs` names its directory's module. Mounted test
/// siblings keep their physical names for receipts and diagnostics, with an
/// additional Rust module path used only for declaration matching.
pub(crate) fn changed_source_modules(
    proof_repo: &std::path::Path,
    paths: &[String],
) -> Vec<SourceModule> {
    let mut modules = std::collections::BTreeSet::new();
    let mut sibling_tests = None;
    for path in paths {
        let normalized = path.replace('\\', "/");
        let Some((crate_path, source)) = normalized.split_once("/src/") else {
            continue;
        };
        let Some(source) = source.strip_suffix(".rs") else {
            continue;
        };
        let source = source.strip_suffix("/mod").unwrap_or(source);
        let parents = if normalized.ends_with("_tests.rs") {
            sibling_tests
                .get_or_insert_with(SiblingTestParents::new)
                .parents(proof_repo, &normalized)
                .unwrap_or_default()
        } else {
            Vec::new()
        };
        let test_parent = if let [parent] = parents.as_slice() {
            parent.split_once("/src/")
                .and_then(|(_, source)| source.strip_suffix(".rs"))
                .map(|source| {
                    source.strip_suffix("/mod").unwrap_or(source)
                        .split('/').map(str::to_string).collect()
                })
        } else {
            None
        };
        modules.insert(SourceModule {
            crate_dir: crate_path
                .rsplit('/')
                .next()
                .unwrap_or(crate_path)
                .to_ascii_lowercase(),
            segments: source.split('/').map(str::to_string).collect(),
            test_parent,
            ambiguous_test_parents: if parents.len() > 1 {
                parents
            } else {
                Vec::new()
            },
        });
    }
    modules.into_iter().collect()
}

/// cas-d6eb: the tested packages covering every proof target a widening adds,
/// when each is crate-qualified and tested at `head` in `repo`.
pub(crate) fn receipts_cover_targets(
    cas_root: &std::path::Path,
    repo: &std::path::Path,
    head: &str,
    added: &[String],
) -> Option<Vec<String>> {
    receipt_scope::receipts_cover_targets(cas_root, repo, head, added)
}

/// Return the source modules (crate-relative `a::b` paths) absent from the
/// declared close proof scope.
pub(crate) fn uncovered_blast_radius_modules(
    proof_repo: &std::path::Path,
    changed_paths: &[String],
    proof_targets: &[String],
) -> Vec<String> {
    uncovered_blast_radius_scope(proof_repo, changed_paths, proof_targets).0
}

/// Keep proof-target module names separate from explanatory mount diagnostics.
fn uncovered_blast_radius_scope(
    proof_repo: &std::path::Path,
    changed_paths: &[String],
    proof_targets: &[String],
) -> (Vec<String>, String) {
    let proof_targets = cas_types::normalize_proof_targets(proof_targets);
    let mut uncovered = Vec::new();
    let mut ambiguities = Vec::new();
    for module in changed_source_modules(proof_repo, changed_paths) {
        let covered = proof_targets
            .iter()
            .any(|target| proof_target_matches_module(target, &module));
        let name = module.display();
        if !covered && !uncovered.contains(&name) {
            if !module.ambiguous_test_parents.is_empty() {
                ambiguities.push(format!(
                    "{name} (mounting parents: {})",
                    module.ambiguous_test_parents.join(", "),
                ));
            }
            uncovered.push(name);
        }
    }
    let notice = if ambiguities.is_empty() {
        String::new()
    } else {
        format!(
            "; ambiguous test mounts: {}. Declare the physical test module explicitly",
            ambiguities.join("; "),
        )
    };
    (uncovered, notice)
}

fn proof_targets_scope_fix_command(task: &Task, uncovered: &[String]) -> String {
    let mut targets = cas_types::normalize_proof_targets(&task.proof_targets);
    for module in uncovered {
        if !targets.iter().any(|target| target == module) {
            targets.push(module.clone());
        }
    }
    format!(
        "A crate the worker tested is covered without a scope fix (cas-b38a): run a capped targeted test in each uncovered module's crate at the delivered commit (`cargo nextest run -p <crate> --lib -E 'test(<name>)'`), then retry close. Otherwise, ask a live registered supervisor to run `{supervisor}task action=update id={} proof_targets=\"{}\" proof_scope_fix=true reason=\"widen proof scope for delivered modules\"`, then record scoped proof and retry close. If no delivery transaction exists, a live registered supervisor may instead close with `{supervisor}task action=close id={} supervisor_override=true reason=\"reviewed uncovered source modules and accepted the measured scope mismatch\"`; the waived modules are recorded on the task.",
        task.id,
        targets.join(","),
        task.id,
        supervisor = crate::mcp::tools::core::guidance::supervisor_prefix(),
    )
}

/// File kinds that are web or documentation content. A delivery made only
/// of these cannot need a macOS native-command platform proof (cas-b4cc).
const WEB_ONLY_EXTENSIONS: &[&str] = &[
    "css", "scss", "sass", "less", "html", "htm", "js", "jsx", "mjs", "cjs", "ts", "tsx", "mts",
    "cts", "vue", "svelte", "astro", "json", "svg", "png", "jpg", "jpeg", "gif", "webp", "avif",
    "ico", "woff", "woff2", "md", "mdx", "rst", "adoc", "txt", "snap",
];

fn is_web_only_path(path: &str) -> bool {
    let file = path.rsplit('/').next().unwrap_or(path).to_ascii_lowercase();
    file.rsplit_once('.')
        .is_some_and(|(_, extension)| WEB_ONLY_EXTENSIONS.contains(&extension))
}

/// cas-b4cc (GH #1023 finding 5): `risk=platform` declared on a delivery
/// whose every changed path is web or documentation content. cas-7d62, a web
/// CSS test, was asked for a macOS native-command receipt. The declared risk
/// is kept; this only says it looks wrong and names the logged supervisor
/// correction (cas-8d38). `None` when the risk is not platform, the diff is
/// unknown, or any path could be native.
pub(crate) fn platform_risk_implausibility(
    task: &Task,
    changed_paths: &[String],
) -> Option<String> {
    if !task.risk.contains(&TaskRisk::Platform)
        || changed_paths.is_empty()
        || !changed_paths.iter().all(|path| is_web_only_path(path))
    {
        return None;
    }
    let shown = changed_paths
        .iter()
        .take(3)
        .map(String::as_str)
        .collect::<Vec<_>>()
        .join(", ");
    let more = changed_paths.len().saturating_sub(3);
    Some(format!(
        "⚠️ PLATFORM RISK LOOKS IMPLAUSIBLE: task {id} declares risk=platform, but every one of its \
         {count} changed path(s) is web or documentation content ({shown}{more}). A platform proof is a \
         macOS native-command receipt and does not apply to web-only work. The declared risk stays in \
         force until a supervisor corrects it: `{supervisor}task action=update id={id} risk=none \
         proof_scope_fix=true reason=\"web-only delivery; platform risk declared in error\"`.",
        id = task.id,
        count = changed_paths.len(),
        more = if more > 0 {
            format!(", and {more} more")
        } else {
            String::new()
        },
        supervisor = crate::mcp::tools::core::guidance::supervisor_prefix(),
    ))
}

fn declared_risk_close_gaps(
    task: &Task,
    changed_paths: &[String],
    proof_repo: &std::path::Path,
) -> Vec<String> {
    let mut gaps = Vec::new();
    if task.risk.contains(&TaskRisk::Platform) && !has_platform_proof_note(&task.notes) {
        gaps.push(format!(
            "platform_proof missing evidence: {}",
            platform_proof_missing_evidence(&task.notes).join(", ")
        ));
    }
    if task.risk.contains(&TaskRisk::Concurrency) && !has_loaded_proof_note(&task.notes) {
        gaps.push(format!(
            "loaded_proof missing evidence: {}",
            loaded_proof_missing_evidence(&task.notes)
        ));
    }
    if task.risk.contains(&TaskRisk::BlastRadius) {
        let (uncovered, notice) =
            uncovered_blast_radius_scope(proof_repo, changed_paths, &task.proof_targets);
        if !uncovered.is_empty() {
            gaps.push(format!(
                "blast-radius uncovered source modules: {}{}",
                uncovered.join(", "),
                notice,
            ));
        }
    }
    gaps
}

/// The latest `ASSEMBLY_PROOF:` line on an epic, only when passing (cas-4cbb):
/// the supervisor's single build and test of the epic tip.
fn assembly_proof_line(notes: &str) -> Option<String> {
    // A later failed assembly invalidates an earlier pass. A substring such
    // as result=PASSING is not a passing receipt.
    let line = notes
        .lines()
        .filter_map(|line| {
            let start = line.find("ASSEMBLY_PROOF:")?;
            Some(line[start..].trim())
        })
        .last()?;
    scoped_proof_receipt_field(line, "result=")
        .is_some_and(|result| result.eq_ignore_ascii_case("pass"))
        .then(|| line.to_string())
}

fn matching_assembly_proof(
    notes: &str,
    repo: &std::path::Path,
    delivered: Option<&str>,
) -> Option<String> {
    let line = assembly_proof_line(notes)?;
    let head = scoped_proof_receipt_field(&line, "head=")?;
    git_commit_is_ancestor(repo, delivered?, &head).then_some(line)
}

/// cas-74cb: the tip an epic close answers for. A supplied commit receipt
/// wins; otherwise use the published epic branch, with a local fallback for
/// unpublished lanes and local_merge deliveries.
fn epic_close_tip(task: &Task, commit_receipt: Option<&str>, repo: &std::path::Path) -> Option<String> {
    if let Some(receipt) = commit_receipt.filter(|receipt| is_safe_git_refname(receipt)) {
        return resolve_branch_sha(repo, &format!("{receipt}^{{commit}}"));
    }
    let branch = task.branch.as_deref().filter(|branch| is_safe_git_refname(branch))?;
    if task.delivery_mode != cas_types::DeliveryMode::LocalMerge {
        fetch_parent_branch_best_effort(repo, branch);
    }
    let reference = preferred_live_target_ref_for_delivery(repo, branch, task.delivery_mode).0;
    resolve_branch_sha(repo, &format!("{reference}^{{commit}}"))
}

/// One integration proof for every code epic, including non-Rust deliveries.
/// Enforce CI only for confirmed no-queue GitHub repositories; otherwise keep
/// the existing containment policy. Without a queue,
/// read successful CI or an exact-SHA supervisor receipt for the landed tree.
fn epic_build_proof_basis(
    task: &Task,
    tip: Option<&str>,
    repo: &std::path::Path,
) -> Result<Option<String>, String> {
    let Some(tip) = tip else {
        return Ok(None);
    };
    let short = &tip[..tip.len().min(12)];
    let landed = resolve_close_gate_default_branch(repo)
        .ok()
        .and_then(|default| {
            let target = preferred_diff_target_ref(repo, &default);
            (git_ref_exists(repo, &target) && git_commit_is_ancestor(repo, tip, &target))
                .then_some((default, target))
        });
    if let Some((default, target)) = landed {
        let proof = (|| -> Result<String, String> {
            let timeout = std::time::Duration::from_secs(2);
            let binary = crate::github_repo::gh_binary();
            let queue =
                crate::github_repo::resolve_origin(repo, &binary, timeout).and_then(|github| {
                    crate::github_repo::merge_queue_enabled(
                        &github.canonical,
                        &default,
                        repo,
                        &binary,
                        timeout,
                    )
                });
            match queue {
                Ok(true) => {
                    return Ok(format!(
                        "its tip {short} is already contained in {target}, whose merge queue proved the landed tree"
                    ));
                }
                // Preserve the pre-existing containment path outside confirmed
                // no-queue GitHub repositories: local/non-GitHub projects and
                // unavailable queue metadata do not opt into this CI policy.
                Err(reason) => {
                    return Ok(format!(
                        "its tip {short} is already contained in {target}; merge queue state is unconfirmed ({reason}), so the existing containment proof is retained"
                    ));
                }
                Ok(false) => {}
            }
            // A cached/local main must not borrow CI while the remote main
            // has advanced. Read one current default SHA; no test is run.
            if crate::git_evidence::fetch_parent_branch_result(repo, &default)
                != BoundedFetch::Succeeded
            {
                return Err(format!(
                    "cannot refresh origin/{default} to read its exact SHA"
                ));
            }
            let target = format!("origin/{default}");
            let sha =
                resolve_branch_sha(repo, &target).ok_or("default branch SHA is unresolved")?;
            if !git_commit_is_ancestor(repo, tip, &sha) {
                return Err(format!(
                    "epic tip {tip} is not contained in refreshed {target} at {sha}"
                ));
            }
            if let Some(line) = assembly_proof_line(&task.notes)
                && scoped_proof_receipt_field(&line, "head=").as_deref() == Some(sha.as_str())
            {
                return Ok(format!(
                    "its tip {short} is already contained in {target}; the supervisor's {line} proves exact default-branch SHA {sha}"
                ));
            }
            let ci = crate::mcp::tools::core::workflow::epic_tip_ci_proof(&sha, repo)?;
            Ok(format!(
                "its tip {short} is already contained in {target}; {ci}"
            ))
        })();
        return proof.map(Some).map_err(|reason| format!(
            "EPIC CI REQUIRED: refusing close of {}: {reason}. A GitHub repository confirmed to have no merge queue needs successful CI on its exact SHA, or an ASSEMBLY_PROOF for that SHA recorded on the epic. Read the existing receipt; do not rerun a passing check. A registered supervisor may retry with supervisor_override=true and a non-empty reason.", task.id
        ));
    }
    Ok(matching_assembly_proof(&task.notes, repo, Some(tip))
        .map(|line| format!("the epic's own {line} covers its tip {short}")))
}

/// cas-74cb: appended when an epic without an assembly basis is refused by
/// the scoped-proof gate, naming the proof an epic is expected to carry.
fn epic_assembly_proof_instruction(epic_id: &str) -> String {
    format!(
        "An epic's build proof is its integration proof (CONTRIBUTING): land the epic on the default branch through the merge queue, which proves the exact merged tree, then retry close. An opt-in local assembly also counts: run the full build and suite on the epic tip and record `ASSEMBLY_PROOF: head=<epic tip sha> result=PASS command=<cmd> log=<path>` as a note on {epic_id}. Without a merge queue, a landed epic needs successful CI or an ASSEMBLY_PROOF on the exact default-branch SHA. Epic {epic_id} has no accepted integration proof."
    )
}

/// The Git range the snapshot-approval gate measures for one close.
#[derive(Debug, PartialEq, Eq)]
struct SnapshotGateRange {
    base: Option<String>,
    tip: Option<String>,
}

/// cas-f0a6: choose the range whose snapshot changes this task must approve.
///
/// The task's attributed delivery range is authoritative when it exists.
/// Without one, the gate must still measure only what the delivered tip
/// itself adds to the target: `merge-base(tip, target)..tip`, against the
/// refreshed `origin/<target>` when present. The old fallback paired the
/// delivered tip with `merge-base(checkout HEAD, target)`, which for a
/// supervisor closing a merged anchor diffed the target's newer snapshots
/// backwards onto the old anchor, and against a stale local `main` swept in
/// a thousand unrelated commits; with no attributed paths the gate then
/// demanded approval for every snapshot in that range. A merged tip adds
/// nothing beyond the target, so it has nothing unattributed to approve.
///
/// No diff is attributed (`None`, gate skipped) when the close has no
/// delivery of its own: a no-code task declares that it delivers no code,
/// and a close with no commit receipt, no merged anchor and no worker
/// checkout would otherwise measure whatever the closing checkout's HEAD
/// happens to carry (for example a supervisor on the epic branch closing an
/// ops chore whose target is `main`).
fn snapshot_gate_range(
    repo: &std::path::Path,
    target_branch: &str,
    attributed_base: Option<&str>,
    delivered_tip: Option<&str>,
    no_code: bool,
    tip_is_task_delivery: bool,
) -> Option<SnapshotGateRange> {
    if no_code || !tip_is_task_delivery {
        return None;
    }
    if let Some(base) = attributed_base {
        return Some(SnapshotGateRange {
            base: Some(base.to_string()),
            tip: delivered_tip.map(str::to_string),
        });
    }
    let base = delivered_tip.and_then(|tip| {
        let target = preferred_diff_target_ref(repo, target_branch);
        git_merge_base(repo, tip, &target)
    });
    Some(SnapshotGateRange {
        base,
        tip: delivered_tip.map(str::to_string),
    })
}

fn close_delivered_tip(
    repo: &std::path::Path,
    receipt: Option<&str>,
    merged_anchor: Option<&str>,
) -> Option<String> {
    receipt
        .and_then(|receipt| resolve_branch_sha(repo, receipt))
        .or_else(|| merged_anchor.map(str::to_string))
        .or_else(|| resolve_branch_sha(repo, "HEAD"))
}

/// Durable code evidence survives a deleted lane or a branchless parent.
fn has_recorded_code_delivery(task: &Task) -> bool {
    let delivery = &task.deliverables;
    !delivery.files_changed.is_empty()
        || delivery.commit_hash.is_some()
        || delivery.merge_commit.is_some()
        || delivery.delivery_pr_merge_commit.is_some()
        || delivery.factory_branch_anchor.is_some()
        || !delivery.historical_factory_branch_anchors.is_empty()
}

/// Releasing a lease retires its assignee, not its recorded delivery.
/// A legacy worktree_id alone only locates the checkout for dirty-work and
/// methodology checks; it does not identify a recorded factory delivery.
fn has_delivery_to_measure(task: &Task) -> bool {
    task.assignee.is_some()
        || has_recorded_code_delivery(task)
        || task.deliverables.parked_branch.is_some()
        || !task.deliverables.handoff_branches.is_empty()
        || task.deliverables.integration_batch.is_some()
}

/// Select one tip for the path, proof-base and snapshot consumers of close.
fn close_task_delivery_tip(
    task: &Task,
    repo: &std::path::Path,
    receipt: Option<&str>,
    merged_anchor: Option<&str>,
    epic_has_recorded_delivery: bool,
) -> Result<Option<String>, String> {
    if task.task_type == TaskType::Epic {
        // cas-04c6: planning/ops epics have no Git delivery window. A
        // declared branch, receipt or durable parent/child delivery must
        // still resolve; absence is never permission to measure HEAD.
        if task.branch.is_none()
            && receipt.is_none()
            && merged_anchor.is_none()
            && !epic_has_recorded_delivery
            && !has_recorded_code_delivery(task)
        {
            return Ok(None);
        }
        return epic_close_tip(task, receipt, repo)
            .map(Some)
            .ok_or_else(|| {
                format!(
                    "EPIC DELIVERY TIP REQUIRED: cannot resolve the delivery of {} from commit_receipt={} or epic branch {} (local or origin). Restore the epic branch or supply a resolvable commit_receipt. Checkout HEAD is not epic delivery evidence.",
                    task.id,
                    receipt.unwrap_or("<none>"),
                    task.branch.as_deref().unwrap_or("<none>"),
                )
            });
    }
    Ok(close_delivered_tip(repo, receipt, merged_anchor))
}

