    fn install_scoped_proof_checker(dir: &std::path::Path) -> bool {
        let checker = crate::test_paths::workspace_root()
            .join("scripts/check-scoped-test-surface.sh");
        if !checker.is_file() {
            eprintln!(
                "SKIP: scoped proof gate regression needs checker at {}",
                checker.display()
            );
            return false;
        }
        let destination = dir.join("scripts/check-scoped-test-surface.sh");
        std::fs::create_dir_all(destination.parent().unwrap()).unwrap();
        std::fs::copy(checker, destination).unwrap();
        true
    }

    fn initialize_scoped_proof_git_fixture(dir: &std::path::Path) {
        let status = std::process::Command::new("git")
            .args(["init", "-q", "-b", "main"])
            .current_dir(dir)
            .status()
            .unwrap();
        assert!(status.success());
        let status = std::process::Command::new("git")
            .args(["add", "."])
            .current_dir(dir)
            .status()
            .unwrap();
        assert!(status.success());
        let status = std::process::Command::new("git")
            .args([
                "-c",
                "user.name=scoped-proof-test",
                "-c",
                "user.email=scoped-proof-test@example.invalid",
                "commit",
                "-qm",
                "fixture",
            ])
            .current_dir(dir)
            .status()
            .unwrap();
        assert!(status.success());
    }

    #[test]
    fn scoped_proof_gate_and_surface_checker_agree_on_multi_area_diff() {
        let dir = tempfile::tempdir().unwrap();
        if !install_scoped_proof_checker(dir.path()) {
            return;
        }
        let target_repo = tempfile::tempdir().unwrap();
        let target_checker = target_repo
            .path()
            .join("scripts/check-scoped-test-surface.sh");
        std::fs::create_dir_all(target_checker.parent().unwrap()).unwrap();
        std::fs::copy(
            dir.path().join("scripts/check-scoped-test-surface.sh"),
            &target_checker,
        )
        .unwrap();

        let files = [
            "cas-cli/src/builtins/skills/demo/SKILL.md",
            "cas-cli/src/hub.rs",
            "cas-cli/tests/builtin_archive_portability_test.rs",
            "cas-cli/tests/builtin_demo_test.rs",
            "cas-cli/tests/builtin_flavor_drift_test.rs",
            "cas-cli/tests/agent_definition_contract_test.rs",
            "cas-cli/tests/factory_codex_skill_guardrails.rs",
            "cas-cli/tests/hub_contract_test.rs",
            "cas-cli/tests/mcp_tools_test.rs",
            "cas-cli/tests/mcp_tools_test/task_tools/operations.rs",
        ];
        for file in files {
            let path = dir.path().join(file);
            std::fs::create_dir_all(path.parent().unwrap()).unwrap();
            let body = if file.ends_with("hub.rs") {
                "pub fn supervisor_sessions() {}\n"
            } else if file.ends_with("hub_contract_test.rs") {
                "fn covers_hub() { cas::hub::supervisor_sessions(); }\n"
            } else if file.ends_with("builtin_demo_test.rs") {
                "const SOURCE: &str = \"cas-cli/src/builtins/skills/demo/SKILL.md\";\nconst CATALOG: &str = \"skills/demo/SKILL.md\";\n"
            } else {
                "fn fixture() {}\n"
            };
            std::fs::write(path, body).unwrap();
        }
        initialize_scoped_proof_git_fixture(dir.path());
        let status = std::process::Command::new("git")
            .args(["checkout", "-qb", "changed"])
            .current_dir(dir.path())
            .status()
            .unwrap();
        assert!(status.success());

        let changed = [
            "cas-cli/src/builtins/skills/demo/SKILL.md",
            "cas-cli/src/hub.rs",
            "cas-cli/tests/mcp_tools_test/task_tools/operations.rs",
        ];
        for file in changed {
            use std::io::Write;
            let path = dir.path().join(file);
            let mut handle = std::fs::OpenOptions::new()
                .append(true)
                .open(path)
                .unwrap();
            writeln!(handle, "// multi-area diff").unwrap();
        }
        let status = std::process::Command::new("git")
            .args(["add", "."])
            .current_dir(dir.path())
            .status()
            .unwrap();
        assert!(status.success());
        let status = std::process::Command::new("git")
            .args([
                "-c",
                "user.name=scoped-proof-test",
                "-c",
                "user.email=scoped-proof-test@example.invalid",
                "commit",
                "-qm",
                "multi-area change",
            ])
            .current_dir(dir.path())
            .status()
            .unwrap();
        assert!(status.success());

        let changed = changed
            .iter()
            .map(|file| (*file).to_string())
            .collect::<Vec<_>>();
        let mut cache = ScopedProofTargetCache::default();
        let targets = required_scoped_proof_targets(
            dir.path(),
            target_repo.path(),
            &changed,
            &mut cache,
        )
        .unwrap();
        let reordered = changed.iter().rev().cloned().collect::<Vec<_>>();
        assert_eq!(
            required_scoped_proof_targets(
                dir.path(),
                target_repo.path(),
                &reordered,
                &mut cache,
            )
            .unwrap(),
            targets,
            "the same changed-path set must reuse the close-local cache"
        );
        assert_eq!(cache.entries.len(), 1);
        // Canonicalization sorts/deduplicates the checker targets; coverage
        // agrees by set, independently of the checker's traversal order.
        let expected = [
            "hub_contract_test".to_string(),
            "mcp_tools_test".to_string(),
            "builtin_archive_portability_test".to_string(),
            "builtin_flavor_drift_test".to_string(),
            "agent_definition_contract_test".to_string(),
            "factory_codex_skill_guardrails".to_string(),
            "builtin_demo_test".to_string(),
        ]
        .into_iter()
        .collect::<std::collections::BTreeSet<_>>();
        assert_eq!(
            targets.iter().cloned().collect::<std::collections::BTreeSet<_>>(),
            expected
        );
        assert_eq!(targets.len(), expected.len(), "canonical targets must be unique");

        let checker = dir.path().join("scripts/check-scoped-test-surface.sh");
        let actual_diff = std::process::Command::new("bash")
            .arg(&checker)
            .args(["--resolve-targets", "--base", "main", "--"])
            .current_dir(dir.path())
            .output()
            .unwrap();
        assert!(
            actual_diff.status.success(),
            "surface checker could not resolve the committed multi-area diff: {}",
            String::from_utf8_lossy(&actual_diff.stderr)
        );
        let actual_diff_args = String::from_utf8_lossy(&actual_diff.stdout);
        for target in &targets {
            assert!(
                actual_diff_args.contains(&format!("--test {target}")),
                "committed diff omitted gate target {target}: {actual_diff_args}"
            );
        }
        let status = std::process::Command::new("git")
            .args(["status", "--porcelain"])
            .current_dir(dir.path())
            .output()
            .unwrap();
        assert!(
            status.status.success() && status.stdout.is_empty(),
            "surface checker must not write inside the inspected repo: {}",
            String::from_utf8_lossy(&status.stdout)
        );

        let mut command = std::process::Command::new("bash");
        command
            .arg(checker)
            .args(["--base", "HEAD", "--paths-from-stdin", "--", "-p", "cas", "--lib"]);
        for target in &targets {
            command.args(["--test", target]);
        }
        command
            .current_dir(dir.path())
            .stdin(std::process::Stdio::piped())
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped());
        let mut child = command.spawn().unwrap();
        {
            use std::io::Write;
            let mut stdin = child.stdin.take().unwrap();
            writeln!(stdin, "{}", changed.join("\n")).unwrap();
        }
        let output = child.wait_with_output().unwrap();
        assert!(
            output.status.success(),
            "surface checker rejected the gate command: {}",
            String::from_utf8_lossy(&output.stderr)
        );
        assert!(
            String::from_utf8_lossy(&output.stdout).contains("covered committed diff"),
            "surface checker did not emit a passing receipt: {}",
            String::from_utf8_lossy(&output.stdout)
        );
    }

    /// cas-0db7: the gate resolves the task's attributed paths, but `--proof`
    /// validates the whole `merge-base(base)..HEAD` diff. With a neighbour's
    /// skill edit inside that range, the refusal's suggested command must name
    /// every target `--proof` will require, so running it exactly as printed
    /// passes the checker's validation. The gate-only command is what failed.
    #[test]
    fn scoped_proof_refusal_suggests_every_target_proof_validation_requires_cas_0db7() {
        let dir = tempfile::tempdir().unwrap();
        if !install_scoped_proof_checker(dir.path()) {
            return;
        }
        let p = dir.path();
        let write = |relative: &str, body: &str| {
            let path = p.join(relative);
            std::fs::create_dir_all(path.parent().unwrap()).unwrap();
            std::fs::write(path, body).unwrap();
        };
        let commit = |message: &str| {
            let status = std::process::Command::new("git")
                .args([
                    "-c",
                    "user.name=scoped-proof-test",
                    "-c",
                    "user.email=scoped-proof-test@example.invalid",
                    "commit",
                    "-qam",
                    message,
                ])
                .current_dir(p)
                .status()
                .unwrap();
            assert!(status.success());
        };
        for target in [
            "mcp_tools_test",
            "builtin_archive_portability_test",
            "builtin_flavor_drift_test",
            "agent_definition_contract_test",
            "factory_codex_skill_guardrails",
            "builtin_doc_hygiene_test",
        ] {
            write(
                &format!("cas-cli/tests/{target}.rs"),
                &format!("// {target}\n"),
            );
        }
        write("cas-cli/Cargo.toml", "[package]\nname = \"cas\"\n");
        write("cas-cli/src/builtins/skills/demo/SKILL.md", "# demo\n");
        initialize_scoped_proof_git_fixture(p);
        let base = resolve_branch_sha(p, "HEAD").unwrap();
        // A neighbour's skill edit lands in the range before the delivery.
        write("cas-cli/src/builtins/skills/demo/SKILL.md", "# demo v2\n");
        commit("neighbour skill edit");
        // The delivery itself touches one integration test.
        write("cas-cli/tests/mcp_tools_test.rs", "// mcp_tools_test v2\n");
        commit("delivery");

        let attributed = vec!["cas-cli/tests/mcp_tools_test.rs".to_string()];
        let mut cache = ScopedProofTargetCache::default();
        let gate_targets = required_scoped_proof_targets(p, p, &attributed, &mut cache).unwrap();
        assert!(
            gate_targets.contains(&"mcp_tools_test".to_string()),
            "{gate_targets:?}"
        );
        let proof_targets =
            proof_validation_targets(p, p, Some(&base)).expect("the checker resolves the range");
        assert!(
            proof_targets.contains(&"builtin_doc_hygiene_test".to_string()),
            "{proof_targets:?}"
        );
        assert!(
            !gate_targets.contains(&"builtin_doc_hygiene_test".to_string()),
            "precondition: the gate's own list is narrower than --proof's: {gate_targets:?}"
        );

        let checker = p.join("scripts/check-scoped-test-surface.sh");
        let validate = |command: &str| {
            let args: Vec<&str> = command
                .split_once("run-scoped-tests.sh --proof ")
                .unwrap()
                .1
                .split_whitespace()
                .collect();
            std::process::Command::new("bash")
                .arg(&checker)
                .args(["--base", base.as_str(), "--"])
                .args(&args)
                .current_dir(p)
                .output()
                .unwrap()
        };

        let suggested = suggested_scoped_proof_command(&gate_targets, p, p, Some(&base));
        for target in gate_targets.iter().chain(proof_targets.iter()) {
            assert!(
                suggested.contains(&format!("--test {target}")),
                "{target} missing from {suggested}"
            );
        }
        let passed = validate(&suggested);
        assert!(
            passed.status.success(),
            "the suggested command must pass --proof validation: {}",
            String::from_utf8_lossy(&passed.stderr)
        );

        let gate_only = validate(&scoped_proof_command(&gate_targets, Some(&base)));
        assert!(
            !gate_only.status.success(),
            "the gate-only command was the defect"
        );
        assert!(
            String::from_utf8_lossy(&gate_only.stderr).contains("SCOPED PROOF INCOMPLETE"),
            "{}",
            String::from_utf8_lossy(&gate_only.stderr)
        );
    }

