    #[test]
    fn scoped_proof_work_target_receipt_requires_matching_base() {
        let expected_base = "a".repeat(40);
        let dir = scoped_proof_fixture();
        assert_eq!(
            scoped_proof_command(
                &[
                    "factory_ops".to_string(),
                    "factory_mcp_ops_test".to_string(),
                ],
                Some(&expected_base),
            ),
            format!(
                "SCOPED_PROOF_BASE={expected_base} scripts/run-scoped-tests.sh --proof -p cas --lib --test factory_ops --test factory_mcp_ops_test"
            )
        );
        let mut task = Task::new("cas-work-target-proof".into(), "work target proof".into());
        task.notes = format!(
            "[2026-09-11] 📝 PROGRESS SCOPED_PROOF: SCOPED_PROOF_BASE={expected_base} targets=lib:factory_ops,test:factory_mcp_ops_test result=PASS"
        );
        let changed = vec!["cas-cli/src/mcp/tools/service/factory_ops.rs".to_string()];

        validate_risk_close_proofs_with_base(&task, &changed, dir.path(), Some(&expected_base))
            .expect("a scoped receipt with the WorkTarget merge base should pass");

        task.notes = task.notes.replace(&expected_base, &"b".repeat(40));
        let error =
            validate_risk_close_proofs_with_base(&task, &changed, dir.path(), Some(&expected_base))
                .expect_err(
                    "a scoped receipt from origin/main must not satisfy a WorkTarget close",
                );
        assert!(error.contains("SCOPED_PROOF_BASE"), "{error}");
        assert!(error.contains(&expected_base), "{error}");
    }

    #[test]
    fn scoped_proof_accepts_unambiguous_abbreviated_base() {
        let dir = scoped_proof_fixture();
        initialize_scoped_proof_git_fixture(dir.path());
        let output = std::process::Command::new("git")
            .args(["rev-parse", "HEAD"])
            .current_dir(dir.path())
            .output()
            .unwrap();
        assert!(output.status.success());
        let expected_base = String::from_utf8(output.stdout).unwrap().trim().to_string();
        let abbreviated = &expected_base[..10];
        let mut task = Task::new("cas-short-base".into(), "scoped proof".into());
        task.notes = format!(
            "[2026-09-23] 📝 PROGRESS SCOPED_PROOF: base={abbreviated} targets=lib:factory_ops,test:factory_mcp_ops_test result=PASS"
        );
        let changed = vec!["cas-cli/src/mcp/tools/service/factory_ops.rs".to_string()];
        validate_risk_close_proofs_with_base(&task, &changed, dir.path(), Some(&expected_base))
            .expect("git must resolve an unambiguous abbreviated base");

        task.notes = task.notes.replace(abbreviated, "deadbeef00");
        assert!(
            validate_risk_close_proofs_with_base(&task, &changed, dir.path(), Some(&expected_base))
                .is_err(),
            "an abbreviation that does not resolve to the base must be rejected"
        );
    }

    #[test]
    fn scoped_proof_rejection_explains_which_base_the_delivery_must_use() {
        // cas-9c1e: a worker hitting this used to be told only *what* base to
        // use, while the command it was told to run produced a receipt the very
        // next check rejected. The message must say what the base is.
        let dir = scoped_proof_fixture();
        let expected_base = "c".repeat(40);
        let mut task = Task::new("cas-base-guidance".into(), "base guidance".into());
        task.notes = format!(
            "[2026-09-18] 📝 PROGRESS SCOPED_PROOF: targets=lib:factory_ops,test:factory_mcp_ops_test result=PASS base={}",
            "d".repeat(40)
        );
        let changed = vec!["cas-cli/src/mcp/tools/service/factory_ops.rs".to_string()];

        let error =
            validate_risk_close_proofs_with_base(&task, &changed, dir.path(), Some(&expected_base))
                .expect_err("a receipt from another base must not satisfy this delivery");
        assert!(error.contains(&expected_base), "{error}");
        assert!(
            error.contains("first parent of its earliest commit"),
            "the rejection must say what the base IS, not only its value: {error}"
        );
        assert!(
            error.contains("the required targets were derived from"),
            "and why that base is the one the targets came from: {error}"
        );

        task.notes = format!(
            "[2026-09-18] 📝 PROGRESS SCOPED_PROOF: targets=lib:factory_ops,test:factory_mcp_ops_test result=PASS base={expected_base}"
        );
        validate_risk_close_proofs_with_base(&task, &changed, dir.path(), Some(&expected_base))
            .expect("a receipt on the delivery's own base closes");
    }

