    #[test]
    fn matching_epic_assembly_proves_supervisor_close_without_worker_receipt_cas_d1ee() {
        let dir = init_factory_repo("worker");
        let repo = dir.path();
        let old = head_sha(repo);
        commit_file_at(repo, "delivery.rs", "// delivery\n", "2026-08-04T12:00:00Z");
        let delivery = head_sha(repo);
        let task = worker_task("worker");
        let notes = format!(
            "ASSEMBLY_PROOF: head={delivery} result=PASS command=cargo nextest run --workspace log=assembly.log"
        );
        let covered = matching_assembly_proof(&notes, repo, Some(&delivery));
        assert!(covered.is_some());
        let proofs = if covered.is_some() {
            BuildProofs::DeferredToAssembly
        } else {
            BuildProofs::Required
        };
        let mut task = task;
        task.risk = vec![TaskRisk::Concurrency];
        validate_risk_close_proofs_with_base_and_target_and_cache(
            &task,
            &["cas-cli/src/retrieval_eval.rs".into()],
            repo,
            repo,
            Some(&old),
            Some(&delivery),
            proofs,
            &mut ScopedProofTargetCache::default(),
        )
        .unwrap();
        assert!(
            matching_assembly_proof(
                &format!("ASSEMBLY_PROOF: head={old} result=PASS"),
                repo,
                Some(&delivery)
            )
            .is_none()
        );
        assert!(
            matching_assembly_proof(
                &format!("{notes}\nASSEMBLY_PROOF: head={delivery} result=FAIL"),
                repo,
                Some(&delivery)
            )
            .is_none()
        );
        assert!(
            matching_assembly_proof("ASSEMBLY_PROOF: result=PASS", repo, Some(&delivery)).is_none()
        );
    }

    #[test]
    fn request_changes_measures_current_delivery_and_reviewed_drop_is_explicit_cas_d1ee() {
        let dir = init_factory_repo("worker");
        let repo = dir.path();
        commit_file_at(
            repo,
            "delivery.rs",
            "// original delivery\n",
            "2026-08-04T12:00:00Z",
        );
        let original = head_sha(repo);
        git(repo, &["checkout", "-q", "main"]);
        git(
            repo,
            &[
                "merge",
                "-q",
                "--no-ff",
                "-s",
                "ours",
                "factory/worker",
                "-m",
                "reviewed integration resolution",
            ],
        );
        let current = head_sha(repo);
        git(repo, &["checkout", "-q", "factory/worker"]);
        git(repo, &["merge", "--ff-only", "main"]);
        let mut task = worker_task("worker");
        task.status = TaskStatus::AwaitingMerge;
        task.deliverables.factory_branch_anchor = Some(original.clone());
        let req = base_req(&task.id);
        assert!(matches!(
            run_factory_branch_merge_gate(&task, &req, "main", repo),
            MergeStateGateOutcome::Reject(_)
        ));

        let mut window = window_at(0, "supervisor content review");
        window.supervisor_override_reason = Some("reviewed risk mismatch".into());
        let attribution = TaskCommitAttribution {
            receipt: None,
            window: Some(&window),
        };
        assert!(matches!(
            run_factory_branch_merge_gate_with_attribution(&task, &req, "main", repo, attribution),
            MergeStateGateOutcome::Reject(_)
        ));
        window.supervisor_override_reason = Some(format!(
            "reviewed-drop: {current} -- original lines intentionally replaced by the approved sibling"
        ));
        let outcome = run_factory_branch_merge_gate_with_attribution(
            &task,
            &req,
            "main",
            repo,
            TaskCommitAttribution {
                receipt: None,
                window: Some(&window),
            },
        );
        assert!(matches!(outcome, MergeStateGateOutcome::Reject(_)),
            "a dropping merge is not a superseding first-parent edit: {outcome:?}");
        assert!(reviewed_delivery_drop_reason(Some("reviewed-drop: ")).is_none());
        assert!(validate_task_commit_receipt(repo, &original, "main", &window)
            .unwrap_err().contains("does not touch"));
        commit_file_at(
            repo,
            "unmerged.rs",
            "// never integrated\n",
            "2026-08-04T12:02:00Z",
        );
        let unmerged = head_sha(repo);
        let outcome = run_factory_branch_merge_gate_with_attribution(
            &task,
            &req,
            "main",
            repo,
            TaskCommitAttribution {
                receipt: Some(&unmerged),
                window: Some(&window),
            },
        );
        assert!(
            matches!(outcome, MergeStateGateOutcome::Reject(_)),
            "reviewed drop must not waive unmerged work: {outcome:?}"
        );
        // Restore the exact already-approved target for the fresh-cycle case.
        git(repo, &["checkout", "-q", "-B", "factory/worker", &current]);

        let root = tempfile::tempdir().unwrap();
        let store = cas_store::SqliteTaskStore::open(root.path()).unwrap();
        cas_store::TaskStore::init(&store).unwrap();
        cas_store::TaskStore::add(&store, &task).unwrap();
        cas_store::request_changes_for_parked_delivery(
            root.path(),
            &task.id,
            "supervisor",
            "Re-deliver the approved current target; no code change required",
        )
        .unwrap();
        let mut fresh = cas_store::TaskStore::get(&store, &task.id).unwrap();
        assert!(fresh.deliverables.factory_branch_anchor.is_none());
        assert!(
            fresh
                .deliverables
                .historical_factory_branch_anchors
                .contains(&original)
        );
        fresh.status = TaskStatus::InProgress;
        // History remains attribution evidence, never the active content anchor.
        let mut fresh_window = window_at(0, "fresh reviewed delivery");
        fresh_window.identity = task_commit_identity(&fresh, None);
        let outcome = run_factory_branch_merge_gate_with_attribution(
            &fresh,
            &req,
            "main",
            repo,
            TaskCommitAttribution {
                receipt: Some(&current),
                window: Some(&fresh_window),
            },
        );
        assert!(
            matches!(outcome, MergeStateGateOutcome::Proceed),
            "{outcome:?}"
        );
        fresh.status = TaskStatus::AwaitingMerge;
        fresh.deliverables.factory_branch_anchor = Some(current);
        assert!(matches!(
            run_factory_branch_merge_gate(&fresh, &req, "main", repo),
            MergeStateGateOutcome::ProceedWithNote(_)
        ));
    }

    #[test]
    fn supervisor_override_uses_merged_anchor_after_worker_branch_moves_cas_46c2() {
        let dir = init_factory_repo("worker");
        let p = dir.path();
        commit_file_at(p, "delivered.rs", "// delivered\n", "2026-08-04T12:00:00Z");
        let anchor = head_sha(p);
        assert!(!supervisor_merged_anchor_close(true, Some(&anchor), p, "main"));
        git(p, &["checkout", "-q", "main"]);
        git(p, &["merge", "-q", "--no-ff", &anchor, "-m", "merge exact SHA"]);
        git(p, &["checkout", "-q", "factory/worker"]);
        git(p, &["checkout", "-q", "-b", "factory/worker-cas-next"]);
        assert!(supervisor_merged_anchor_close(true, Some(&anchor), p, "main"));
        assert!(!supervisor_merged_anchor_close(false, Some(&anchor), p, "main"));
        assert!(!supervisor_merged_anchor_close(true, None, p, "main"));
        commit_file_at(p, "next.rs", "// unrelated next task\n", "2026-08-04T12:02:00Z");
        let next_head = head_sha(p);
        assert_eq!(close_delivered_tip(p, None, Some(&anchor)), Some(anchor.clone()));
        assert_ne!(close_delivered_tip(p, None, Some(&anchor)), Some(next_head.clone()));
        let assembly_head = rev_parse_local(p, "main");
        let assembly_note = format!("ASSEMBLY_PROOF: head={assembly_head} result=PASS");
        let line = assembly_proof_line(&assembly_note).unwrap();
        let tested_head = scoped_proof_receipt_field(&line, "head=").unwrap();
        let delivered = close_delivered_tip(p, None, Some(&anchor)).unwrap();
        assert!(git_commit_is_ancestor(p, &delivered, &tested_head));
        assert!(!git_commit_is_ancestor(p, &next_head, &tested_head));
        assert!(commit_is_merged_into_parent(p, &anchor, "main"));
    }

    /// cas-dc1b (M03): PreToolUse denies `git push origin` for local_merge
    /// delivery, so MERGE REQUIRED must not tell such a worker to push or
    /// open a PR; it asks the supervisor for the local merge instead. Both
    /// the trunk-parent and epic-parent remediations are covered.
    #[test]
    fn local_merge_merge_required_remediation_never_suggests_a_push() {
        let dir = init_factory_repo("worker");
        std::fs::write(dir.path().join("a.rs"), "// a\n").unwrap();
        git(dir.path(), &["add", "a.rs"]);
        git(dir.path(), &["commit", "-q", "-m", "feat: a"]);
        git(dir.path(), &["branch", "epic/local-lane", "main"]);

        let mut task = worker_task("worker");
        task.delivery_mode = cas_types::DeliveryMode::LocalMerge;
        let req = base_req(&task.id);
        let _env = TestEnvGuard::with_optional_vars(&[
            ("CAS_FACTORY_WORKER_CLI", Some("claude")),
            ("CAS_FACTORY_SUPERVISOR_CLI", Some("claude")),
        ]);

        for parent in ["main", "epic/local-lane"] {
            match run_factory_branch_merge_gate(&task, &req, parent, dir.path()) {
                MergeStateGateOutcome::Reject(msg) => {
                    assert!(msg.contains("MERGE REQUIRED"), "{parent}: {msg}");
                    assert!(
                        !msg.contains("If this gate has now refused you twice"),
                        "routine merge handoff must not suggest a premise stop: {msg}"
                    );
                    assert!(!msg.contains("git push origin"), "{parent}: {msg}");
                    assert!(!msg.contains("Open a PR targeting"), "{parent}: {msg}");
                    assert!(msg.contains("merge_request=true"), "{parent}: {msg}");
                    assert!(
                        msg.contains(&format!("task action=close id={}`", task.id)),
                        "{parent}: retry must be a complete command: {msg}"
                    );
                }
                other => panic!("{parent}: expected Reject, got {other:?}"),
            }
        }
    }

    #[test]
    fn worker_task_close_on_local_epic_branch_points_at_supervisor_merge_not_pr() {
        // cas-c631: when the parent branch is a local-only `epic/<slug>`
        // branch (the supervisor's EPIC workflow convention — never pushed
        // to origin), the remediation must NOT tell the worker to open a PR
        // against it (that `gh pr create --base epic/<slug>` call fails with
        // no matching origin ref — the exact recurring friction this task
        // fixes). It must instead hand the worker a push + supervisor-merge
        // handoff.
        let parent = "epic/epic-triage-fix-the-docs-requests-bug-backlog-veri-cas-fff9";
        let dir = init_factory_repo_with_parent("worker", parent);
        std::fs::write(dir.path().join("a.rs"), "// a\n").unwrap();
        git(dir.path(), &["add", "a.rs"]);
        git(dir.path(), &["commit", "-q", "-m", "feat: a"]);
        let expected_tip = resolve_branch_sha(dir.path(), "factory/worker")
            .expect("factory branch tip should resolve");

        let task = worker_task("worker");
        let req = base_req(&task.id);
        let mut env =
            TestEnvGuard::with_optional_vars(&[("CAS_FACTORY_WORKER_CLI", Some("claude"))]);

        for (harness, coord) in [
            ("claude", "mcp__cas__coordination"),
            ("codex", "mcp__cs__coordination"),
            ("grok", "cas__coordination"),
            ("opencode", "cas_coordination"),
        ] {
            env.set("CAS_FACTORY_WORKER_CLI", harness);
            env.set("CAS_FACTORY_SUPERVISOR_CLI", "codex");
            let out = run_factory_branch_merge_gate(&task, &req, parent, dir.path());

            match out {
                MergeStateGateOutcome::Reject(msg) => {
                    assert!(msg.contains("MERGE REQUIRED"), "missing header: {msg}");
                    let prefix = coord.strip_suffix("coordination").unwrap();
                    assert!(msg.contains(&format!("{prefix}task action=close")), "{msg}");
                    assert!(
                        msg.contains("mcp__cs__task action=request_changes"),
                        "{msg}"
                    );
                    assert!(
                        msg.contains("factory/worker"),
                        "missing factory branch name: {msg}"
                    );
                    assert!(msg.contains(parent), "missing parent branch name: {msg}");
                    assert!(
                        msg.contains("supervisor_override=true"),
                        "remediation must still call out bypass-immunity: {msg}"
                    );
                    assert!(
                        !msg.contains("Open a PR targeting"),
                        "must NOT tell the worker to open a PR against a local-only \
                         epic branch: {msg}"
                    );
                    assert!(
                        msg.contains("do NOT run `gh pr create"),
                        "must explicitly warn against gh pr create on the missing \
                         origin ref: {msg}"
                    );
                    assert!(
                        msg.contains("supervisor to merge"),
                        "must hand the worker a supervisor-merge-request handoff: {msg}"
                    );
                    assert!(
                        msg.contains(&format!("`{coord} action=inbox_poll`"))
                            && msg.contains(&format!("`{coord} action=message"))
                            && msg.contains("`No unread messages`")
                            && !msg.contains("daemon transport delivery")
                            && !msg.contains("at-most-once"),
                        "{harness} remediation must use its harness-resolved inbox and \
                         message APIs and require drain-until-empty polling, without \
                         polling internals (cas-90e8): {msg}"
                    );
                    assert!(
                        msg.contains(&expected_tip),
                        "escalation template must include the current branch tip {expected_tip}: {msg}"
                    );
                    assert!(
                        msg.contains(&format!("task_id={}", task.id)),
                        "structured merge request must carry the parked task identity: {msg}"
                    );
                    assert!(
                        msg.contains("merge_request=true summary=\"...\" message=\"...\"")
                            && !msg.contains("Fresh after draining"),
                        "the merge request names its fields but does not dictate the \
                         worker's wording (cas-90e8): {msg}"
                    );
                    let poll = msg.find("action=inbox_poll").expect("poll step");
                    let push = msg.find("Push factory/worker").expect("push step");
                    let escalation = msg.find("action=message").expect("escalation step");
                    assert!(
                        poll < push && poll < escalation,
                        "polling must precede push/escalation steps for {harness}: {msg}"
                    );
                }
                other => panic!("expected Reject for stranded factory branch, got {other:?}"),
            }
        }
    }

    /// cas-355d (GH #141): when the `epic/<slug>` parent branch IS pushed to
    /// origin, the rejection must not assert the opposite. The old wording
    /// hardcoded "is a local-only epic branch (not pushed to origin) ... the
    /// PR will fail" off the *name* alone, sending workers to re-push a branch
    /// that was already published while the real gap — their branch not merged
    /// into the epic tip — went unnamed.
    #[test]
    fn pushed_epic_branch_rejection_names_the_merge_gap_not_a_missing_push_cas_355d() {
        let bare = tempfile::tempdir().unwrap();
        let bare_status = std::process::Command::new("git")
            .args(["init", "-q", "--bare"])
            .current_dir(bare.path())
            .status()
            .expect("git init --bare");
        assert!(bare_status.success());

        let parent = "epic/x";
        let dir = init_factory_repo_with_parent("worker", parent);
        let p = dir.path();
        git(
            p,
            &["remote", "add", "origin", bare.path().to_str().unwrap()],
        );
        // Publish the epic branch: origin/epic/x exists AND matches local.
        git(p, &["push", "-q", "origin", parent]);
        assert!(
            git_ref_exists(p, "origin/epic/x"),
            "precondition: origin/epic/x must resolve"
        );
        assert_eq!(
            resolve_branch_sha(p, parent),
            resolve_branch_sha(p, "origin/epic/x"),
            "precondition: local and origin epic tips must match"
        );

        // Unmerged worker commit → the gate rejects.
        std::fs::write(p.join("a.rs"), "// a\n").unwrap();
        git(p, &["add", "a.rs"]);
        git(p, &["commit", "-q", "-m", "feat: a"]);

        let task = worker_task("worker");
        let req = base_req(&task.id);
        let out = run_factory_branch_merge_gate(&task, &req, parent, p);

        match out {
            MergeStateGateOutcome::Reject(msg) => {
                assert!(
                    !msg.contains("local-only"),
                    "must not call a published epic branch local-only: {msg}"
                );
                assert!(
                    !msg.contains("not pushed to origin"),
                    "must not claim an unverified missing push: {msg}"
                );
                assert!(
                    msg.contains("IS published on origin"),
                    "must state the verified push state: {msg}"
                );
                assert!(
                    msg.contains("not merged into the epic tip"),
                    "must name the real gap (unmerged worker branch): {msg}"
                );
                // The epic handoff STYLE is unchanged: still no PR instruction,
                // still a supervisor-merge request.
                assert!(
                    !msg.contains("Open a PR targeting"),
                    "epic parents never get PR instructions: {msg}"
                );
                assert!(
                    msg.contains("NOT run `gh pr create --base epic/x`"),
                    "must still steer away from gh pr create: {msg}"
                );
                assert!(
                    msg.contains("supervisor to merge"),
                    "must still hand off a supervisor merge: {msg}"
                );
            }
            other => panic!("expected Reject for stranded factory branch, got {other:?}"),
        }
    }

