    /// cas-f1f4 (GH #1087): the gabber-studio cas-4c7d sequence through the
    /// real handler. A worker parks task A's anchor, commits task B on top in
    /// the same checkout, and the supervisor's close of A (which has no
    /// validated task worktree) used to be refused with "PRE-CLOSE HOOK
    /// CONTEXT REJECTED … not reachable from the validated task worktree".
    /// It must instead reach the merge gate and park A as awaiting_merge.
    #[tokio::test]
    async fn supervisor_close_of_stacked_delivery_parks_for_merge_cas_f1f4() {
        use crate::mcp::CasService;
        use crate::store::{
            open_agent_store, open_rule_store, open_skill_store, open_store, open_task_store,
            open_worktree_store,
        };
        use cas_types::{Agent, AgentRole, WorkTarget};

        let mut env = TestEnvGuard::temp_home();
        let dir = tempfile::tempdir().unwrap();
        let p = dir.path();
        git(p, &["init", "-q", "-b", "main"]);
        std::fs::write(p.join("seed.txt"), "seed\n").unwrap();
        git(p, &["add", "seed.txt"]);
        git(p, &["commit", "-q", "-m", "seed"]);
        let cas_dir = p.join(".cas");
        std::fs::create_dir_all(&cas_dir).unwrap();
        std::fs::write(
            cas_dir.join("config.toml"),
            "[project]\ncanonical_id = \"cas-f1f4-fixture\"\n\n[verification]\nenabled = false\n[qa]\nmode='per_task'\n",
        )
        .unwrap();
        std::fs::write(p.join(".gitignore"), ".cas/\n").unwrap();
        git(p, &["add", ".gitignore"]);
        git(p, &["commit", "-q", "-m", "ignore store"]);

        // The worker's checkout: task A, then task B stacked on it.
        let worktrees = tempfile::tempdir().unwrap();
        let wt = worktrees.path().join("watchful-dolphin-12");
        git(
            p,
            &["worktree", "add", "-q", "-b", "factory/watchful-dolphin-12", wt.to_str().unwrap(), "main"],
        );
        std::fs::write(wt.join("task_a.rs"), "pub fn task_a() {}\n").unwrap();
        git(&wt, &["add", "task_a.rs"]);
        git(&wt, &["commit", "-q", "-m", "feat(cas-f1f4-a): task A"]);
        let anchor_a = rev_parse_local(&wt, "HEAD");
        std::fs::write(wt.join("task_b.rs"), "pub fn task_b() {}\n").unwrap();
        git(&wt, &["add", "task_b.rs"]);
        git(&wt, &["commit", "-q", "-m", "feat(cas-f1f4-b): task B on A"]);

        env.set("CAS_ROOT", &cas_dir);
        env.set("XDG_CONFIG_HOME", env.home().join(".config"));
        open_store(&cas_dir).unwrap().init().unwrap();
        open_rule_store(&cas_dir).unwrap().init().unwrap();
        open_skill_store(&cas_dir).unwrap().init().unwrap();
        open_worktree_store(&cas_dir).unwrap().init().unwrap();
        let store = open_task_store(&cas_dir).unwrap();
        store.init().unwrap();
        let agents = open_agent_store(&cas_dir).unwrap();
        agents.init().unwrap();
        let actor = "cas-f1f4-supervisor";
        agents
            .register(&Agent::new_with_role(
                actor.into(),
                "supervisor".into(),
                AgentRole::Supervisor,
            ))
            .unwrap();
        let core = CasCore::with_daemon(cas_dir.clone(), None, None);
        core.set_agent_id_for_testing(actor.into());
        let service = CasService::new(core, None);

        let mut task = worker_task("watchful-dolphin-12");
        task.id = "cas-f1f4-a".into();
        task.task_type = TaskType::Bug;
        task.risk = vec![TaskRisk::None];
        task.deliverables.factory_branch_anchor = Some(anchor_a.clone());
        // User-facing, so the park dispatches an independent QA round.
        task.demo_statement = "Open the composer and the stacked card renders".into();
        task.deliverables.work_target = Some(WorkTarget {
            repo_selector: "project:cas-f1f4-fixture".into(),
            target_branch: "main".into(),
        });
        store.add(&task).unwrap();

        let request = serde_json::from_value(serde_json::json!({
            "action": "close", "id": task.id, "supervisor_override": true,
            "reason": "stacked delivery: task B is built on task A's tip",
        }))
        .unwrap();
        let response = service.task(Parameters(request)).await.unwrap();
        let text = response
            .content
            .into_iter()
            .filter_map(|content| match content.raw {
                rmcp::model::RawContent::Text(text) => Some(text.text),
                _ => None,
            })
            .collect::<Vec<_>>()
            .join("\n");
        assert!(!text.contains("PRE-CLOSE HOOK CONTEXT REJECTED"), "{text}");
        assert!(text.contains("MERGE REQUIRED"), "{text}");
        let parked = store.get(&task.id).unwrap();
        assert_eq!(parked.status, TaskStatus::AwaitingMerge, "{text}");
        assert!(parked.notes.contains("Task parked as awaiting_merge"), "{}", parked.notes);
        assert_eq!(
            parked.deliverables.factory_branch_anchor.as_deref(),
            Some(anchor_a.as_str()),
            "the parked anchor stays task A's commit, not B's tip"
        );
        // QA dispatch ran for the park, bound to A's anchor.
        let rounds = cas_store::list_qa_passes(&cas_dir, &task.id).unwrap();
        assert_eq!(rounds.len(), 1, "{text}");
        assert_eq!(rounds[0].bound_head, anchor_a, "{text}");
    }

    /// What one cas-74cb handler close of a fixture epic produced.
    struct EpicCloseRun {
        is_error: bool,
        text: String,
        elapsed: std::time::Duration,
        task: Task,
    }

    /// Close an epic through the real handler with supervisor_override and a
    /// stranded-branch override, as the cas-f0c7 and cas-459b closes did.
    /// `children` terminal children point at lanes and anchors that are gone
    /// locally and on origin. `checker` is the project's committed
    /// `scripts/check-scoped-test-surface.sh`. `setup` receives the
    /// repository (on `main`, pushed to origin) and returns the epic branch
    /// and its notes.
    #[cfg(unix)]
    async fn run_epic_override_close_cas_74cb(
        children: usize,
        checker: &str,
        setup: impl FnOnce(&std::path::Path) -> (String, String),
    ) -> EpicCloseRun {
        run_epic_close_fixture_cas_7e91e(children, checker, setup, None, false).await
    }

    #[cfg(unix)]
    async fn run_epic_close_fixture_cas_7e91e(
        children: usize,
        checker: &str,
        setup: impl FnOnce(&std::path::Path) -> (String, String),
        ci: Option<(&str, bool)>,
        owner_verification: bool,
    ) -> EpicCloseRun {
        use crate::mcp::CasService;
        use crate::store::{
            open_agent_store, open_rule_store, open_skill_store, open_store, open_task_store,
        };
        use cas_types::{Agent, AgentRole, Dependency, DependencyType};
        use std::os::unix::fs::PermissionsExt;

        let mut env = TestEnvGuard::temp_home();
        let (dir, _bare) = handoff_repo();
        let p = dir.path();
        git(p, &["checkout", "-q", "main"]);
        std::fs::create_dir_all(p.join("scripts")).unwrap();
        std::fs::create_dir_all(p.join("cas-cli/tests")).unwrap();
        // A real integration target, so a resolving checker yields a
        // required target the epic has no receipt for.
        std::fs::write(p.join("cas-cli/tests/epic_proof_test.rs"), "// target\n").unwrap();
        let checker_path = p.join("scripts/check-scoped-test-surface.sh");
        std::fs::write(&checker_path, checker).unwrap();
        std::fs::set_permissions(&checker_path, std::fs::Permissions::from_mode(0o755)).unwrap();
        git(p, &["add", "scripts", "cas-cli"]);
        git(p, &["commit", "-q", "-m", "chore: project surface checker"]);
        git(p, &["push", "-q", "origin", "main"]);
        // Every child lane is gone locally and was never on origin.
        git(p, &["branch", "-D", "factory/worker"]);
        let (epic_branch, epic_notes) = setup(p);
        git(p, &["checkout", "-q", "main"]);
        if let Some((gh_body, _)) = ci {
            let origin = rev_parse_local(p, "origin/main");
            let fake_gh = env.home().join("gh");
            crate::test_paths::warm_stub(&fake_gh, gh_body);
            env.set(crate::github_issue_attach::GH_BIN_ENV, &fake_gh);
            std::fs::write(p.join(".git/info/exclude"), "gh-requests.log\n").unwrap();
            // Keep all Git operations on the local bare fixture while the
            // provider identity remains the explicit GitHub origin.
            let bare = _bare.path().to_str().unwrap();
            git(p, &["config", &format!("url.{bare}.insteadOf"), "https://github.com/acme/epic"]);
            git(p, &["config", "remote.origin.url", "https://github.com/acme/epic"]);
            assert_eq!(origin, rev_parse_local(p, "origin/main"));
        }

        let cas_dir = p.join(".cas");
        std::fs::create_dir_all(&cas_dir).unwrap();
        env.set("CAS_ROOT", &cas_dir);
        env.set("XDG_CONFIG_HOME", env.home().join(".config"));
        std::fs::write(
            cas_dir.join("config.toml"),
            if owner_verification {
                "[verification]\nenabled = true\n"
            } else {
                "[verification]\nenabled = false\n"
            },
        )
        .unwrap();
        open_store(&cas_dir).unwrap().init().unwrap();
        open_rule_store(&cas_dir).unwrap().init().unwrap();
        open_skill_store(&cas_dir).unwrap().init().unwrap();
        let store = open_task_store(&cas_dir).unwrap();
        store.init().unwrap();
        let agents = open_agent_store(&cas_dir).unwrap();
        agents.init().unwrap();
        let actor = "cas-74cb-supervisor";
        agents
            .register(&Agent::new_with_role(
                actor.into(),
                "supervisor".into(),
                AgentRole::Supervisor,
            ))
            .unwrap();
        if owner_verification {
            env.set("CAS_AGENT_ROLE", "supervisor");
            env.set("CAS_FACTORY_SUPERVISOR_CLI", "codex");
        }
        let core = CasCore::with_daemon(cas_dir.clone(), None, None);
        core.set_agent_id_for_testing(actor.into());
        let service = CasService::new(core, None);

        // The epic binds to the store's own repository (`<repo>/.cas`), as a
        // supervisor's epic in the project checkout does.
        let mut epic = Task {
            id: "cas-74cb-epic".to_string(),
            title: "deleted-lane epic".to_string(),
            task_type: TaskType::Epic,
            status: TaskStatus::Open,
            branch: Some(epic_branch),
            risk: vec![TaskRisk::None],
            notes: epic_notes,
            epic_verification_owner: owner_verification.then(|| actor.to_string()),
            ..Default::default()
        };
        epic.deliverables.files_changed = vec!["delivery.rs".to_string()];
        store.add(&epic).unwrap();
        for index in 0..children {
            let mut child = Task {
                id: format!("cas-74cb-child-{index:02}"),
                title: format!("deleted lane child {index}"),
                status: TaskStatus::Closed,
                assignee: Some(format!("gone-{index:02}")),
                ..Default::default()
            };
            child.deliverables.factory_branch_anchor = Some(format!("{:040x}", index + 1));
            child.deliverables.parked_branch = Some(format!("factory/gone-{index:02}"));
            store.add(&child).unwrap();
            store
                .add_dependency(&Dependency::new(
                    child.id.clone(),
                    epic.id.clone(),
                    DependencyType::ParentChild,
                ))
                .unwrap();
        }

        let started = std::time::Instant::now();
        let request: cas_mcp::TaskRequest = serde_json::from_value(serde_json::json!({
            "action": "close",
            "id": epic.id,
            "supervisor_override": !owner_verification && ci.is_none_or(|(_, override_requested)| override_requested),
            "reason": "inspected every terminal child delivery against main",
            "stranded_branch_override": "inspected every child lane: each factory branch and anchor is deleted locally and on origin after its delivery shipped",
        }))
        .unwrap();
        let mut response = service.task(Parameters(request.clone())).await.unwrap();
        if owner_verification {
            assert_ne!(
                store.get(&epic.id).unwrap().status,
                TaskStatus::Closed,
                "epic ownership and assembly proof must not replace the epic verdict: {response:?}"
            );
            let dispatch = cas_store::get_latest_verification_dispatch(&cas_dir, &epic.id)
                .unwrap()
                .expect("owner close must mint the active proof boundary");
            assert_eq!(
                dispatch.repository.as_ref().unwrap().head_commit,
                rev_parse_local(p, &format!("origin/{}", epic.branch.as_deref().unwrap())),
                "epic dispatch must bind the published epic, never the unrelated supervisor HEAD"
            );
            assert_ne!(dispatch.repository.as_ref().unwrap().head_commit, rev_parse_local(p, "HEAD"));
            assert!(!dispatch.repository.as_ref().unwrap().anchor_commits.contains(&rev_parse_local(p, "HEAD")));
            let reject = serde_json::from_value(serde_json::json!({
                "action": "add", "task_id": epic.id, "dispatch_id": dispatch.id,
                "verification_type": "epic", "status": "rejected",
                "summary": "Step 0A: REJECT stale epic flow walk; assembled tip differs from the recorded walk. Live deployment evidence is retained; current-tip evidence is owed.",
            })).unwrap();
            let verdict = service.verification(Parameters(reject)).await.unwrap();
            assert_ne!(verdict.is_error, Some(true), "{verdict:?}");
            let latest = crate::store::open_verification_store(&cas_dir)
                .unwrap()
                .get_latest_for_task_by_type(&epic.id, VerificationType::Epic)
                .unwrap()
                .unwrap();
            assert_eq!(latest.status, VerificationStatus::Rejected);
            assert_eq!(latest.dispatch_id.as_deref(), Some(dispatch.id.as_str()));
            assert_ne!(store.get(&epic.id).unwrap().status, TaskStatus::Closed);

            // A rejected walk remains in the audit log. A corrected evidence
            // review gets a new exact dispatch, rather than reusing rejection.
            response = service.task(Parameters(request.clone())).await.unwrap();
            assert_ne!(
                store.get(&epic.id).unwrap().status,
                TaskStatus::Closed,
                "{response:?}"
            );
            let fresh = cas_store::get_latest_verification_dispatch(&cas_dir, &epic.id)
                .unwrap()
                .unwrap();
            assert_ne!(fresh.id, dispatch.id);
            let approve = serde_json::from_value(serde_json::json!({
                "action": "add", "task_id": epic.id, "dispatch_id": fresh.id,
                "verification_type": "epic", "status": "approved",
                "summary": "Fixture: current-tip assembly and epic walk accepted after the recorded stale-walk rejection.",
            })).unwrap();
            let verdict = service.verification(Parameters(approve)).await.unwrap();
            assert_ne!(verdict.is_error, Some(true), "{verdict:?}");
            response = service.task(Parameters(request)).await.unwrap();
        }
        let elapsed = started.elapsed();
        let text = response
            .content
            .iter()
            .filter_map(|content| match &content.raw {
                rmcp::model::RawContent::Text(text) => Some(text.text.clone()),
                _ => None,
            })
            .collect::<Vec<_>>()
            .join("\n");
        let text = format!("{text}\nRequests: {}", std::fs::read_to_string(p.join("gh-requests.log")).unwrap_or_default());
        EpicCloseRun {
            is_error: response.is_error == Some(true),
            text,
            elapsed,
            task: store.get(&epic.id).unwrap(),
        }
    }


    // Real close-handler controls: the epic tip is an ancestor of main, so
    // CI must belong to origin/main itself, never the old epic tip.
    #[cfg(unix)]
    async fn landed_epic_ci_close_cas_7e91e(
        queue: &str,
        checks: &str,
        override_requested: bool,
    ) -> EpicCloseRun {
        let gh = format!(
            r#"#!/bin/sh
printf '%s\n' "$*" >> gh-requests.log
case "$1 $2" in
'repo view') printf '%s\n' '{{"nameWithOwner":"acme/epic"}}' ;;
'api graphql') printf '%s\n' '{queue}' ;;
'api --method')
  expected="repos/acme/epic/commits/$(git rev-parse origin/main)/check-runs"
  [ "$4" = "$expected" ] || exit 97
  printf '%s\n' '{checks}' ;;
*) exit 97 ;;
esac
"#
        );
        run_epic_close_fixture_cas_7e91e(
            0,
            "#!/bin/sh\ncat >/dev/null\n",
            |p| {
                git(p, &["branch", "epic/landed", "main"]);
                std::fs::write(p.join("delivery.js"), "export const delivered = true;\n").unwrap();
                git(p, &["add", "delivery.js"]);
                git(p, &["commit", "-q", "-m", "main integration"]);
                git(p, &["push", "-q", "origin", "main"]);
                ("epic/landed".into(), String::new())
            },
            Some((&gh, override_requested)),
            false,
        )
        .await
    }

    #[cfg(unix)]
    #[tokio::test]
    async fn epic_close_requires_exact_main_ci_without_queue_cas_7e91e() {
        for checks in [
            r#"{"check_runs":[]}"#,
            r#"{"check_runs":[{"name":"Tests","status":"completed","conclusion":"cancelled"}]}"#,
            r#"{"check_runs":[{"name":"Tests","status":"completed","conclusion":"startup_failure"}]}"#,
            r#"{"check_runs":[{"name":"Tests","status":"completed","conclusion":"skipped"}]}"#,
            r#"{"check_runs":[{"name":"Tests","status":"queued","conclusion":null}]}"#,
            r#"{"check_runs":[{"name":"Tests","status":"completed","conclusion":"failure"}]}"#,
            r#"{"check_runs":[{"name":"Tests","status":"completed","conclusion":"neutral"}]}"#,
            r#"{"check_runs":[{"name":"Tests","status":"completed","conclusion":"skipped"},{"name":"Lint","status":"completed","conclusion":"success"}]}"#,
            r#"{"check_runs":[{"name":"Tests","conclusion":"success"}]}"#,
            r#"{"check_runs":[{"name":"Tests","head_sha":"wrong-sha","status":"completed","conclusion":"success"}]}"#,
            r#"{"total_count":101,"check_runs":[{"name":"Tests","status":"completed","conclusion":"success"}]}"#,
        ] {
            let run = landed_epic_ci_close_cas_7e91e(
                r#"{"data":{"repository":{"mergeQueue":null}}}"#,
                checks,
                false,
            )
            .await;
            assert!(run.is_error, "untested main must be refused: {}", run.text);
            assert_ne!(run.task.status, TaskStatus::Closed, "{}", run.text);
            assert!(
                run.text.contains("EPIC CI REQUIRED")
                    && run.text.contains("supervisor_override=true"),
                "{}",
                run.text
            );
        }
    }

    #[cfg(unix)]
    #[tokio::test]
    async fn epic_close_green_main_and_queue_controls_cas_7e91e() {
        let green = landed_epic_ci_close_cas_7e91e(
            r#"{"data":{"repository":{"mergeQueue":null}}}"#,
            r#"{"check_runs":[{"name":"Tests","status":"completed","conclusion":"success"}]}"#,
            false,
        )
        .await;
        assert!(!green.is_error, "{}", green.text);
        assert_eq!(green.task.status, TaskStatus::Closed, "{}", green.text);
        assert!(
            green.text.contains("branch=main")
                && green.text.contains("owner=acme")
                && green.text.contains("name=epic"),
            "{}",
            green.text
        );
        assert!(green.text.contains("/check-runs"), "{}", green.text);
        assert!(
            green.task.notes.contains("CI") && green.task.notes.contains("origin/main"),
            "{}",
            green.task.notes
        );

        let queued = landed_epic_ci_close_cas_7e91e(
            r#"{"data":{"repository":{"mergeQueue":{"id":"queue"}}}}"#,
            r#"{"check_runs":[]}"#,
            false,
        )
        .await;
        assert!(!queued.is_error, "{}", queued.text);
        assert_eq!(queued.task.status, TaskStatus::Closed);
        assert!(
            !queued.text.contains("/check-runs"),
            "queue proof must not add a CI run or lookup: {}",
            queued.text
        );

        let overridden = landed_epic_ci_close_cas_7e91e(
            r#"{"data":{"repository":{"mergeQueue":null}}}"#,
            r#"{"check_runs":[]}"#,
            true,
        )
        .await;
        assert!(!overridden.is_error, "{}", overridden.text);
        assert_eq!(overridden.task.status, TaskStatus::Closed);
        assert!(
            overridden.task.notes.contains("EPIC CI REQUIRED"),
            "override must audit refusal: {}",
            overridden.task.notes
        );
    }

    #[cfg(unix)]
    #[tokio::test]
    async fn epic_close_unknown_queue_preserves_existing_containment_cas_7e91e() {
        for queue in [
            "not-json",
            r#"{"data":{"repository":null}}"#,
            r#"{"errors":[{"message":"forbidden"}],"data":{"repository":{"mergeQueue":null}}}"#,
            r#"{"data":{"repository":{"mergeQueue":{}}}}"#,
        ] {
            let run = landed_epic_ci_close_cas_7e91e(
                queue,
                r#"{"check_runs":[{"name":"Tests","status":"completed","conclusion":"success"}]}"#,
                false,
            )
            .await;
            assert!(
                !run.is_error,
                "unknown queue preserves prior behaviour: {}",
                run.text
            );
            assert_eq!(run.task.status, TaskStatus::Closed);
            assert!(
                run.task.notes.contains("merge queue state is unconfirmed"),
                "{}",
                run.task.notes
            );
            assert!(
                !run.text.contains("/check-runs"),
                "unknown queue adds no CI policy: {}",
                run.text
            );
        }
    }

    #[cfg(unix)]
    #[tokio::test]
    async fn epic_close_exact_default_assembly_receipt_cas_7e91e() {
        for queue in [
            r#"{"data":{"repository":{"mergeQueue":null}}}"#,
            r#"{"data":null}"#,
        ] {
            let gh = format!(
                r#"#!/bin/sh
case "$1 $2" in
'repo view') printf '%s\n' '{{"nameWithOwner":"acme/epic"}}' ;;
'api graphql') printf '%s\n' '{queue}' ;;
*) exit 97 ;;
esac
"#
            );
            for current in [false, true] {
                let run = run_epic_close_fixture_cas_7e91e(0, "#!/bin/sh\ncat >/dev/null\n", |p| {
                let old = rev_parse_local(p, "main");
                git(p, &["branch", "epic/landed", "main"]);
                std::fs::write(p.join("delivery.js"), "export const integrated = true;\n").unwrap();
                git(p, &["add", "delivery.js"]);
                git(p, &["commit", "-q", "-m", "main integration"]);
                git(p, &["push", "-q", "origin", "main"]);
                let head = if current { rev_parse_local(p, "main") } else { old };
                ("epic/landed".into(), format!("ASSEMBLY_PROOF: head={head} result=PASS command=integrated-suite log=assembly.log"))
            }, Some((&gh, false)), false).await;
                let closes = current || queue == r#"{"data":null}"#;
                assert_eq!(run.is_error, !closes, "{}", run.text);
                assert_eq!(
                    run.task.status == TaskStatus::Closed,
                    closes,
                    "{}",
                    run.text
                );
            }
        }
    }

    /// A surface checker that resolves at once and requires a real target.
    #[cfg(unix)]
    const FAST_REQUIRING_CHECKER_CAS_74CB: &str = concat!(
        "#!/usr/bin/env bash\n",
        "cat > /dev/null\n",
        "printf '%s\\n' 'SCOPED_PROOF_TARGET_ARGS: --test epic_proof_test'\n",
    );

    /// Commit an unreleased epic lane `epic/unreleased` and return its tip.
    #[cfg(unix)]
    fn unreleased_epic_lane_cas_74cb(p: &std::path::Path) -> String {
        git(p, &["checkout", "-q", "-b", "epic/unreleased", "main"]);
        std::fs::write(p.join("epic.rs"), "// unreleased epic work\n").unwrap();
        git(p, &["add", "epic.rs"]);
        git(p, &["commit", "-q", "-m", "feat: unreleased epic work"]);
        let tip = git_command(p, &["rev-parse", "HEAD"]).output().unwrap();
        String::from_utf8(tip.stdout).unwrap().trim().to_string()
    }

    /// cas-74cb: the cas-f0c7 production shape through the real handler. A
    /// supervisor override close of an epic whose 64 terminal children point
    /// at factory lanes and anchors deleted both locally and on origin must
    /// return inside the 55 s MCP deadline and close the epic. On the released runtime the
    /// epic merge gate finished in about 8.5 s (cas-9069 bounds it), then the
    /// scoped-proof gate spawned the project's surface checker over the
    /// epic's whole attributed diff with no bound: 38 s for 1228 paths, then a
    /// second run to build the suggested command. This fixture's checker
    /// sleeps past the deadline instead. The epic tip is contained in main
    /// (released), so the close defers its build proof to that assembly.
    #[cfg(unix)]
    #[tokio::test]
    async fn epic_override_close_with_deleted_child_lanes_closes_in_budget_cas_74cb() {
        let run = run_epic_override_close_cas_74cb(
            64,
            "#!/usr/bin/env bash\nsleep 60\n",
            |_| ("main".to_string(), String::new()),
        )
        .await;
        assert!(
            run.elapsed < std::time::Duration::from_secs(30),
            "epic override close must answer inside the MCP deadline, took {:?}: {}",
            run.elapsed,
            run.text
        );
        assert!(!run.is_error, "{}", run.text);
        assert_eq!(run.task.status, TaskStatus::Closed, "{}", run.text);
        assert!(
            run.task.notes.contains("BUILD PROOF deferred to epic assembly")
                && run.task.notes.contains("already contained in"),
            "the released epic defers to the release's assembly: {}",
            run.task.notes
        );
    }

    /// cas-74cb case (b), the cas-459b / cas-a25c shape: the epic's lane was
    /// deleted after release and its tip is contained in the default branch.
    /// A resolving checker would demand a scoped proof the epic does not
    /// carry; release containment stands for it instead.
    #[cfg(unix)]
    #[tokio::test]
    async fn released_epic_tip_defers_build_proof_cas_74cb() {
        let run = run_epic_override_close_cas_74cb(8, FAST_REQUIRING_CHECKER_CAS_74CB, |p| {
            unreleased_epic_lane_cas_74cb(p);
            git(p, &["checkout", "-q", "main"]);
            git(p, &["merge", "-q", "--no-ff", "epic/unreleased", "-m", "release epic"]);
            git(p, &["push", "-q", "origin", "main"]);
            // The epic lane was never kept on origin; only the local ref the
            // supervisor recreated at the released tip remains.
            git(p, &["branch", "-m", "epic/unreleased", "epic/released"]);
            ("epic/released".to_string(), String::new())
        })
        .await;
        assert!(!run.is_error, "{}", run.text);
        assert_eq!(run.task.status, TaskStatus::Closed, "{}", run.text);
        assert!(
            run.task.notes.contains("already contained in")
                && !run.text.contains("SCOPED_PROOF"),
            "release containment must replace the scoped proof: {}\n{}",
            run.text,
            run.task.notes
        );
    }

    /// cas-74cb case (a): an unreleased epic whose own passing ASSEMBLY_PROOF
    /// head is the epic tip defers to that assembly.
    #[cfg(unix)]
    #[tokio::test]
    async fn epic_with_covering_assembly_proof_defers_build_proof_cas_74cb() {
        let run = run_epic_close_fixture_cas_7e91e(8, FAST_REQUIRING_CHECKER_CAS_74CB, |p| {
            let tip = unreleased_epic_lane_cas_74cb(p);
            git(p, &["push", "-q", "origin", "epic/unreleased"]);
            git(p, &["checkout", "-q", "main"]);
            // A stale local epic ref must not displace its published delivery.
            git(p, &["branch", "-f", "epic/unreleased", "main"]);
            let notes = format!(
                "[2026-10-02 20:00] PROGRESS ASSEMBLY_PROOF: head={tip} result=PASS command=assembly-proof log=/tmp/assembly.log"
            );
            ("epic/unreleased".to_string(), notes)
        }, None, true)
        .await;
        assert!(!run.is_error, "{}", run.text);
        assert_eq!(run.task.status, TaskStatus::Closed, "{}", run.text);
        assert!(
            run.task.notes.contains("BUILD PROOF deferred to epic assembly")
                && run.task.notes.contains("covers its tip"),
            "{}",
            run.task.notes
        );
    }

    /// cas-74cb case (c): an unreleased epic with no covering ASSEMBLY_PROOF
    /// still owes its scoped proof, now under the bounded checker, and the
    /// refusal names the assembly proof an epic should carry.
    #[cfg(unix)]
    #[tokio::test]
    async fn epic_without_assembly_basis_still_owes_build_proof_cas_74cb() {
        let run = run_epic_override_close_cas_74cb(8, FAST_REQUIRING_CHECKER_CAS_74CB, |p| {
            unreleased_epic_lane_cas_74cb(p);
            // A passing proof of some other head does not cover this tip.
            (
                "epic/unreleased".to_string(),
                "[2026-10-02 20:00] PROGRESS ASSEMBLY_PROOF: head=0000000000000000000000000000000000000001 result=PASS command=x log=/tmp/x".to_string(),
            )
        })
        .await;
        assert!(run.is_error, "an unassembled epic must not close: {}", run.text);
        assert_ne!(run.task.status, TaskStatus::Closed, "{}", run.text);
        assert!(
            run.text.contains("TASK CLOSE REJECTED")
                && run.text.contains("ASSEMBLY_PROOF: head=<epic tip sha>"),
            "{}",
            run.text
        );
        assert!(
            run.elapsed < std::time::Duration::from_secs(30),
            "{:?}",
            run.elapsed
        );
    }

