    /// cas-a472: a release-note park (CHANGELOG.md plus a docs/release-notes
    /// draft) opened hub QA on "journeys:HUB-J1..HUB-J11". The installed
    /// binary measured the worker's base lane, which still held a
    /// hub-web/src/main.ts delivery (a Surface-wide path in the catalog).
    /// Measured from the task's own tip, through the real journey catalog
    /// and its helper, a docs-only diff maps to no journey and dispatches no
    /// QA, while the hub-web source path still maps to its journeys.
    #[test]
    fn docs_only_park_maps_to_no_journey_while_hub_source_still_does_cas_a472() {
        let (dir, _bare) = handoff_repo();
        let repo = dir.path();
        let task = worker_task("worker");
        git(repo, &["checkout", "-q", "factory/worker"]);
        std::fs::create_dir_all(repo.join("hub-web/src")).unwrap();
        std::fs::write(repo.join("hub-web/src/main.ts"), "export {};\n").unwrap();
        git(repo, &["add", "hub-web/src/main.ts"]);
        git(repo, &["commit", "-q", "-m", "older hub-web task"]);
        let task_branch = format!("factory/worker-{}", task.id);
        git(repo, &["checkout", "-q", "-b", &task_branch, "main"]);
        std::fs::create_dir_all(repo.join("docs/release-notes")).unwrap();
        std::fs::write(repo.join("CHANGELOG.md"), "# Changelog\n").unwrap();
        std::fs::write(repo.join("docs/release-notes/2026-09-27-v34-slack.md"), "# Draft\n").unwrap();
        git(repo, &["add", "CHANGELOG.md", "docs/release-notes/2026-09-27-v34-slack.md"]);
        git(repo, &["commit", "-q", "-m", "release notes"]);
        let head = rev_parse_local(repo, "HEAD");
        // The project's real catalog and helper, left untracked so they are
        // in neither diff.
        // Embedded at build time: an archived test runs away from the
        // producer checkout, so it must not read it at runtime.
        std::fs::create_dir_all(repo.join("scripts")).unwrap();
        std::fs::create_dir_all(repo.join("docs/qa")).unwrap();
        std::fs::write(
            repo.join("scripts/journeys-for-diff.py"),
            include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/../scripts/journeys-for-diff.py")),
        )
        .unwrap();
        std::fs::write(
            repo.join("docs/qa/journeys.md"),
            include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/../docs/qa/journeys.md")),
        )
        .unwrap();
        let qa = crate::config::QaConfig::default();

        let docs = crate::qa_pass::changed_paths_for_delivery(repo, "main", &head).unwrap();
        assert_eq!(docs, vec!["CHANGELOG.md", "docs/release-notes/2026-09-27-v34-slack.md"]);
        let docs_journeys = crate::qa_pass::catalog_journeys_for(repo, None, &docs);
        assert!(docs_journeys.is_empty(), "a docs-only diff maps to no journey: {docs_journeys:?}");
        assert!(
            !crate::qa_pass::user_facing_reasons(&task, &qa, Some(&docs), &docs_journeys).is_eligible(),
            "a docs-only park dispatches no independent QA",
        );

        let lane = crate::qa_pass::changed_paths_for_delivery(repo, "main", "factory/worker").unwrap();
        assert!(lane.contains(&"hub-web/src/main.ts".to_string()), "{lane:?}");
        let lane_journeys = crate::qa_pass::catalog_journeys_for(repo, None, &lane);
        assert!(
            ["HUB-J1", "HUB-J8", "HUB-J12"].iter().all(|id| lane_journeys.iter().any(|journey| journey == id)),
            "hub-web/src/main.ts is Surface-wide and maps to every hub journey: {lane_journeys:?}",
        );
        let reasons = crate::qa_pass::user_facing_reasons(&task, &qa, Some(&lane), &lane_journeys).reasons;
        assert!(reasons.iter().any(|reason| reason.starts_with("journeys:HUB-J1")), "{reasons:?}");

        let one = crate::qa_pass::catalog_journeys_for(repo, None, &["hub-web/src/connection.ts".to_string()]);
        assert!(
            !one.is_empty() && one.len() < lane_journeys.len(),
            "a narrower hub-web source path maps to its own journeys, not all: {one:?}",
        );
    }

    /// cas-93db fixture (the cas-1451 shape): the worker's plain
    /// `factory/worker` ends in cas-0906's delivery, already merged into the
    /// target; this task's commit, when `with_delivery`, sits on the per-task
    /// branch the worker opened for another task, `factory/worker-cas-6b75`.
    fn plain_branch_claims_another_task_fixture(with_delivery: bool) -> TempDir {
        let dir = init_factory_repo("worker");
        let p = dir.path();
        std::fs::write(p.join("other.rs"), "fn other() {}\n").unwrap();
        git(p, &["add", "other.rs"]);
        git(p, &["commit", "-q", "-m", "fix(task): another task's delivery (cas-0906)"]);
        git(p, &["checkout", "-q", "main"]);
        git(p, &["merge", "-q", "--no-ff", "factory/worker", "-m", "Merge branch 'factory/worker'"]);
        git(p, &["checkout", "-q", "-b", "factory/worker-cas-6b75", "main"]);
        std::fs::write(p.join("prior.rs"), "fn prior() {}\n").unwrap();
        git(p, &["add", "prior.rs"]);
        git(p, &["commit", "-q", "-m", "fix(task): the per-task branch's own task (cas-6b75)"]);
        if with_delivery {
            std::fs::write(p.join("mine.rs"), "fn mine() {}\n").unwrap();
            git(p, &["add", "mine.rs"]);
            git(p, &["commit", "-q", "-m", "fix(task): this task's delivery (cas-test1)"]);
        }
        git(p, &["checkout", "-q", "main"]);
        dir
    }

    /// cas-93db: closing a task whose commit lives on another per-task branch
    /// measures the branch whose commits claim it, never the plain branch
    /// that ends in another task's merged delivery.
    #[test]
    fn close_binds_the_branch_claiming_the_task_not_a_plain_branch_claiming_another_cas_93db() {
        let dir = plain_branch_claims_another_task_fixture(true);
        let p = dir.path();
        let task = worker_task("worker");
        assert_eq!(close_measured_factory_branch(p, &task, "worker"), "factory/worker-cas-6b75");
        match run_factory_branch_merge_gate(&task, &base_req(&task.id), "main", p) {
            MergeStateGateOutcome::Reject(message) => {
                assert!(message.contains("factory/worker-cas-6b75"), "{message}")
            }
            other => panic!("the unmerged delivery must not close against cas-0906's tip: {other:?}"),
        }
    }

    /// cas-93db: when no branch claims the task and the plain branch ends in
    /// another task's delivery, close refuses with a reason instead of
    /// binding to that delivery.
    #[test]
    fn close_refuses_when_only_a_plain_branch_claiming_another_task_resolves_cas_93db() {
        let dir = plain_branch_claims_another_task_fixture(false);
        let p = dir.path();
        let task = worker_task("worker");
        assert_ne!(close_measured_factory_branch(p, &task, "worker"), "factory/worker");
        match run_factory_branch_merge_gate(&task, &base_req(&task.id), "main", p) {
            MergeStateGateOutcome::Unresolved(message) => {
                assert!(message.contains("DELIVERY BRANCH UNRESOLVED"), "{message}");
                assert!(message.contains("cas-0906"), "{message}");
            }
            other => panic!("another task's merged delivery must not close this task: {other:?}"),
        }
    }

    fn transferred_delivery_gh1180() -> (TempDir, Task, String) {
        let dir = init_factory_repo("original");
        let p = dir.path();
        std::fs::write(p.join("delivered.rs"), "fn delivered() {}\n").unwrap();
        git(p, &["add", "delivered.rs"]);
        git(p, &["commit", "-q", "-m", "finished delivery"]);
        let anchor = head_sha(p);
        git(p, &["checkout", "-q", "-b", "factory/receiver", "main"]);
        std::fs::write(p.join("other.rs"), "fn other() {}\n").unwrap();
        git(p, &["add", "other.rs"]);
        git(p, &["commit", "-q", "-m", "other work (cas-0906)"]);
        git(p, &["checkout", "-q", "main"]);
        git(p, &["merge", "-q", "--no-ff", "factory/original", "-m", "merge delivery"]);
        let mut task = worker_task("receiver");
        task.deliverables.parked_branch = Some("factory/original".into());
        task.deliverables.factory_branch_anchor = Some(anchor.clone());
        (dir, task, anchor)
    }

    #[test]
    fn transferred_merged_delivery_resolves_parked_branch_gh1180() {
        let (dir, task, anchor) = transferred_delivery_gh1180();
        let p = dir.path();
        assert_eq!(
            resolve_close_delivery_branch(p, &task, "receiver").unwrap(),
            "factory/original",
        );
        let mut req = base_req(&task.id);
        let merge_receipt = head_sha(p);
        let window = window_at(1_000_000_000, "latest task lease claim/transfer");
        for receipt in [&anchor, &merge_receipt] {
            req.commit_receipt = Some(receipt.clone());
            let out = run_factory_branch_merge_gate_with_attribution(
                &task, &req, "main", p,
                TaskCommitAttribution { receipt: Some(receipt), window: Some(&window) },
            );
            assert!(matches!(out, MergeStateGateOutcome::Proceed | MergeStateGateOutcome::ProceedWithNote(_)), "{out:?}");
        }
    }

    #[test]
    fn transferred_merged_delivery_resolves_remote_handoff_branch_gh1180() {
        let (dir, mut task, anchor) = transferred_delivery_gh1180();
        let p = dir.path();
        git(p, &["update-ref", "refs/remotes/origin/factory/original", &anchor]);
        git(p, &["branch", "-D", "factory/original"]);
        task.deliverables.parked_branch = None;
        task.deliverables.record_handoff_branch("factory/original");
        assert_eq!(
            resolve_close_delivery_branch(p, &task, "receiver").unwrap(),
            "origin/factory/original",
        );
        let out = run_factory_branch_merge_gate(&task, &base_req(&task.id), "main", p);
        assert!(matches!(out, MergeStateGateOutcome::Proceed), "{out:?}");
    }

