    #[test]
    fn transferred_merged_delivery_missing_branch_validates_receipt_gh1180() {
        let (dir, mut task, receipt) = transferred_delivery_gh1180();
        let p = dir.path();
        git(p, &["branch", "-D", "factory/original"]);
        task.deliverables.factory_branch_anchor = None;
        let mut req = base_req(&task.id);
        let window = window_at(1_000_000_000, "latest task lease claim/transfer");
        let unmerged = rev_parse_local(p, "factory/receiver");
        for (supplied, refusal) in [
            ("not-a-commit", Some("hexadecimal")),
            (unmerged.as_str(), Some("not an ancestor")),
            (receipt.as_str(), None),
        ] {
            req.commit_receipt = Some(supplied.into());
            let out = run_factory_branch_merge_gate_with_attribution(
                &task, &req, "main", p,
                TaskCommitAttribution { receipt: Some(supplied), window: Some(&window) },
            );
            match (refusal, out) {
                (Some(reason), MergeStateGateOutcome::Unresolved(message)) => {
                    assert!(message.contains(reason), "{message}");
                }
                (None, MergeStateGateOutcome::ProceedWithNote(note)) => {
                    assert!(note.contains(&receipt), "{note}");
                }
                (expected, other) => panic!("expected {expected:?}, got {other:?}"),
            }
        }
    }

    /// cas-a44a: a task reopened and reassigned keeps the previous worker's
    /// `parked_branch`. When the new worker re-parks from its own per-task
    /// branch, the merge-request, close and QA readers all name that branch,
    /// and the anchor is the new tip. The old branch stays a handoff record.
    #[test]
    fn re_park_after_reassignment_records_the_new_workers_branch_cas_a44a() {
        let dir = init_factory_repo("old");
        let p = dir.path();
        git(p, &["checkout", "-q", "-b", "factory/old-cas-test1"]);
        std::fs::write(p.join("draft.md"), "first cycle\n").unwrap();
        git(p, &["add", "draft.md"]);
        git(p, &["commit", "-q", "-m", "first cycle (cas-test1)"]);
        let old_tip = rev_parse_local(p, "HEAD");
        git(p, &["checkout", "-q", "main"]);
        git(p, &["merge", "-q", "--no-ff", "factory/old-cas-test1", "-m", "merge first cycle"]);
        git(p, &["checkout", "-q", "-b", "factory/new-cas-test1"]);
        std::fs::write(p.join("draft.md"), "second cycle\n").unwrap();
        git(p, &["add", "draft.md"]);
        git(p, &["commit", "-q", "-m", "second cycle (cas-test1)"]);
        let new_tip = rev_parse_local(p, "HEAD");
        git(p, &["checkout", "-q", "main"]);

        // Reopened (anchor retired) and reassigned to `new`.
        let mut task = worker_task("new");
        task.deliverables.parked_branch = Some("factory/old-cas-test1".into());
        task.deliverables.factory_branch_anchor = Some(old_tip.clone());
        task.deliverables.retain_factory_branch_anchor_as_history();

        // The re-park records what the merge gate measured.
        let measured = close_measured_factory_branch(p, &task, "new");
        let measured_tip = resolve_branch_sha(p, &measured);
        task.deliverables
            .record_park(Some(&measured), measured_tip.as_deref(), Some("new"));
        task.status = TaskStatus::AwaitingMerge;

        assert_eq!(task.deliverables.factory_branch_anchor.as_deref(), Some(new_tip.as_str()));
        assert_eq!(
            crate::prompt_revalidation::merge_request_branch(Some(&task), Some(p)).as_deref(),
            Some("factory/new-cas-test1"),
            "the merge-request reader names the new worker's branch"
        );
        assert_eq!(close_measured_factory_branch(p, &task, "new"), "factory/new-cas-test1");
        assert_eq!(
            task.deliverables.parked_branch.as_deref(),
            Some("factory/new-cas-test1")
        );
        assert!(
            task.deliverables
                .handoff_branches
                .iter()
                .any(|branch| branch == "factory/old-cas-test1"),
            "the previous worker's branch stays linked to the task: {:?}",
            task.deliverables.handoff_branches
        );
        assert!(task.deliverables.historical_factory_branch_anchors.contains(&old_tip));
    }

    /// cas-a44a: an AwaitingMerge retry after a handoff to the supervisor
    /// keeps the parked branch; a re-park on the same branch keeps the
    /// commit-time anchor.
    #[test]
    fn re_park_on_the_same_branch_keeps_its_records_cas_a44a() {
        let mut deliverables = cas_types::TaskDeliverables {
            parked_branch: Some("factory/worker-cas-test1".into()),
            factory_branch_anchor: Some("a".repeat(40)),
            ..Default::default()
        };
        deliverables.record_park(Some("origin/factory/worker-cas-test1"), Some(&"b".repeat(40)), Some("worker"));
        assert_eq!(deliverables.parked_branch.as_deref(), Some("factory/worker-cas-test1"));
        assert_eq!(deliverables.factory_branch_anchor, Some("a".repeat(40)));
        assert!(deliverables.handoff_branches.is_empty());
    }

    #[test]
    fn per_task_close_ignores_legacy_start_on_parked_lane_gh1353() {
        let dir = init_factory_repo("worker");
        let p = dir.path();
        let base = head_sha(p);
        std::fs::create_dir_all(p.join(".cas")).unwrap();
        std::fs::write(p.join(".cas/config.toml"), "[project]\ncanonical_id = \"gh1353\"\n").unwrap();
        let target = cas_types::WorkTarget {
            repo_selector: "project:gh1353".into(), target_branch: "main".into(),
        };
        // The old runtime recorded the reusable lane, which still backs
        // the parked task's open PR. It must never be suggested for push.
        std::fs::write(p.join("parked.rs"), "// parked\n").unwrap();
        git(p, &["add", "parked.rs"]);
        git(p, &["commit", "-q", "-m", "parked work"]);
        let parked = head_sha(p);
        git(p, &["checkout", "-q", "-b", "factory/worker-cas-test1", "main"]);
        std::fs::write(p.join("own.rs"), "// own\n").unwrap();
        git(p, &["add", "own.rs"]);
        git(p, &["commit", "-q", "-m", "fix(cas-test1): own work"]);
        let tip = head_sha(p);
        let mut task = worker_task("worker");
        task.deliverables.work_target = Some(target.clone());
        task.deliverables.factory_branch_start = Some(cas_types::FactoryBranchStart {
            work_target: target, assignee: "worker".into(),
            branch: "factory/worker".into(), base_sha: base.clone(),
        });
        let branch = resolve_close_delivery_branch(p, &task, "worker").unwrap();
        assert_eq!(branch, "factory/worker-cas-test1");
        let refusal = unpushed_delivery_tip_refusal(&branch, &tip, &base);
        assert!(refusal.contains("git push origin factory/worker-cas-test1"), "{refusal}");
        assert!(!refusal.contains("git push origin factory/worker`"), "{refusal}");
        assert_eq!(head_sha(p), tip);
        assert_eq!(rev_parse_local(p, "factory/worker"), parked);
    }

    /// cas-985f: merging the released trunk into an epic-bound lane, as
    /// instructed and without a rebase, brings other tasks' released commits.
    /// They are upstream, so the lane still resolves to its own commit; an
    /// unreleased branch carrying another task's work is still refused.
    #[test]
    fn merging_released_main_into_an_epic_lane_is_upstream_but_unreleased_work_is_foreign_cas_985f() {
        let mut failures = Vec::new();
        for (merged, foreign, shadow, octopus) in [
            ("main", false, false, false),
            ("factory/other-cas-0e2b", true, false, false),
            // cas-77b81: a branch cannot impersonate the released remote.
            ("factory/other-cas-0e2b", true, true, false),
            // Each side parent may independently belong to target or trunk.
            ("main", false, false, true),
        ] {
            let dir = init_factory_repo_with_parent("worker", "main");
            let p = dir.path();
            std::fs::create_dir_all(p.join(".cas")).unwrap();
            std::fs::write(p.join(".cas/config.toml"), "[project]\ncanonical_id = \"cas985f\"\n").unwrap();
            git(p, &["branch", "epic/next", "main"]);
            git(p, &["checkout", "-q", "-b", "factory/worker-cas-test1", "epic/next"]);
            let base = head_sha(p);
            std::fs::write(p.join("own.rs"), "// own\n").unwrap();
            git(p, &["add", "own.rs"]);
            git(p, &["commit", "-q", "-m", "fix(cas-test1): own work"]);
            let own = head_sha(p);
            // Released on main by another task, after this lane started.
            git(p, &["checkout", "-q", "main"]);
            std::fs::write(p.join("released.rs"), "// released\n").unwrap();
            git(p, &["add", "released.rs"]);
            git(p, &["commit", "-q", "-m", "fix(cas-0e1a): released work"]);
            git(p, &["checkout", "-q", "-b", "factory/other-cas-0e2b", "main"]);
            std::fs::write(p.join("unreleased.rs"), "// unreleased\n").unwrap();
            git(p, &["add", "unreleased.rs"]);
            git(p, &["commit", "-q", "-m", "fix(cas-0e2b): unreleased work"]);
            if shadow {
                git(p, &["update-ref", "refs/remotes/origin/main", "refs/heads/main"]);
                git(p, &["branch", "origin/main", "factory/other-cas-0e2b"]);
            }
            if octopus {
                git(p, &["checkout", "-q", "epic/next"]);
                commit_local(p, "epic.rs", "fix(cas-0e3b): integrated epic work");
            }
            git(p, &["checkout", "-q", "factory/worker-cas-test1"]);
            if octopus {
                git(p, &["merge", "-q", "--no-ff", "--no-edit", "epic/next", "main"]);
                let parents = git_stdout_lines(p, &["rev-list", "--parents", "-n", "1", "HEAD"]).unwrap();
                assert_eq!(parents[0].split_whitespace().count(), 4);
            } else {
                git(p, &["merge", "-q", "--no-ff", "--no-edit", merged]);
            }
            let target = cas_types::WorkTarget {
                repo_selector: "project:cas985f".into(), target_branch: "epic/next".into(),
            };
            let mut task = worker_task("worker");
            task.deliverables.work_target = Some(target.clone());
            task.deliverables.factory_branch_start = Some(cas_types::FactoryBranchStart {
                work_target: target, assignee: "worker".into(),
                branch: "factory/worker-cas-test1".into(), base_sha: base,
            });
            match task_attribution::started_delivery(p, &task) {
                Ok(delivery) if !foreign => {
                    assert_eq!(delivery.map(|d| d.commits), Some(vec![own.clone()]), "merging {merged}");
                }
                Err(error) if foreign => {
                    assert!(error.contains("foreign commit") && error.contains("cas-0e2b"), "{error}");
                }
                other => failures.push(format!("merging {merged}, shadow={shadow}: unexpected {:?}", other.map(|d| d.map(|d| d.commits)))),
            }
            if octopus && !parked_anchor_advance_with_target_is_attributable(
                p, &own, &head_sha(p), &task.id, None, "epic/next",
            ) {
                failures.push("mixed epic/main octopus sync must retain the parked delivery identity".into());
            }
        }
        assert!(failures.is_empty(), "{}", failures.join("\n"));
    }

    /// Without a per-task branch the worker's own branch is measured, as
    /// before.
    #[test]
    fn without_a_per_task_branch_the_worker_branch_is_measured_cas_73b8() {
        let (dir, _bare) = handoff_repo();
        let p = dir.path();
        let task = worker_task("worker");
        assert_eq!(
            close_measured_factory_branch(p, &task, "worker"),
            "factory/worker"
        );
        assert!(worker_task_branch_ref(p, "worker", &task.id).is_none());
    }

    // --- cas-e74c (GH #80 / #62 symptoms 3-4): delivery-scoped guard -------
    //
    // The guard used to evaluate the worker's ENTIRE registered lane
    // branch. Three real deadlocks followed: a cherry-pick delivery from a
    // reused lane could never close even with a valid, target-reachable
    // `commit_receipt`; a zero-commit task inherited the lane's unrelated
    // commits; and work done on a clean task-local branch, merged before
    // close, still bounced because the guard keyed on the lane name.

    /// Commit with an explicit committer/author date so a test can place
    /// commits before or after a task's attribution window.
    fn git_at(dir: &std::path::Path, args: &[&str], date: &str) {
        let status = Command::new("git")
            .args(args)
            .current_dir(dir)
            .env("GIT_AUTHOR_NAME", "test")
            .env("GIT_AUTHOR_EMAIL", "test@test")
            .env("GIT_COMMITTER_NAME", "test")
            .env("GIT_COMMITTER_EMAIL", "test@test")
            .env("GIT_AUTHOR_DATE", date)
            .env("GIT_COMMITTER_DATE", date)
            .env("GIT_CONFIG_GLOBAL", "/dev/null")
            .env("GIT_CONFIG_SYSTEM", "/dev/null")
            .status()
            .expect("git");
        assert!(status.success(), "git {args:?} failed");
    }

    fn commit_file_at(dir: &std::path::Path, name: &str, body: &str, date: &str) {
        std::fs::write(dir.join(name), body).unwrap();
        git_at(dir, &["add", name], date);
        git_at(dir, &["commit", "-q", "-m", &format!("feat: {name}")], date);
    }

    fn window_at(epoch: i64, basis: &'static str) -> TaskCommitReceiptWindow {
        TaskCommitReceiptWindow {
            supervisor_override_reason: None,
            not_before: chrono::DateTime::from_timestamp(epoch, 0).unwrap(),
            basis,
            task_floor: chrono::DateTime::from_timestamp(epoch, 0).unwrap(),
            identity: TaskCommitIdentity::default(),
        }
    }

    fn head_sha(dir: &std::path::Path) -> String {
        let out = Command::new("git")
            .args(["rev-parse", "HEAD"])
            .current_dir(dir)
            .output()
            .expect("git rev-parse");
        String::from_utf8_lossy(&out.stdout).trim().to_string()
    }

    /// GH #80: the lane carries prior-session commits the supervisor
    /// deliberately refused to merge; the task's own work was cherry-picked
    /// onto the parent and handed back as a `commit_receipt`. The receipt IS
    /// the delivery evidence — close must pass, logging the lane residue.
    #[test]
    fn reused_lane_close_with_valid_receipt_proceeds_with_residue_note() {
        let dir = init_factory_repo("worker");
        let p = dir.path();
        // Two prior-session commits stranded on the reused lane.
        commit_file_at(p, "old-a.rs", "// a\n", "2020-01-01T00:00:00Z");
        commit_file_at(p, "old-b.rs", "// b\n", "2020-01-02T00:00:00Z");
        // This task's delivery, cherry-picked onto main as a new SHA.
        git(p, &["checkout", "-q", "main"]);
        commit_file_at(p, "delivery.rs", "// delivered\n", "2026-08-04T12:00:00Z");
        let receipt = head_sha(p);
        git(p, &["checkout", "-q", "factory/worker"]);

        let task = worker_task("worker");
        let mut req = base_req(&task.id);
        req.commit_receipt = Some(receipt.clone());
        let window = window_at(1_000_000_000, "latest task lease claim/transfer");

        let out = run_factory_branch_merge_gate_with_attribution(
            &task,
            &req,
            "main",
            p,
            TaskCommitAttribution {
                receipt: Some(&receipt),
                window: Some(&window),
            },
        );
        match out {
            MergeStateGateOutcome::ProceedWithNote(note) => {
                assert!(
                    note.contains(&receipt),
                    "note must record the accepted receipt: {note}"
                );
                assert!(
                    note.contains("factory/worker") && note.contains("2 commit"),
                    "note must log the unmerged lane residue: {note}"
                );
            }
            other => panic!("valid receipt must clear the lane guard, got {other:?}"),
        }
    }

    /// cas-da3f (GH #382): a child whose parent epic has not been advanced
    /// after a squash delivery to main must not deadlock. The receipt is the
    /// integration commit (not the rewritten factory SHA), and the note must
    /// preserve the exact stale-epic evidence for later status/review flows.
    #[test]
    fn lagging_clean_epic_accepts_receipt_fully_validated_on_integration_branch() {
        let dir = init_factory_repo("worker");
        let p = dir.path();
        let epic = "epic/lagging-after-main-delivery";

        git(p, &["checkout", "-q", "main"]);
        git(p, &["checkout", "-q", "-b", epic]);
        let epic_tip = head_sha(p);
        git(p, &["checkout", "-q", "factory/worker"]);
        commit_file_at(p, "delivered.rs", "// delivered\n", "2026-08-14T12:00:00Z");

        // GitHub-style squash delivery creates integration commit B rather
        // than retaining worker commit A in main's ancestry.
        git(p, &["checkout", "-q", "main"]);
        git(p, &["merge", "-q", "--squash", "factory/worker"]);
        git_at(
            p,
            &["commit", "-q", "-m", "feat: delivered via squash"],
            "2026-08-14T12:01:00Z",
        );
        let receipt = head_sha(p);
        let integration_tip = receipt.clone();
        assert!(
            git_commit_is_ancestor(p, &epic_tip, &integration_tip),
            "precondition: epic must be a clean ancestor of main"
        );
        assert_ne!(epic_tip, integration_tip, "precondition: epic must lag");
        git(p, &["checkout", "-q", "factory/worker"]);

        let task = worker_task("worker");
        let mut req = base_req(&task.id);
        req.commit_receipt = Some(receipt.clone());
        let window = window_at(1_000_000_000, "latest task lease claim/transfer");
        let out = run_factory_branch_merge_gate_with_attribution(
            &task,
            &req,
            epic,
            p,
            TaskCommitAttribution {
                receipt: Some(&receipt),
                window: Some(&window),
            },
        );

        match out {
            MergeStateGateOutcome::ProceedWithNote(note) => {
                assert!(
                    note.contains("CAS_CLOSE_LAGGING_EPIC_RECEIPT_V1"),
                    "lagging-epic acceptance must be machine-readable: {note}"
                );
                assert!(
                    note.contains("integration_branch=main")
                        && note.contains(&format!("epic_branch={epic}"))
                        && note.contains(&format!("epic_tip={epic_tip}"))
                        && note.contains(&format!("integration_tip={integration_tip}")),
                    "lagging-epic note must retain resolved branch and exact tips: {note}"
                );
                assert!(
                    note.contains(&receipt) && note.contains("accepted commit_receipt"),
                    "the ordinary receipt proof must remain visible in the audit note: {note}"
                );
            }
            other => panic!(
                "clean-behind epic with a receipt fully valid on main must proceed, got {other:?}"
            ),
        }
    }

    /// A diverged epic cannot be advanced safely by a close gate. Even a
    /// receipt valid on main must retain the normal epic-target rejection.
    #[test]
    fn divergent_epic_does_not_accept_main_receipt_fallback() {
        let dir = init_factory_repo("worker");
        let p = dir.path();
        let epic = "epic/diverged-from-main";

        git(p, &["checkout", "-q", "main"]);
        git(p, &["checkout", "-q", "-b", epic]);
        commit_file_at(
            p,
            "epic-only.rs",
            "// explicit epic work\n",
            "2026-08-14T11:00:00Z",
        );
        let epic_tip = head_sha(p);
        git(p, &["checkout", "-q", "factory/worker"]);
        commit_file_at(p, "delivered.rs", "// delivered\n", "2026-08-14T12:00:00Z");

        git(p, &["checkout", "-q", "main"]);
        git(p, &["merge", "-q", "--squash", "factory/worker"]);
        git_at(
            p,
            &["commit", "-q", "-m", "feat: delivered via squash"],
            "2026-08-14T12:01:00Z",
        );
        let receipt = head_sha(p);
        assert!(
            !git_commit_is_ancestor(p, &epic_tip, &receipt),
            "precondition: an epic with its own commit must diverge from main"
        );
        git(p, &["checkout", "-q", "factory/worker"]);

        let task = worker_task("worker");
        let mut req = base_req(&task.id);
        req.commit_receipt = Some(receipt.clone());
        let window = window_at(1_000_000_000, "latest task lease claim/transfer");
        let out = run_factory_branch_merge_gate_with_attribution(
            &task,
            &req,
            epic,
            p,
            TaskCommitAttribution {
                receipt: Some(&receipt),
                window: Some(&window),
            },
        );

        match out {
            MergeStateGateOutcome::Reject(message) => {
                assert!(
                    message.contains("not an ancestor of epic/diverged-from-main"),
                    "divergent epic must retain the detailed epic-target receipt rejection: {message}"
                );
                assert!(
                    !message.contains("CAS_CLOSE_LAGGING_EPIC_RECEIPT_V1"),
                    "a divergent epic must never receive the lagging-epic acceptance: {message}"
                );
            }
            other => panic!("divergent epic must remain fail-closed, got {other:?}"),
        }
    }

    /// GH #62 symptom 4: the delivery lives on a clean task-local branch that
    /// was merged into the parent BEFORE close. The guard must resolve merge
    /// state from the receipt's ancestry, not the registered lane name.
    ///
    /// cas-b62d: the task-local branch must not be named
    /// `factory/<assignee>-<task-id>`. Since cas-73b8 that is the worker's own
    /// per-task branch, which the close gate measures directly (see
    /// `merged_per_task_branch_is_measured_and_proceeds_cas_73b8`). The old
    /// fixture name took that path and never reached the receipt-ancestry
    /// logic this test exists for.
    #[test]
    fn clean_task_local_branch_merged_before_close_proceeds() {
        let dir = init_factory_repo("worker");
        let p = dir.path();
        commit_file_at(p, "unrelated.rs", "// other task\n", "2020-03-01T00:00:00Z");
        // Task work on its own branch, cut from main and merged into main.
        git(p, &["checkout", "-q", "main"]);
        git(p, &["checkout", "-q", "-b", "task-local/cas-test1"]);
        commit_file_at(p, "scoped.rs", "// scoped\n", "2026-08-04T12:00:00Z");
        let receipt = head_sha(p);
        git(p, &["checkout", "-q", "main"]);
        git(
            p,
            &[
                "merge",
                "-q",
                "--no-ff",
                "task-local/cas-test1",
                "-m",
                "merge",
            ],
        );
        git(p, &["checkout", "-q", "factory/worker"]);

        let task = worker_task("worker");
        assert_eq!(
            close_measured_factory_branch(p, &task, "worker"),
            "factory/worker",
            "the fixture must measure the lane, not a cas-73b8 per-task branch"
        );
        let mut req = base_req(&task.id);
        req.commit_receipt = Some(receipt.clone());
        let window = window_at(1_000_000_000, "latest task lease claim/transfer");

        let out = run_factory_branch_merge_gate_with_attribution(
            &task,
            &req,
            "main",
            p,
            TaskCommitAttribution {
                receipt: Some(&receipt),
                window: Some(&window),
            },
        );
        assert!(
            matches!(out, MergeStateGateOutcome::ProceedWithNote(_)),
            "receipt merged into parent before close must clear the guard, got {out:?}"
        );
    }

    /// cas-73b8: a worker whose factory branch was frozen committed this task
    /// on `factory/<assignee>-<task-id>`. The close gate measures that branch
    /// itself, and once it is merged into the parent the guard proceeds with
    /// nothing stranded, even though the lane carries another task's commit.
    #[test]
    fn merged_per_task_branch_is_measured_and_proceeds_cas_73b8() {
        let dir = init_factory_repo("worker");
        let p = dir.path();
        commit_file_at(p, "unrelated.rs", "// other task\n", "2020-03-01T00:00:00Z");
        git(p, &["checkout", "-q", "main"]);
        git(p, &["checkout", "-q", "-b", "factory/worker-cas-test1"]);
        commit_file_at(p, "scoped.rs", "// scoped\n", "2026-08-04T12:00:00Z");
        let receipt = head_sha(p);
        git(p, &["checkout", "-q", "main"]);
        git(
            p,
            &[
                "merge",
                "-q",
                "--no-ff",
                "factory/worker-cas-test1",
                "-m",
                "merge",
            ],
        );
        git(p, &["checkout", "-q", "factory/worker"]);

        let task = worker_task("worker");
        assert_eq!(
            close_measured_factory_branch(p, &task, "worker"),
            "factory/worker-cas-test1"
        );
        let mut req = base_req(&task.id);
        req.commit_receipt = Some(receipt.clone());
        let window = window_at(1_000_000_000, "latest task lease claim/transfer");

        let out = run_factory_branch_merge_gate_with_attribution(
            &task,
            &req,
            "main",
            p,
            TaskCommitAttribution {
                receipt: Some(&receipt),
                window: Some(&window),
            },
        );
        assert!(
            matches!(out, MergeStateGateOutcome::Proceed),
            "a merged per-task branch strands nothing, got {out:?}"
        );
    }

    /// GH #62 symptom 3: an epic-less, zero-commit task inherited the lane's
    /// 34 unrelated commits. No commit is attributable to this task's work
    /// cycle, so the guard must not fire.
    #[test]
    fn zero_task_attributable_commits_proceeds_despite_lane_residue() {
        let dir = init_factory_repo("worker");
        let p = dir.path();
        commit_file_at(p, "other-1.rs", "// 1\n", "2020-01-01T00:00:00Z");
        commit_file_at(p, "other-2.rs", "// 2\n", "2020-01-02T00:00:00Z");

        let task = worker_task("worker");
        let req = base_req(&task.id);
        // Work cycle started long after those commits were made.
        let window = window_at(1_700_000_000, "latest task lease claim/transfer");

        let out = run_factory_branch_merge_gate_with_attribution(
            &task,
            &req,
            "main",
            p,
            TaskCommitAttribution {
                receipt: None,
                window: Some(&window),
            },
        );
        match out {
            MergeStateGateOutcome::ProceedWithNote(note) => {
                assert!(
                    note.contains("2 commit"),
                    "residue must be logged, not fatal: {note}"
                );
            }
            other => {
                panic!("zero task-attributable commits must not trip the guard, got {other:?}")
            }
        }
    }

    /// GH #1028: an override cannot silently discard a pre-task delivery as
    /// lane residue. A receipt identifies the historical tip for the normal
    /// merge gate, and after integration it supplies the QA path attribution.
    #[test]
    fn supervisor_override_requires_receipt_for_pre_task_delivery_gh_1028() {
        let dir = init_factory_repo("worker");
        let p = dir.path();
        commit_file_at(p, "delivery.rs", "// delivered\n", "2020-01-01T00:00:00Z");
        let receipt = head_sha(p);
        let task = worker_task("worker");
        let mut req = base_req(&task.id);
        req.supervisor_override = Some(true);
        req.reason = Some("adopt historical delivery".into());
        let mut window = window_at(1_700_000_000, "latest task lease claim/transfer");
        window.supervisor_override_reason = req.reason.clone();
        window.identity = task_commit_identity(&task, None);

        let close_gate = |request: &TaskCloseRequest, window: &TaskCommitReceiptWindow| {
            run_factory_branch_merge_gate_with_attribution(
                &task,
                request,
                "main",
                p,
                TaskCommitAttribution {
                    receipt: request.commit_receipt.as_deref(),
                    window: Some(window),
                },
            )
        };
        match close_gate(&req, &window) {
            MergeStateGateOutcome::Reject(message) => {
                assert!(message.contains("MERGE REQUIRED"), "{message}");
                assert!(message.contains("commit_receipt"), "{message}");
            }
            other => panic!("historical delivery closed without receipt: {other:?}"),
        }

        let mut test_first_task = task.clone();
        test_first_task.execution_note = Some("test-first".into());
        match run_factory_branch_merge_gate_with_attribution(
            &test_first_task,
            &req,
            "main",
            p,
            TaskCommitAttribution {
                receipt: None,
                window: Some(&window),
            },
        ) {
            MergeStateGateOutcome::Reject(message) => {
                assert!(message.contains("MERGE REQUIRED"), "{message}");
                assert!(message.contains("commit_receipt"), "{message}");
            }
            other => panic!("test-first historical delivery closed without receipt: {other:?}"),
        }

        req.commit_receipt = Some(receipt.clone());
        window.identity.known_commits.push(receipt.clone());
        match close_gate(&req, &window) {
            MergeStateGateOutcome::Reject(message) => {
                assert!(message.contains("MERGE REQUIRED"), "{message}");
            }
            other => panic!("unmerged historical receipt closed: {other:?}"),
        }

        git(p, &["checkout", "-q", "main"]);
        git(p, &["merge", "-q", "--no-ff", "factory/worker", "-m", "merge delivery"]);
        git(p, &["checkout", "-q", "factory/worker"]);
        assert!(matches!(close_gate(&req, &window), MergeStateGateOutcome::Proceed));
        assert!(
            task_attribution::paths(p, "main", &window, Some(&receipt))
                .is_some_and(|paths| paths.iter().any(|path| path == "delivery.rs")),
            "QA must inspect the historical delivery path after merge"
        );
    }

    /// The scoping must not become a bypass: commits made inside the task's
    /// own work cycle and left unmerged still reject, and the count reported
    /// is the task-attributable one (not the whole lane).
    #[test]
    fn task_attributable_unmerged_commits_still_reject() {
        let dir = init_factory_repo("worker");
        let p = dir.path();
        commit_file_at(p, "other-1.rs", "// 1\n", "2020-01-01T00:00:00Z");
        commit_file_at(p, "mine.rs", "// mine\n", "2026-08-04T12:00:00Z");

        let task = worker_task("worker");
        let req = base_req(&task.id);
        let window = window_at(1_700_000_000, "latest task lease claim/transfer");

        let out = run_factory_branch_merge_gate_with_attribution(
            &task,
            &req,
            "main",
            p,
            TaskCommitAttribution {
                receipt: None,
                window: Some(&window),
            },
        );
        match out {
            MergeStateGateOutcome::Reject(msg) => {
                assert!(msg.contains("MERGE REQUIRED"), "missing header: {msg}");
                assert!(
                    msg.contains("1 commit(s) from this task"),
                    "rejection must count only task-attributable commits: {msg}"
                );
            }
            other => panic!("unmerged task-own commits must still reject, got {other:?}"),
        }
    }

    fn commit_file_with_message_at(dir: &std::path::Path, name: &str, message: &str, date: &str) {
        std::fs::write(dir.join(name), format!("// {name}\n")).unwrap();
        git_at(dir, &["add", name], date);
        git_at(dir, &["commit", "-q", "-m", message], date);
    }

    /// cas-2664: after cas-b412 merged, its worker started cas-f0a6 on the
    /// same lane. Closing cas-b412 then counted cas-f0a6's commits as its own
    /// stranded delivery. A commit naming another task is that task's work;
    /// an unlabelled commit inside the window still counts (fail closed).
    #[test]
    fn next_task_commits_on_the_same_lane_are_not_attributed_cas_2664() {
        let dir = init_factory_repo("worker");
        let p = dir.path();
        commit_file_with_message_at(p, "gate.rs", "fix(close): gate (cas-test1)", "2026-08-04T12:00:00Z");
        let anchor = rev_parse_local(p, "HEAD");
        git(p, &["checkout", "-q", "main"]);
        git(p, &["merge", "-q", "--no-ff", "factory/worker", "-m", "merge cas-test1"]);
        git(p, &["checkout", "-q", "factory/worker"]);
        commit_file_with_message_at(p, "snap.rs", "fix(close): snapshot gate (cas-f0a6)", "2026-08-04T13:00:00Z");
        commit_file_with_message_at(p, "more.rs", "test(close): cover it (cas-f0a6)", "2026-08-04T13:05:00Z");

        let mut task = worker_task("worker");
        task.status = TaskStatus::AwaitingMerge;
        task.deliverables.factory_branch_anchor = Some(anchor);
        let req = base_req(&task.id);
        let mut window = window_at(1_700_000_000, "task work cycle");
        window.identity = task_commit_identity(&task, None);
        assert_eq!(
            count_task_attributable_unmerged_commits(p, "factory/worker", "main", &window, None),
            Some(0)
        );
        // Also with a supervisor override and no receipt: the merged anchor
        // identifies the delivery, so the remainder is not pre-task work.
        window.supervisor_override_reason = Some("supervisor close of merged delivery".into());
        match run_factory_branch_merge_gate_with_attribution(
            &task,
            &req,
            "main",
            p,
            TaskCommitAttribution {
                receipt: None,
                window: Some(&window),
            },
        ) {
            MergeStateGateOutcome::Proceed | MergeStateGateOutcome::ProceedWithNote(_) => {}
            other => panic!("the next task's commits must not block this close, got {other:?}"),
        }

        // An unlabelled commit inside the window is still attributed.
        commit_file_with_message_at(p, "anon.rs", "wip", "2026-08-04T13:10:00Z");
        window.supervisor_override_reason = None;
        assert_eq!(
            count_task_attributable_unmerged_commits(p, "factory/worker", "main", &window, None),
            Some(1)
        );
    }

    /// cas-2664 (7), the cas-ef5e shape: lane commit → merge of the epic tip
    /// into the lane (as the supervisor asked, to resolve overlap) → lane
    /// commit. The merged-in epic content is other tasks' delivery; only the
    /// lane's own commits are attributed, for paths, base and diff stat.
    #[test]
    fn target_merged_into_lane_is_not_attributed_to_the_task_cas_2664() {
        let dir = init_factory_repo("worker");
        let p = dir.path();
        commit_file_with_message_at(p, "own-a.rs", "feat: first half (cas-test1)", "2026-08-04T12:00:00Z");
        git(p, &["checkout", "-q", "main"]);
        // Other tasks' deliveries land on the epic (target) meanwhile; one
        // names no task at all.
        commit_file_with_message_at(p, "epic-gate.rs", "fix(close): gate (cas-b412)", "2026-08-04T12:10:00Z");
        commit_file_with_message_at(p, "epic-hook.rs", "hook policy", "2026-08-04T12:20:00Z");
        git(p, &["checkout", "-q", "factory/worker"]);
        git_at(
            p,
            &["merge", "-q", "--no-ff", "main", "-m", "Merge epic tip into factory/worker"],
            "2026-08-04T12:30:00Z",
        );
        commit_file_with_message_at(p, "own-b.rs", "feat: second half (cas-test1)", "2026-08-04T12:40:00Z");

        let task = worker_task("worker");
        let mut window = window_at(0, "task work cycle");
        window.identity = task_commit_identity(&task, None);
        let paths = task_attribution::paths(p, "main", &window, None).expect("attribution");
        assert_eq!(paths, vec!["own-a.rs".to_string(), "own-b.rs".to_string()]);
        let stat = task_attribution::diff_stat(p, "main", &window, None).expect("diff stat");
        assert!(!stat.stat.contains("epic-"), "{}", stat.stat);
        assert!(stat.stat.contains("own-a.rs") && stat.stat.contains("own-b.rs"), "{}", stat.stat);

        // A merge of a branch that is NOT on the target is still attributed.
        git(p, &["checkout", "-q", "-b", "side", "main"]);
        commit_file_with_message_at(p, "side.rs", "side work", "2026-08-04T12:50:00Z");
        git(p, &["checkout", "-q", "factory/worker"]);
        git_at(p, &["merge", "-q", "--no-ff", "side", "-m", "merge side"], "2026-08-04T12:55:00Z");
        let paths = task_attribution::paths(p, "main", &window, None).expect("attribution");
        assert!(paths.contains(&"side.rs".to_string()), "{paths:?}");
        assert!(!paths.iter().any(|path| path.starts_with("epic-")), "{paths:?}");
    }

    #[test]
    fn message_claims_other_task_matches_only_foreign_task_ids_cas_2664() {
        assert!(message_claims_other_task("fix (cas-f0a6)", Some("cas-b412")));
        assert!(!message_claims_other_task("fix (cas-b412)", Some("cas-b412")));
        assert!(!message_claims_other_task("fix cas-b412 per cas-f2eb", Some("cas-b412")));
        assert!(!message_claims_other_task("touch cas-cli and cas-src", Some("cas-b412")));
        assert!(!message_claims_other_task("wip", Some("cas-b412")));
        assert!(message_claims_other_task("CAS-F0A6: thing", Some("cas-b412")));
    }

    /// cas-08f9: a parked delivery bounced for a merge conflict. The worker
    /// rebased (new commit ids, committed before the restart), then ran the
    /// merge-recovery `task start`, which moved the lease window past those
    /// commits and retired the old anchor. The rebased commits name the task,
    /// so they are still this task's unmerged delivery: MERGE REQUIRED, not a
    /// silent pass that later reads as "merged without a QA round".
    #[test]
    fn merge_recovery_rebase_before_restart_is_still_this_tasks_delivery_cas_08f9() {
        let dir = init_factory_repo("worker");
        let p = dir.path();
        // Someone else's residue on the reused lane.
        commit_file_at(p, "other-1.rs", "// 1\n", "2020-01-01T00:00:00Z");
        // The rebased delivery: made before the restart, message names the task.
        commit_file_with_message_at(
            p,
            "fix.rs",
            "hub-web: the fix (cas-test1)",
            "2026-08-04T12:00:00Z",
        );
        commit_file_with_message_at(
            p,
            "dist.js",
            "hub-web: rebuild dist for cas-test1",
            "2026-08-04T12:00:05Z",
        );

        let mut task = worker_task("worker");
        // The pre-rebase anchor survives only as history, under an id the
        // rebase replaced.
        task.deliverables.historical_factory_branch_anchors =
            vec!["0123456789abcdef0123456789abcdef01234567".to_string()];
        let req = base_req(&task.id);
        // The restart's lease claim is later than the rebase.
        let mut window = window_at(1_800_000_000, "latest task lease claim/transfer");
        window.identity = task_commit_identity(&task, None);

        let out = run_factory_branch_merge_gate_with_attribution(
            &task,
            &req,
            "main",
            p,
            TaskCommitAttribution {
                receipt: None,
                window: Some(&window),
            },
        );
        match out {
            MergeStateGateOutcome::Reject(msg) => {
                assert!(msg.contains("MERGE REQUIRED"), "missing header: {msg}");
                assert!(
                    msg.contains("2 commit(s) from this task"),
                    "both rebased commits name the task; the residue does not: {msg}"
                );
            }
            other => {
                panic!("a rebased, unmerged delivery must not clear the guard, got {other:?}")
            }
        }
        assert_eq!(
            count_task_attributable_unmerged_commits(p, "factory/worker", "main", &window, None),
            Some(2)
        );
    }

    /// cas-08f9 counterpart: a commit that names the task but whose patch is
    /// already on the target (it landed as a cherry-pick) is not stranded work.
    #[test]
    fn task_named_commit_already_on_target_as_an_equivalent_patch_is_not_attributed_cas_08f9() {
        let dir = init_factory_repo("worker");
        let p = dir.path();
        commit_file_with_message_at(
            p,
            "fix.rs",
            "hub-web: the fix (cas-test1)",
            "2026-08-04T12:00:00Z",
        );
        let delivered = head_sha(p);
        git(p, &["checkout", "-q", "main"]);
        git_at(p, &["cherry-pick", &delivered], "2026-08-04T13:00:00Z");
        git(p, &["checkout", "-q", "factory/worker"]);

        let task = worker_task("worker");
        let mut window = window_at(1_800_000_000, "latest task lease claim/transfer");
        window.identity = task_commit_identity(&task, None);
        assert_eq!(
            count_task_attributable_unmerged_commits(p, "factory/worker", "main", &window, None),
            Some(0)
        );
        // A message naming another task (a longer id) is never attributed.
        commit_file_with_message_at(
            p,
            "other.rs",
            "fix: unrelated (cas-test10)",
            "2026-08-04T14:00:00Z",
        );
        assert_eq!(
            count_task_attributable_unmerged_commits(p, "factory/worker", "main", &window, None),
            Some(0)
        );
    }

    /// cas-08f9: the QA backstop's "cannot tell which commit" refusal never
    /// claims a merge when the branch tip is not on the target.
    #[test]
    fn unresolved_delivery_refusal_never_claims_an_unmerged_branch_merged_cas_08f9() {
        let tip = "59f25d1ac0000000000000000000000000000000";
        let refusal = super::super::qa_dispatch::unresolved_delivery_refusal(
            "cas-1622",
            "epic/burn-down",
            "factory/proud-shark-78",
            Some(tip),
            "remedy",
        );
        assert!(!refusal.contains("merged into epic/burn-down"), "{refusal}");
        assert!(
            refusal.contains("is not contained in epic/burn-down, so it is not merged"),
            "{refusal}"
        );
        assert!(
            refusal.contains(&format!("commit_receipt={tip}")),
            "{refusal}"
        );
        let missing = super::super::qa_dispatch::unresolved_delivery_refusal(
            "cas-1622",
            "epic/burn-down",
            "factory/gone",
            None,
            "remedy",
        );
        assert!(missing.contains("does not resolve here"), "{missing}");
    }

    /// GH #849: `request_changes` deliberately clears the active parked
    /// anchor before the worker starts a fresh lease.  The declined delivery
    /// is still this task's work, however; it must not become anonymous lane
    /// residue merely because its commit predates the new lease.  This is the
    /// pure gate shape from the production report (the factory tip is
    /// unmerged on the target, regardless of whether an external PR is open).
    #[test]
    fn request_changes_fresh_cycle_still_rejects_prior_unmerged_delivery_gh_849() {
        let dir = init_factory_repo("worker");
        let p = dir.path();
        commit_file_at(
            p,
            "declined.rs",
            "// declined delivery remains unmerged\n",
            "2026-08-17T21:00:00Z",
        );

        let cas_root = tempfile::tempdir().unwrap();
        let task_store = cas_store::SqliteTaskStore::open(cas_root.path()).unwrap();
        cas_store::TaskStore::init(&task_store).unwrap();
        let mut parked = worker_task("worker");
        parked.status = TaskStatus::AwaitingMerge;
        parked.deliverables.factory_branch_anchor = Some(head_sha(p));
        parked.deliverables.parked_branch = Some("factory/worker".to_string());
        cas_store::TaskStore::add(&task_store, &parked).unwrap();
        cas_store::request_changes_for_parked_delivery(
            cas_root.path(),
            &parked.id,
            "supervisor",
            "The delivery needs correction before re-delivery.",
        )
        .unwrap();

        // Model the real worker start after the supervisor's request_changes:
        // the active anchor is gone, but this remains the same task and the
        // existing delivery commit is still on its factory branch.
        let mut task = cas_store::TaskStore::get(&task_store, &parked.id).unwrap();
        assert!(task.deliverables.factory_branch_anchor.is_none());
        assert_eq!(
            task.deliverables
                .historical_factory_branch_anchors
                .as_slice(),
            [parked.deliverables.factory_branch_anchor.clone().unwrap()]
        );
        task.status = TaskStatus::InProgress;
        cas_store::TaskStore::update(&task_store, &task).unwrap();
        task = cas_store::TaskStore::get(&task_store, &parked.id).unwrap();

        let req = base_req(&task.id);
        // `request_changes` clears the active anchor and `task start` moves
        // the attribution window past this already-produced commit.  The
        // current implementation therefore reproduces the production false
        // Proceed unless this commit remains durable task identity.
        let mut window = window_at(1_800_000_000, "latest task lease claim/transfer");
        window.identity = task_commit_identity(&task, None);
        let out = run_factory_branch_merge_gate_with_attribution(
            &task,
            &req,
            "main",
            p,
            TaskCommitAttribution {
                receipt: None,
                window: Some(&window),
            },
        );
        assert!(
            matches!(out, MergeStateGateOutcome::Reject(_)),
            "a declined delivery still unmerged after request_changes/start must reject close, got {out:?}"
        );

        // The historical identity is not an approval shortcut: once the
        // target actually contains the delivery, the same fresh-cycle task
        // may proceed through the ordinary proof/review gates.
        git(p, &["checkout", "-q", "main"]);
        git(
            p,
            &[
                "merge",
                "-q",
                "--no-ff",
                "factory/worker",
                "-m",
                "merge declined delivery after fresh proof",
            ],
        );
        git(p, &["checkout", "-q", "factory/worker"]);
        assert!(
            matches!(
                run_factory_branch_merge_gate_with_attribution(
                    &task,
                    &req,
                    "main",
                    p,
                    TaskCommitAttribution {
                        receipt: None,
                        window: Some(&window),
                    },
                ),
                MergeStateGateOutcome::Proceed
            ),
            "after the target merge, the fresh-cycle task must pass the merge gate"
        );
    }

    /// A receipt that does not validate (here: not reachable from the parent)
