    /// cas-43d2: a parked push delivery never advances to a commit origin
    /// lacks; once that commit is pushed, the same advance succeeds.
    #[test]
    fn parked_anchor_never_advances_to_an_unpushed_commit_cas_43d2() {
        let dir = init_factory_repo("worker");
        let p = dir.path();
        let bare = tempfile::tempdir().unwrap();
        git(bare.path(), &["init", "-q", "--bare"]);
        git(p, &["remote", "add", "origin", bare.path().to_str().unwrap()]);
        let parked_at = commit_local(p, "a.rs", "task A delivery");
        git(p, &["push", "-q", "origin", "main", "factory/worker"]);
        let mut parked = worker_task("worker");
        parked.id = "cas-a0a0".to_string();
        parked.status = TaskStatus::AwaitingMerge;
        parked.deliverables.factory_branch_anchor = Some(parked_at.clone());
        let own = commit_local(p, "a2.rs", "fix(cas-a0a0): review follow-up");
        let temp = tempfile::tempdir().unwrap();
        let core = CasCore::with_daemon(temp.path().join(".cas"), None, None);
        let store = crate::store::mock::MockTaskStore::with_tasks(vec![parked.clone()]);
        let anchor = |store: &crate::store::mock::MockTaskStore| {
            use cas_store::TaskStore;
            store.get(&parked.id).unwrap().deliverables.factory_branch_anchor
        };
        core.advance_awaiting_merge_anchor(&store, &parked, p, "main", Some(&own)).unwrap();
        assert_eq!(anchor(&store), Some(parked_at), "an unpushed commit is not the delivery");
        git(p, &["push", "-q", "origin", "factory/worker"]);
        // cas-16e1: the lane's own origin branch answers before any scan of
        // every remote ref.
        let trace = temp.path().join("git-trace.log");
        let mut env = crate::test_support::TestEnvGuard::new();
        env.set("GIT_TRACE", &trace);
        core.advance_awaiting_merge_anchor(&store, &parked, p, "main", Some(&own)).unwrap();
        drop(env);
        assert_eq!(anchor(&store), Some(own), "the pushed continuation advances it");
        let scans = std::fs::read_to_string(&trace).unwrap_or_default().lines()
            .filter(|line| line.contains("for-each-ref") && line.contains("refs/remotes/origin")).count();
        assert_eq!(scans, 0);
    }

    /// cas-ba4a: a parked task resolves to its anchor; an anchor that cannot
    /// be resolved (and cannot be fetched) refuses with a named reason
    /// instead of substituting the live lane.
    #[test]
    fn parked_delivery_head_is_the_anchor_or_a_named_refusal_cas_ba4a() {
        let dir = init_factory_repo("worker");
        let p = dir.path();
        let parked_at = commit_local(p, "a.rs", "task A delivery");
        commit_local(p, "b.rs", "next task");
        let mut task = worker_task("worker");
        task.deliverables.factory_branch_anchor = Some(parked_at.clone());
        assert_eq!(parked_delivery_head(p, &task), Ok(None), "not parked");

        task.status = TaskStatus::AwaitingMerge;
        assert_eq!(parked_delivery_head(p, &task), Ok(Some(parked_at)));

        task.deliverables.factory_branch_anchor = Some("d".repeat(40));
        let refusal = parked_delivery_head(p, &task).unwrap_err();
        assert!(refusal.contains("PARKED DELIVERY UNRESOLVED"), "{refusal}");
        assert!(refusal.contains("no origin remote"), "{refusal}");
        assert!(refusal.contains(&"d".repeat(40)), "{refusal}");
    }

    /// GH #819: the worker syncs the current target into its factory branch
    /// before `worktree_merge`, leaving a merge tip with no first-parent tree
    /// effect. The task's earlier first-parent content commits are the
    /// delivery proof; the sync merge itself is not.
    #[test]
    fn merge_tip_uses_task_content_commits_for_delivery_proof_cas_f7c8() {
        let dir = init_factory_repo("worker");
        let p = dir.path();

        std::fs::write(p.join("first.rs"), "// first task change\n").unwrap();
        git(p, &["add", "first.rs"]);
        git(
            p,
            &["commit", "-q", "-m", "feat(cas-test1): first delivery"],
        );
        std::fs::write(p.join("second.rs"), "// second task change\n").unwrap();
        git(p, &["add", "second.rs"]);
        git(
            p,
            &["commit", "-q", "-m", "fix(cas-test1): second delivery"],
        );

        // Advance main independently, then reproduce the worker's sync
        // commit with the same tree content. The following merge is real
        // history but has an empty first-parent tree effect.
        git(p, &["checkout", "-q", "main"]);
        std::fs::write(p.join("target.rs"), "// current target\n").unwrap();
        git(p, &["add", "target.rs"]);
        git(p, &["commit", "-q", "-m", "advance integration target"]);
        git(p, &["checkout", "-q", "factory/worker"]);
        std::fs::write(p.join("target.rs"), "// current target\n").unwrap();
        git(p, &["add", "target.rs"]);
        git(p, &["commit", "-q", "-m", "sync integration target"]);
        git(
            p,
            &[
                "merge",
                "-q",
                "--no-ff",
                "main",
                "-m",
                "sync current integration target",
            ],
        );
        let merge_tip = rev_parse_local(p, "HEAD");
        assert!(
            git_command(
                p,
                &["diff", "--quiet", &format!("{merge_tip}^1"), &merge_tip],
            )
            .status()
            .expect("git diff")
            .success(),
            "precondition: the target-sync merge tip has no first-parent tree effect"
        );

        // Mirrors worktree_merge: the target branch now contains the worker
        // merge tip, but its first-parent tree effect remains empty.
        git(p, &["checkout", "-q", "main"]);
        git(
            p,
            &[
                "merge",
                "-q",
                "--no-ff",
                "factory/worker",
                "-m",
                "merge worker delivery",
            ],
        );
        assert!(git_commit_is_ancestor(p, &merge_tip, "main"));
        assert!(matches!(
            delivery_content_presence_on_target(p, &merge_tip, "main"),
            DeliveryContentPresence::Unknown { ref reason }
                if reason.contains("no first-parent tree effect")
        ));

        let mut task = worker_task("worker");
        task.status = TaskStatus::AwaitingMerge;
        task.deliverables.factory_branch_anchor = Some(merge_tip);
        let req = base_req(&task.id);
        assert!(
            matches!(
                run_factory_branch_merge_gate(&task, &req, "main", p),
                MergeStateGateOutcome::Proceed
            ),
            "a target-sync merge tip must be proven from task content commits"
        );
    }

    /// GH #895: GitHub updates a worker branch by merging the target into it,
    /// then the target accepts the PR and an unrelated commit. The receipt
    /// names the worker's last content commit, not the target-sync merge tip.
    #[test]
    fn receipt_survives_target_sync_merge_and_later_unrelated_target_commit_gh895() {
        let dir = init_factory_repo("worker");
        let p = dir.path();
        let upload = "apps/frontend/app/src/composables/useUpload.ts";
        std::fs::create_dir_all(p.join("apps/frontend/app/src/composables")).unwrap();
        std::fs::write(p.join(upload), "export const upload = 1;\n").unwrap();
        git(p, &["add", upload]);
        git(p, &["commit", "-q", "-m", "feat(cas-test1): add upload"]);
        std::fs::write(p.join(upload), "export const upload = 2;\n").unwrap();
        git(p, &["add", upload]);
        git(p, &["commit", "-q", "-m", "fix(cas-test1): finish upload"]);
        let receipt = rev_parse_local(p, "HEAD");

        git(p, &["checkout", "-q", "main"]);
        std::fs::write(p.join("en.json"), "{}\n").unwrap();
        git(p, &["add", "en.json"]);
        git(p, &["commit", "-q", "-m", "advance target for CI"]);
        git(p, &["checkout", "-q", "factory/worker"]);
        git(p, &["merge", "-q", "--no-ff", "main", "-m", "update worker branch"]);
        let merge_tip = rev_parse_local(p, "HEAD");
        assert!(
            git_command(p, &["diff", "--quiet", &format!("{merge_tip}^1"), &merge_tip, "--", upload])
                .status()
                .unwrap()
                .success(),
            "target-sync merge must not itself change the delivery path"
        );

        git(p, &["checkout", "-q", "main"]);
        git(p, &["merge", "-q", "--no-ff", "factory/worker", "-m", "accept delivery"]);
        std::fs::write(p.join("en.json"), "{\"later\":true}\n").unwrap();
        git(p, &["add", "en.json"]);
        git(p, &["commit", "-q", "-m", "unrelated locale edit"]);

        let mut task = worker_task("worker");
        task.status = TaskStatus::AwaitingMerge;
        task.deliverables.factory_branch_anchor = Some(merge_tip.clone());
        let mut req = base_req(&task.id);
        req.commit_receipt = Some(receipt.clone());
        let window = window_at(0, "GH #895 receipt regression");
        assert!(validate_task_commit_receipt(p, &receipt, "main", &window).is_ok());
        assert_eq!(
            delivery_content_anchor_at_close(p, &merge_tip, "factory/worker", "main", Some(&receipt)),
            receipt
        );
        assert!(matches!(
            run_factory_branch_merge_gate_with_attribution(
                &task,
                &req,
                "main",
                p,
                TaskCommitAttribution {
                    receipt: Some(&receipt),
                    window: Some(&window),
                },
            ),
            MergeStateGateOutcome::Proceed
        ));
    }

    /// GH #840: a worker's own conflict-resolution merge can intentionally
    /// replace the hunks from an earlier task commit before the final worker
    /// tip is merged. That merge resolution is task content, not a dropped
    /// delivery, even though the original non-merge commit's exact patch no
    /// longer applies to the target tree.
    #[test]
    fn worker_merge_resolution_supersedes_earlier_content_without_drop_gh_840() {
        let dir = init_factory_repo("worker");
        let p = dir.path();

        std::fs::write(
            p.join("conversation-history.ts"),
            "export type MessageReceipt = { id: string };\n",
        )
        .unwrap();
        git(p, &["add", "conversation-history.ts"]);
        git(
            p,
            &[
                "commit",
                "-q",
                "-m",
                "feat(cas-test1): add conversation history",
            ],
        );

        // The integration target independently adds the same path, forcing
        // the worker's target-sync merge to carry an explicit resolution.
        git(p, &["checkout", "-q", "main"]);
        std::fs::write(
            p.join("conversation-history.ts"),
            "export type MessageReceipt = { source: string };\n",
        )
        .unwrap();
        git(p, &["add", "conversation-history.ts"]);
        git(
            p,
            &["commit", "-q", "-m", "feat: advance integration history"],
        );
        git(p, &["checkout", "-q", "factory/worker"]);
        let merge = git_command(
            p,
            &[
                "merge",
                "--no-ff",
                "main",
                "-m",
                "Merge branch 'main' into factory/worker",
            ],
        )
        .status()
        .expect("start worker target-sync merge");
        assert!(!merge.success(), "fixture must produce a merge conflict");
        std::fs::write(
            p.join("conversation-history.ts"),
            "export type MessageQueued = { id: string };\n",
        )
        .unwrap();
        git(p, &["add", "conversation-history.ts"]);
        git(
            p,
            &[
                "commit",
                "-q",
                "-m",
                "Merge branch 'main' into factory/worker",
            ],
        );

        // Keep a later ordinary task commit in the same worker branch, then
        // merge another target-only change to make the recorded anchor a
        // merge tip, matching the delivery shape from GH #840.
        std::fs::write(p.join("follow-up.rs"), "pub fn follow_up() {}\n").unwrap();
        git(p, &["add", "follow-up.rs"]);
        git(
            p,
            &["commit", "-q", "-m", "fix(cas-test1): add follow-up"],
        );
        let later_content = rev_parse_local(p, "HEAD");
        git(p, &["checkout", "-q", "main"]);
        std::fs::write(p.join("target-only.rs"), "// target-only\n").unwrap();
        git(p, &["add", "target-only.rs"]);
        git(p, &["commit", "-q", "-m", "chore: advance target again"]);
        git(p, &["checkout", "-q", "factory/worker"]);
        git(
            p,
            &[
                "merge",
                "-q",
                "--no-ff",
                "main",
                "-m",
                "Merge branch 'main' into factory/worker",
            ],
        );
        let worker_tip = rev_parse_local(p, "HEAD");

        git(p, &["checkout", "-q", "main"]);
        git(
            p,
            &[
                "merge",
                "-q",
                "--no-ff",
                "factory/worker",
                "-m",
                "merge worker delivery",
            ],
        );

        let mut task = worker_task("worker");
        task.status = TaskStatus::AwaitingMerge;
        task.deliverables.factory_branch_anchor = Some(worker_tip);
        let req = base_req(&task.id);
        assert!(
            matches!(
                run_factory_branch_merge_gate(&task, &req, "main", p),
                MergeStateGateOutcome::Proceed
            ),
            "a worker-owned merge resolution must count as delivered task content"
        );

        // A validated receipt may name that later content commit directly;
        // the merge-tip proof must honor it as the delivery boundary too.
        let receipt_window = window_at(0, "GH #840 receipt regression");
        let mut receipt_req = base_req(&task.id);
        receipt_req.commit_receipt = Some(later_content.clone());
        assert!(matches!(
            run_factory_branch_merge_gate_with_attribution(
                &task,
                &receipt_req,
                "main",
                p,
                TaskCommitAttribution {
                    receipt: Some(&later_content),
                    window: Some(&receipt_window),
                },
            ),
            MergeStateGateOutcome::Proceed
        ));
    }

    /// cas-3f8c, the cas-bf07 shape: an earlier task commit added
    /// `headerLatencyLabel`, and the same task's later commit replaced it with
    /// `headerConnectionChip`. The worker then synced the target, the
    /// delivery merged, and a later target commit extended the import line.
    /// The earlier commit's hunk was rewritten by the task itself, so it is
    /// not dropped delivery content.
    #[test]
    fn a_hunk_the_same_task_later_rewrote_is_not_dropped_content_cas_3f8c() {
        let dir = init_factory_repo("worker");
        let p = dir.path();
        let commit_main_ts = |body: &str, message: &str| {
            std::fs::write(p.join("main.ts"), body).unwrap();
            git(p, &["add", "main.ts"]);
            git(p, &["commit", "-q", "-m", message]);
        };
        commit_main_ts(
            "import { attach, headerLatencyLabel } from \"./connection-state\";\nexport const latency = headerLatencyLabel();\n",
            "fix(cas-test1): say Checking until the first latency sample",
        );
        commit_main_ts(
            "import { attach, headerConnectionChip } from \"./connection-state\";\nexport const latency = headerConnectionChip();\n",
            "fix(cas-test1): header chip reads the machine's state",
        );
        git(p, &["checkout", "-q", "main"]);
        std::fs::write(p.join("target-only.rs"), "// target-only\n").unwrap();
        git(p, &["add", "target-only.rs"]);
        git(p, &["commit", "-q", "-m", "chore: advance target"]);
        git(p, &["checkout", "-q", "factory/worker"]);
        git(
            p,
            &[
                "merge",
                "-q",
                "--no-ff",
                "main",
                "-m",
                "Merge branch 'main' into factory/worker",
            ],
        );
        let worker_tip = rev_parse_local(p, "HEAD");
        git(p, &["checkout", "-q", "main"]);
        git(
            p,
            &[
                "merge",
                "-q",
                "--no-ff",
                "factory/worker",
                "-m",
                "merge worker delivery",
            ],
        );
        // A later target change extends the delivered import line, so the
        // merge tip no longer matches the target for this path.
        commit_main_ts(
            "import { attach, headerConnectionChip, type AttachSnapshot } from \"./connection-state\";\nexport const latency = headerConnectionChip();\n",
            "feat: extend the connection-state import",
        );

        let mut task = worker_task("worker");
        task.status = TaskStatus::AwaitingMerge;
        task.deliverables.factory_branch_anchor = Some(worker_tip);
        let req = base_req(&task.id);
        let outcome = run_factory_branch_merge_gate(&task, &req, "main", p);
        assert!(
            matches!(outcome, MergeStateGateOutcome::Proceed),
            "a hunk the task rewrote itself must not read as dropped: {outcome:?}"
        );
    }

    #[test]
    fn stale_merge_cannot_resurrect_lost_line_ownership_cas_0930() {
        let dir = init_factory_repo("worker");
        let p = dir.path();
        std::fs::write(p.join("work.rs"), "legacy();\nkeep();\n").unwrap();
        git(p, &["add", "work.rs"]);
        git(p, &["commit", "-qm", "cas-test1: delivery"]);
        let delivery = head_sha(p);
        git(p, &["checkout", "main"]);
        git(p, &["merge", "--no-ff", "-s", "ours", "factory/worker", "-m", "stale integration"]);
        // A stale side copies identical text without owning delivery.
        // A later edit of that copy must not resurrect the dropped line.
        git(p, &["checkout", "-b", "stale", &format!("{delivery}^1")]);
        std::fs::write(p.join("work.rs"), "legacy();\nkeep();\nunrelated();\n").unwrap();
        git(p, &["add", "work.rs"]);
        git(p, &["commit", "-qm", "stale side"]);
        git(p, &["checkout", "main"]);
        git(p, &["merge", "--no-ff", "stale", "-m", "merge stale side"]);
        std::fs::write(p.join("work.rs"), "modern();\nkeep();\nunrelated();\n").unwrap();
        git(p, &["add", "work.rs"]);
        git(p, &["commit", "-qm", "replace delivered line"]);
        assert_eq!(delivery_content_presence_on_target(p, &delivery, "main"),
            DeliveryContentPresence::Dropped { paths: vec!["work.rs".into()] });
    }

