    /// cas-90d8 (cas-07c9 shape): the delivered release-notes draft lands in
    /// a merge, then `release: vX` renames it to the cut date and rewrites
    /// only its date line. The delivered lines survive at the new path, so a
    /// receipt naming the merge must not read as DELIVERY CONTENT DROPPED.
    #[test]
    fn renamed_delivery_file_keeps_its_content_cas_90d8() {
        let dir = init_factory_repo("worker");
        let p = dir.path();
        let draft = "docs/release-notes/2026-10-16-v9.99.0-slack.md";
        let published = "docs/release-notes/2026-10-17-v9.99.0-slack.md";
        let body = |date: &str| {
            format!(
                "# Cassy v9.99.0\n\nRelease date: {date}\n\n- Close gate measures merge tips.\n- Worker checks reuse seeded targets.\n- Slack threads post in order.\n- Commander shows supervisor updates.\n"
            )
        };
        std::fs::create_dir_all(p.join("docs/release-notes")).unwrap();
        std::fs::write(p.join(draft), body("2026-10-16")).unwrap();
        git(p, &["add", "."]);
        git(p, &["commit", "-qm", "cas-test1: draft v9.99.0 release notes"]);
        git(p, &["checkout", "-q", "main"]);
        git(p, &["merge", "--no-ff", "factory/worker", "-m", "Merge branch 'factory/worker'"]);
        let anchor = head_sha(p);
        git(p, &["mv", draft, published]);
        std::fs::write(p.join(published), body("2026-10-17")).unwrap();
        git(p, &["add", "."]);
        git(p, &["commit", "-qm", "release: v9.99.0"]);

        let mut task = worker_task("worker");
        task.status = TaskStatus::AwaitingMerge;
        task.deliverables.factory_branch_anchor = Some(anchor.clone());
        let mut req = base_req(&task.id);
        req.commit_receipt = Some(anchor.clone());
        let outcome = run_factory_branch_merge_gate_with_attribution(
            &task,
            &req,
            "main",
            p,
            TaskCommitAttribution {
                receipt: Some(&anchor),
                window: None,
            },
        );
        assert!(
            !matches!(outcome, MergeStateGateOutcome::Reject(_)),
            "a renamed delivery whose lines survive must not read as dropped: {outcome:?}"
        );
    }

    /// GH #1404: the worker renames its migration while merging the target,
    /// so the rename belongs to the delivery anchor itself.
    #[test]
    fn migration_renamed_inside_own_anchor_merge_is_delivered_gh1404() {
        let dir = init_factory_repo("worker");
        let p = dir.path();
        let old = "migrations/20261027200000_watched_creators.sql";
        let new = "migrations/20261027210000_watched_creators.sql";
        std::fs::create_dir_all(p.join("migrations")).unwrap();
        std::fs::write(p.join(old), "CREATE TABLE watched_creators (id INT);\n").unwrap();
        git(p, &["add", "."]);
        git(p, &["commit", "-qm", "cas-test1: add watched creators migration"]);
        git(p, &["checkout", "main"]);
        std::fs::write(p.join("sibling.sql"), "CREATE TABLE sibling (id INT);\n").unwrap();
        git(p, &["add", "."]);
        git(p, &["commit", "-qm", "cas-beef: sibling migration"]);
        git(p, &["checkout", "factory/worker"]);
        git(p, &["merge", "--no-ff", "--no-commit", "main"]);
        git(p, &["mv", old, new]);
        git(p, &["commit", "-qm", "cas-test1: sync target and rename migration"]);
        let anchor = head_sha(p);
        git(p, &["checkout", "main"]);
        git(p, &["merge", "--no-ff", "factory/worker", "-m", "integrate delivery"]);

        let mut task = worker_task("worker");
        task.status = TaskStatus::AwaitingMerge;
        task.deliverables.factory_branch_anchor = Some(anchor);
        let req = base_req(&task.id);
        let mut window = window_at(0, "anchor rename");
        window.identity.task_id = Some(task.id.clone());
        let outcome = || run_factory_branch_merge_gate_with_attribution(
            &task, &req, "main", p,
            TaskCommitAttribution { receipt: None, window: Some(&window) },
        );
        let delivered = outcome();
        assert!(
            matches!(delivered, MergeStateGateOutcome::Proceed | MergeStateGateOutcome::ProceedWithNote(_)),
            "the identical migration renamed inside its own anchor must be delivered: {delivered:?}"
        );

        // Reachability and the old path's absence cannot excuse losing the
        // renamed file after integration.
        git(p, &["rm", new]);
        git(p, &["commit", "-qm", "drop renamed migration"]);
        let dropped = outcome();
        assert!(matches!(&dropped, MergeStateGateOutcome::Reject(reason)
            if reason.contains("DELIVERY CONTENT DROPPED")), "{dropped:?}");
        // Matching bytes after lost ownership are still not delivery.
        std::fs::create_dir_all(p.join("migrations")).unwrap();
        std::fs::write(p.join(new), "CREATE TABLE watched_creators (id INT);\n").unwrap();
        git(p, &["add", new]);
        git(p, &["commit", "-qm", "unrelated recreation of migration"]);
        let recreated = outcome();
        assert!(matches!(&recreated, MergeStateGateOutcome::Reject(reason)
            if reason.contains("DELIVERY CONTENT DROPPED")), "{recreated:?}");
    }

    /// GH #1160: the final sync anchor comes after two migration renames and
    /// an intentional revert. The old paths are absent at that anchor, but
    /// attribution still measures their earlier task commits as dropped.
    #[test]
    fn reviewed_drop_before_delivery_anchor_closes_cas_f091() {
        let dir = init_factory_repo("worker");
        let p = dir.path();
        let loose = "migrations/receipt.sql";
        let intermediate = "migrations/early/migration.sql";
        let final_path = "migrations/final/migration.sql";
        std::fs::create_dir_all(p.join("migrations")).unwrap();
        std::fs::write(p.join(loose), "CREATE TABLE receipt (id INT);\n").unwrap();
        std::fs::write(p.join("analytics.vue"), "delivered();\n").unwrap();
        git(p, &["add", "."]);
        git(
            p,
            &[
                "commit",
                "-qm",
                "cas-test1: deliver migration and analytics",
            ],
        );
        let introduction = head_sha(p);
        std::fs::create_dir_all(p.join("migrations/early")).unwrap();
        git(p, &["mv", loose, intermediate]);
        git(
            p,
            &[
                "commit",
                "-qm",
                "cas-test1: move migration into Prisma directory",
            ],
        );
        let moved = head_sha(p);
        git(p, &["mv", "migrations/early", "migrations/final"]);
        git(
            p,
            &["commit", "-qm", "cas-test1: rename migration directory"],
        );
        let renamed = head_sha(p);
        git(p, &["rm", "analytics.vue"]);
        git(
            p,
            &[
                "commit",
                "-qm",
                "revert: deliberately retire cas-test1 analytics",
            ],
        );
        let reverted = head_sha(p);
        git(p, &["checkout", "main"]);
        std::fs::write(p.join("sibling.txt"), "sibling\n").unwrap();
        git(p, &["add", "."]);
        git(p, &["commit", "-qm", "cas-sibling: documentation"]);
        git(p, &["checkout", "factory/worker"]);
        git(
            p,
            &[
                "merge",
                "--no-ff",
                "main",
                "-m",
                "cas-test1: sync target before parking",
            ],
        );
        let anchor = head_sha(p);
        git(p, &["checkout", "main"]);
        git(p, &["merge", "--ff-only", "factory/worker"]);
        assert!(!p.join(loose).exists() && !p.join(intermediate).exists());
        assert!(p.join(final_path).exists());
        for receipt in [&moved, &renamed, &reverted] {
            assert!(git_commit_is_ancestor(p, receipt, &anchor));
            assert_ne!(receipt, &anchor);
        }
        let mut task = worker_task("worker");
        task.status = TaskStatus::AwaitingMerge;
        task.deliverables.factory_branch_anchor = Some(anchor.clone());
        let req = base_req(&task.id);
        let mut window = window_at(0, "pre-anchor supersession");
        window.identity.task_id = Some(task.id.clone());
        let outcome = |window: &TaskCommitReceiptWindow| {
            run_factory_branch_merge_gate_with_attribution(
                &task,
                &req,
                "main",
                p,
                TaskCommitAttribution {
                    receipt: None,
                    window: Some(window),
                },
            )
        };
        assert!(
            matches!(outcome(&window), MergeStateGateOutcome::Reject(_)),
            "unreviewed drops must still refuse"
        );
        window.supervisor_override_reason = Some(format!(
            "reviewed-drop: {introduction} -- original delivery is not a replacement"
        ));
        assert!(
            matches!(outcome(&window), MergeStateGateOutcome::Reject(_)),
            "an old path touch without final-state coverage must refuse"
        );
        window.supervisor_override_reason = Some(format!(
            "reviewed-drop: {moved},{renamed} -- analytics is not covered"
        ));
        assert!(
            matches!(outcome(&window), MergeStateGateOutcome::Reject(_)),
            "every dropped path needs a covering commit"
        );
        // cas-90d8: the migration's lines survive both renames, so only the
        // retired analytics file is dropped and needs the reviewed commit.
        window.supervisor_override_reason = Some(format!(
            "reviewed-drop: {reverted} -- reviewed analytics retirement"
        ));
        let result = outcome(&window);
        assert!(
            matches!(&result, MergeStateGateOutcome::ProceedWithNote(note)
            if note.contains("reviewed delivery content supersession accepted")
                && note.contains(&reverted)),
            "pre-anchor reviewed supersession must close: {result:?}"
        );
        let MergeStateGateOutcome::ProceedWithNote(accepted) = result else {
            unreachable!()
        };
        // GH #1401: a closed child's epic row must consume the accepted
        // decision, including when a prior read cached the unreviewed loss.
        task.status = TaskStatus::Closed;
        let report = |task: &Task| {
            let rows = collect_epic_branch_statuses(std::slice::from_ref(task), "main", p);
            let rendered = render_epic_status_report("cas-epic", "main", &rows);
            (rows.into_iter().next().unwrap(), rendered)
        };
        for notes in [
            String::new(),
            window.supervisor_override_reason.clone().unwrap(),
            accepted.replace(&format!("anchor={anchor};"), &format!("anchor={introduction};")),
            accepted.replace(&format!("superseding commits: {reverted};"),
                &format!("superseding commits: {introduction};")),
        ] {
            task.notes = notes;
            let (row, rendered) = report(&task);
            assert!(row.dropped_paths.contains(&"analytics.vue".to_string()), "{rendered}");
            assert!(row.blocks_epic_close(), "{rendered}");
            assert!(rendered.contains("reachable anchor content is absent"), "{rendered}");
        }
        task.notes = format!("[2026-10-28 15:00] {accepted}");
        let (row, rendered) = report(&task);
        assert!(row.dropped_paths.is_empty(), "{rendered}");
        assert!(!row.blocks_epic_close(), "{rendered}");
        let note = row.content_evolution_note.expect("accepted review remains visible");
        assert!(note.contains(&anchor) && note.contains(&reverted), "{note}");
        assert!(!rendered.contains("reachable anchor content is absent"), "{rendered}");
        task.notes.clear();
        assert!(report(&task).0.blocks_epic_close(), "removing acceptance must invalidate the cached verdict");
    }

    #[test]
    fn reviewed_drop_requires_final_target_state_cas_f091() {
        let dir = init_factory_repo("worker");
        let p = dir.path();
        std::fs::write(p.join("work.rs"), "delivered();\n").unwrap();
        git(p, &["add", "."]);
        git(p, &["commit", "-qm", "cas-test1: delivery"]);
        let anchor = head_sha(p);
        git(p, &["checkout", "main"]);
        std::fs::write(p.join("work.rs"), "replacement();\n").unwrap();
        git(p, &["add", "."]);
        git(
            p,
            &["commit", "-qm", "reviewed replacement on sibling branch"],
        );
        let replacement = head_sha(p);
        assert!(!git_commit_is_ancestor(p, &anchor, &replacement));
        assert!(!git_commit_is_ancestor(p, &replacement, &anchor));
        git(
            p,
            &[
                "merge",
                "--no-ff",
                "-s",
                "ours",
                "factory/worker",
                "-m",
                "integrate reviewed replacement",
            ],
        );
        let paths = vec!["work.rs".to_string()];
        let review = format!("reviewed-drop: {replacement} -- reviewed sibling replacement");
        assert!(
            validated_delivery_drop_review(p, &anchor, "main", &paths, None)
                .unwrap()
                .is_none()
        );
        assert!(
            validated_delivery_drop_review(p, &anchor, "main", &paths, Some(&review))
                .unwrap()
                .unwrap()
                .contains(&replacement)
        );
        // The same reachable commit still touches the dropped path, but its
        // state no longer covers the target. It cannot authorize a later loss.
        std::fs::write(p.join("work.rs"), "unreviewed();\n").unwrap();
        git(p, &["add", "."]);
        git(p, &["commit", "-qm", "unreviewed later change"]);
        let error =
            validated_delivery_drop_review(p, &anchor, "main", &paths, Some(&review)).unwrap_err();
        assert!(
            error.contains("final target state") && error.contains("work.rs"),
            "{error}"
        );
    }

    #[test]
    fn delivery_drop_review_requires_reachable_path_receipts_cas_0930() {
        let dir = init_factory_repo("worker");
        let p = dir.path();
        for path in ["work.rs", "other.rs"] {
            std::fs::write(p.join(path), "delivered();\n").unwrap();
        }
        git(p, &["add", "."]);
        git(p, &["commit", "-qm", "cas-test1: delivery"]);
        let delivery = head_sha(p);
        git(p, &["checkout", "main"]);
        git(p, &["merge", "--no-ff", "-s", "ours", "factory/worker", "-m", "reviewed resolution"]);
        let dropping = head_sha(p);
        for path in ["work.rs", "other.rs"] {
            std::fs::write(p.join(path), "reviewed_replacement();\n").unwrap();
        }
        git(p, &["add", "."]);
        git(p, &["commit", "-qm", "replace both dropped paths"]);
        let resolution = head_sha(p);
        let paths = vec!["work.rs".into(), "other.rs".into()];
        assert!(validated_delivery_drop_review(p, &delivery, "main", &paths,
            Some(&format!("reviewed-drop: {dropping} -- invalid dropping merge"))).is_err());
        let review = format!("reviewed-drop: {} -- reviewed replacement", &resolution[..10]);
        let accepted = validated_delivery_drop_review(p, &delivery, "main", &paths, Some(&review))
            .unwrap().unwrap();
        assert!(accepted.contains(&resolution) && accepted.contains(&delivery) && accepted.contains("other.rs"));
        for named in [&delivery, "--all", "deadbeef"] {
            assert!(validated_delivery_drop_review(p, &delivery, "main", &paths,
                Some(&format!("reviewed-drop: {named} -- rejected"))).is_err());
        }
        assert!(validated_delivery_drop_review(p, &delivery, "main", &paths,
            Some("reviewed-drop: narrative without commits")).is_err());
        std::fs::write(p.join("work.rs"), "only one path();\n").unwrap();
        git(p, &["add", "work.rs"]);
        git(p, &["commit", "-qm", "edit one dropped path"]);
        let partial = head_sha(p);
        assert!(validated_delivery_drop_review(p, &delivery, "main", &paths,
            Some(&format!("reviewed-drop: {partial} -- incomplete coverage"))).unwrap_err().contains("other.rs"));
        std::fs::write(p.join("unrelated.rs"), "unrelated();\n").unwrap();
        git(p, &["add", "unrelated.rs"]);
        git(p, &["commit", "-qm", "unrelated"]);
        let unrelated = head_sha(p);
        assert!(validated_delivery_drop_review(p, &delivery, "main", &paths,
            Some(&format!("reviewed-drop: {unrelated} -- wrong path"))).unwrap_err().contains("does not touch"));
        git(p, &["checkout", "-b", "unmerged"]);
        std::fs::write(p.join("work.rs"), "not merged();\n").unwrap();
        git(p, &["add", "work.rs"]);
        git(p, &["commit", "-qm", "unmerged replacement"]);
        let unmerged = head_sha(p);
        assert!(validated_delivery_drop_review(p, &delivery, "main", &paths,
            Some(&format!("reviewed-drop: {unmerged} -- not landed"))).is_err());
    }

