        std::fs::write(p.join("update.rs"), "keep();\nadded();\n").unwrap();
        git(p, &["add", "update.rs"]);
        git(p, &["commit", "-q", "-m", "chore: trim helper"]);
        git(p, &["checkout", "-q", "main"]);
        git(p, &["merge", "-q", "--no-ff", "factory/other", "-m", "Merge branch 'factory/other'"]);
        git(p, &["checkout", "-q", "factory/worker"]);
